// from 'copilot', the Advisor's actual built-in content id, precisely to
// avoid the same slot/content ambiguity this whole scheme exists to
// avoid) meaning "toggle the .mc-copilot aside open/closed"; its button's
// own glyph/label follow whatever content the Advisor position currently
// holds (see computeVisibleEdgeOrder's render loop).
const EDGE_ORDER = ['guide', 'oracle', 'cast', 'faction-events', 'trade', 'documents', 'gallery', 'battlemap', 'hexcrawl', 'dungeoncrawl', 'graph', 'advisor-toggle'];
// The header's own small drawer-tab group, right-aligned in .header-actions
// — same data-drawer-open routing as the edge nav (onClick's [data-drawer-
// open] branch has no idea which container a button lives in), rendered by
// the separate headerTabButtonHTML() below since the header is a compact
// horizontal bar, not the edge nav's vertical icon-tile strip.
const HEADER_ORDER = ['party', 'colony', 'world-tracker', 'journal'];
// Nav buttons whose panel is brought into focus — never closed — when
// clicked, wherever that panel currently lives: an open tab, an anchored
// Storyboard card, or a Storyboard position (direct requests, Party). Their
// button stays in the nav even while the panel fills a position. Close it
// with its own tab ✕ instead.
const FOCUS_ON_REOPEN_DRAWERS = new Set(['party']);

// Rules Profile module gating + Storyboard positions (design/adr/rules-
// profiles-multi-campaign.md). EDGE_ORDER/HEADER_ORDER above are the full,
// ungated candidate lists — computeVisibleEdgeOrder/computeVisibleHeaderOrder
// filter+augment them per the active profile on every render:
//  - a GATEABLE_MODULES id the profile has disabled drops out entirely;
//  - an id currently occupying a Storyboard position drops out of its
//    normal nav slot (it's reachable via the position instead);
//  - 'dashboard'/'narrative'/'copilot' (the built-in Composer/Navigator/
//    Advisor content) surface in the header whenever they are NOT the
//    content filling their own position — "move the current three to the
//    top navigation" when something else takes over a position.
// BUILTIN_POSITION_IDS = the three fixed SLOT names; BUILTIN_CONTENT_IDS =
// the three built-in CONTENT ids each slot points at by default — a
// deliberately separate namespace (domain/rulesProfiles.js's
// resolvePositionContentId/BUILTIN_SLOT_CONTENT). Conflating them was a
// real reported bug: a freed built-in's own top-nav button resolved
// through the SLOT mapping instead of rendering itself, so — once a
// profile reassigned the slot elsewhere (5PFH's Composer -> Colony) —
// clicking "Composer" in the top nav kept showing Colony instead of the
// actual Composer/Dashboard content the button was labeled with.
const BUILTIN_POSITION_IDS = ['composer', 'navigator', 'advisor'];
const BUILTIN_CONTENT_IDS = ['dashboard', 'narrative', 'copilot'];
function positionContentIds(profile) {
  if (!profile) return new Set();
  return new Set(BUILTIN_POSITION_IDS.map((slot) => resolvePositionContentId(profile, slot)));
}
function computeVisibleEdgeOrder(profile) {
  const positioned = positionContentIds(profile);
  return EDGE_ORDER.filter((id) => {
    if (id === 'advisor-toggle') return true; // aside toggle always present; its content follows the Advisor position
    if (!isModuleVisible(profile, id)) return false;
    return !positioned.has(id);
  });
}
function computeVisibleHeaderOrder(profile) {
  const positioned = positionContentIds(profile);
  // FOCUS_ON_REOPEN_DRAWERS ids (Party) keep their button even while filling a
  // position — clicking it goes to that position (focusDrawerPanel).
  const base = HEADER_ORDER.filter((id) => isModuleVisible(profile, id) && (!positioned.has(id) || FOCUS_ON_REOPEN_DRAWERS.has(id)));
  const freedBuiltins = BUILTIN_CONTENT_IDS.filter((id) => !positioned.has(id));
  return [...base, ...freedBuiltins];
}
// Resolve a content id (built-in dashboard/narrative/copilot, or any real
// DRAWERS id) into real HTML. Lives here (not workspace/index.js or
// drawers/index.js) because it's the one place that can import all three
// content sources — composerBodyHtml/navigatorBodyHtml (workspace/
// index.js), renderCopilot (copilotPanel.js), and renderDrawer (drawers/
// index.js) — without creating a circular import between those files
// (drawers/index.js -> workspace/index.js already runs the other way via
// factionEvents.js's shared helpers). Callers pass an already-resolved
// content id — a raw SLOT id ('composer'/'navigator'/'advisor') must go
// through resolvePositionContentId first (see resolveSlotContentId below).
function renderPositionContent(contentId, doc, ui) {
  if (contentId === 'dashboard') return composerBodyHtml(doc, ui);
  if (contentId === 'narrative') return navigatorBodyHtml(doc, ui);
  if (contentId === 'copilot') return renderCopilot(doc, ui);
  if (contentId === 'faction-events') {
    return renderFactionEvents(doc, { factionEventsDrafts, factionEventsFactionFilterId, factionEventsLocationFilterId, factionEventsStepFactionId, factionRoundHistoryOpen, conflictEscalationSuggestions });
  }
  if (!isModuleVisible(store.getActiveProfile(), contentId)) return '';
  return renderDrawer(contentId, doc, ui);
}
// Panel anchoring (see anchoredPanels' own declaration): an anchored id
// always wins over the profile's own baseline content for that slot — the
// LAST anchored entry sits in Navigator (nearest the navbar), the one
// before it (if a second is anchored) gets pushed to Composer. Each
// overridden card's title grows a "⇤ Return to tab strip" control so
// un-anchoring is reachable from right where the content actually is, not
// just back at its original tab.
function renderStoryboardGrid(doc, ui, profile) {
  const anchoredComposerId = anchoredPanels.length >= 2 ? anchoredPanels[anchoredPanels.length - 2] : null;
  const anchoredNavigatorId = anchoredPanels.length >= 1 ? anchoredPanels[anchoredPanels.length - 1] : null;
  let composerContentId = anchoredComposerId || resolvePositionContentId(profile, 'composer');
  const navigatorContentId = anchoredNavigatorId || resolvePositionContentId(profile, 'navigator');
  // Direct bug report: "The Campaign Turn functionality on Navigator
  // should only be on the panel once. It appears duplicated now." Root
  // cause: the Storyboard Positions settings (Rulesets tab) let a GM
  // assign the SAME content (e.g. "Navigator") to BOTH the Composer and
  // Navigator position dropdowns independently, with nothing stopping it
  // — rendering the identical card (same Campaign Turn stepper, same Turn
  // Step text) twice side by side. Rather than also policing this at every
  // place a position gets assigned/saved, this one spot both slots always
  // render through is the simplest place to guarantee it can't happen:
  // Composer (not Navigator — the report is specifically that Navigator's
  // own content should keep showing) falls back to its own true default
  // ('dashboard') whenever it would otherwise duplicate whatever Navigator
  // is already showing.
  if (composerContentId === navigatorContentId) composerContentId = BUILTIN_SLOT_CONTENT.composer;
  const titleWithUnanchor = (label, anchoredId) => anchoredId
    ? `${escapeHtml(label)}${anchoredId === 'battlemap' ? battlemapSpanControlsHtml() : ''} <button type="button" class="icon-btn storyboard-unanchor" data-storyboard-unanchor="${escapeHtml(anchoredId)}" title="Return to the tab strip" aria-label="Return to the tab strip">⇤</button>`
    : escapeHtml(label);
  const composerLabel = titleWithUnanchor((drawerMeta(composerContentId) || DRAWER_META.composer).label, anchoredComposerId);
  const navigatorLabel = titleWithUnanchor((drawerMeta(navigatorContentId) || DRAWER_META.navigator).label, anchoredNavigatorId);
  // An anchored Battlemap widened to 2 or 3 sections takes the whole grid
  // (2 = both Storyboard columns; 3 = also over the right-hand column).
  const wideBattlemapSlot = battlemapSpan >= 2 && !isCompactTab()
    ? (anchoredNavigatorId === 'battlemap' ? 'navigator' : anchoredComposerId === 'battlemap' ? 'composer' : null) : null;
  if (wideBattlemapSlot) {
    const label = wideBattlemapSlot === 'navigator' ? navigatorLabel : composerLabel;
    return `<div class="storyboard-grid">${positionCardHtml(label, renderPositionContent('battlemap', doc, ui), 'battlemap-card storyboard-span-' + battlemapSpan)}</div>`;
  }
  return `<div class="storyboard-grid">${positionCardHtml(composerLabel, renderPositionContent(composerContentId, doc, ui), anchoredComposerId === 'battlemap' ? 'battlemap-card' : '')}${positionCardHtml(navigatorLabel, renderPositionContent(navigatorContentId, doc, ui), 'navigator-card' + (anchoredNavigatorId === 'battlemap' ? ' battlemap-card' : ''))}</div>`;
}
// A Storyboard SLOT id ('composer'/'navigator'/'advisor') resolves through
// the active profile (resolvePositionContentId) to whatever CONTENT id
// currently fills it — used anywhere a SLOT id shows up as a pinned tab or
// activeDrawer value, so its label/glyph/rendered body reflect the real
// content, not the fixed slot name (e.g. the 5PFH profile's Composer slot
// reads/shows as "Colony"). Any OTHER id (a real content id already, e.g.
// 'dashboard' or 'colony') passes through unresolved — it's not a slot, it
// IS the content.
function resolveSlotContentId(id, profile) {
  if (!BUILTIN_POSITION_IDS.includes(id)) return id;
  return resolvePositionContentId(profile, id);
}
function currentEditingProfileId() {
  if (settingsSelectedProfileId && store.listProfiles().some((p) => p.id === settingsSelectedProfileId)) return settingsSelectedProfileId;
  return configCampaignProfileId();
}

// The campaign Settings → Campaigns is configuring — picked in that tab's
// own dropdown, independent of the ACTIVE campaign (picking one there
// never switches; only the header switcher does). Falls back to the active
// campaign when nothing is picked or the pick no longer exists (deleted).
// Every edit in that tab writes through store.updateCampaign(), which for
// the active campaign is the ordinary live update(), so it shows at once.
function configCampaignId() {
  const campaigns = store.listCampaigns();
  if (settingsCampaignId && campaigns.some((c) => c.id === settingsCampaignId)) return settingsCampaignId;
  const active = campaigns.find((c) => c.active);
  return active ? active.id : null;
}
function configCampaignProfileId() {
  const entry = store.listCampaigns().find((c) => c.id === configCampaignId());
  const profiles = store.listProfiles();
  const p = (entry && profiles.find((x) => x.id === entry.profileId)) || store.getActiveProfile() || profiles[0];
  return p ? p.id : null;
}

// store.update()'s mutator receives the RAW campaign doc — unlike store.get(),
// it does NOT run overlayProfile(), so campaign.turnStepLists is never
// populated there. advanceTurnStep/retreatTurnStep/startNext*CampaignTurn
// need it to resolve which list backs a slot, so this overlays it just for
// the call and strips it back off the result before returning —
// turnStepLists is shared appConfig content and must never actually get
// persisted onto the campaign doc (design/adr/rules-profiles-multi-
// campaign.md's "never persisted back" invariant for every overlaid
// field). Split from applyTurnStepMutation below so a caller that needs to
// chain something else (e.g. addNote) onto the result can still get the
// overlay/strip treatment without a second store.update().
function withTurnStepListsOverlay(campaign, mutatorFn) {
  const withLists = { ...campaign, turnStepLists: store.get().turnStepLists || [] };
  const next = mutatorFn(withLists);
  if (next && Object.prototype.hasOwnProperty.call(next, 'turnStepLists')) {
    const { turnStepLists, ...clean } = next;
    return clean;
  }
  return next;
}
function applyTurnStepMutation(slot, mutatorFn) {
  // Navigator workflow manager: only ever called by a Prev/Next click
  // (never by "Start"/add-to-journal, which has its own clear — see
  // logTurnStepToJournal) — clears this slot's ephemeral map link
  // whenever the current step actually changes, so a map picked for a
  // step the GM has now moved away from doesn't keep showing "under the
  // step" for a DIFFERENT step that happens to become current next.
  if (navigatorStepMapLink[slot]) navigatorStepMapLink = { ...navigatorStepMapLink, [slot]: null };
  return store.update((d) => withTurnStepListsOverlay(d, (c) => mutatorFn(c, slot)));
}
// Shared by the Campaign panel's own "▶ Start" buttons (data-turn-step-
// start et al) AND the Navigator workflow manager's "+ Add to Journal" —
// deliberately the SAME handler for both (they're the same action from two
// surfaces, not two separate implementations). Direct instruction: "When a
// Campaign step involving a location is added to the journal, include the
// map link with the narrative content" — if navigatorStepMapLink has a map
// picked for THIS slot's CURRENT step, a real @[Map Name] mention
// (resolves via domain/mapMentions.js the moment this text is logged) is
// appended before logging, and the ephemeral link is cleared — it's now
// baked into the Journal text, nothing left to show "under the step."
function logTurnStepToJournal(slot) {
  const current = getCurrentTurnStep(store.get(), slot);
  if (!current) return;
  const mapLink = navigatorStepMapLink[slot];
  const text = (mapLink && mapLink.stepId === current.step.id)
    ? `${current.step.text}\n\n🗺️ @[${mapLink.mapName}]`
    : current.step.text;
  const source = `Turn Step — ${current.group.label} ${current.index + 1}/${current.total}`;
  // Starting the step that was JUST logged (the Journal's latest entry is
  // this same step) doesn't log it a second time.
  const journal = store.get().journal || [];
  const last = journal[journal.length - 1];
  if (last && last.source === source && last.text === text) return toast('Already logged — this step is the latest Journal entry');
  if (mapLink && mapLink.stepId === current.step.id) navigatorStepMapLink = { ...navigatorStepMapLink, [slot]: null };
  // Adds the entry without switching over to the Journal tab.
  store.update((d) => addNote(d, text, source));
  toast('Step logged to Journal');
}

// Same fallback shape as store.js's own structuredCloneSafe — most runtimes
// this app targets have a real global structuredClone, but this avoids a
// hard dependency on it.
function cloneProfileSafe(profile) {
  try { return structuredClone(profile); } catch { return JSON.parse(JSON.stringify(profile)); }
}

// --- Ruleset Profile Editor drafts (direct request: explicit Save/Cancel,
// not instant-apply) --------------------------------------------------------
// Seeds a profile's draft from the STORED value the first time it's
// touched this session; every later call returns the SAME draft object
// (further edits mutate it in place via the setX helpers below, each of
// which already returns a new object per the pure-mutator convention —
// this just re-stores whatever they return).
function getProfileDraft(profileId) {
  if (!profileId) return null;
  if (!profileDrafts.has(profileId)) {
    const stored = store.listProfiles().find((p) => p.id === profileId);
    if (!stored) return null;
    profileDrafts.set(profileId, cloneProfileSafe(stored));
  }
  return profileDrafts.get(profileId);
}
function setProfileDraft(profileId, nextDraft) { profileDrafts.set(profileId, nextDraft); }
// Only the three fields a profile draft ever touches are compared — never
// id/name/createdAt/updatedAt, so simply opening the editor (which seeds a
// draft equal to the stored value) never reads as "dirty."
function isProfileDraftDirty(profileId) {
  const draft = profileDrafts.get(profileId);
  if (!draft) return false;
  const stored = store.listProfiles().find((p) => p.id === profileId);
  if (!stored) return false;
  const shape = (p) => JSON.stringify({ storyboardPositions: p.storyboardPositions, moduleEnabled: p.moduleEnabled, ruleset: p.ruleset, crewTasks: p.crewTasks });
  return shape(draft) !== shape(stored);
}
function saveProfileDraft(profileId) {
  const draft = profileDrafts.get(profileId);
  if (!draft) return;
  store.updateProfile(profileId, (stored) => applyProfileDraft(stored, draft));
  profileDrafts.delete(profileId);
  toast('Profile saved');
  render();
}
function cancelProfileDraft(profileId) {
  if (!profileDrafts.has(profileId)) return;
  profileDrafts.delete(profileId);
  render();
}

// data-shift-prompt's generic inline-prompt placeholder text, per shift
// name — a nicety, not a requirement (the fallback `${name}…` reads fine
// for any future shift this gets wired to without needing an entry here).
const SHIFT_PROMPT_PLACEHOLDERS = {
  'Set Objective': 'What is the party trying to accomplish?',
};

