const DUNGEON_ROOM_FALLBACK_PALETTE = { floor: '#4a4a46', wall: '#17140f', decor: '#8a7558' };

exports.DUNGEON_CRAWL_ARCHETYPES = DUNGEON_CRAWL_ARCHETYPES;
exports.DUNGEON_CRAWL_ENTRANCE_ARCHETYPE = DUNGEON_CRAWL_ENTRANCE_ARCHETYPE;
exports.ALL_DUNGEON_CRAWL_ARCHETYPES = ALL_DUNGEON_CRAWL_ARCHETYPES;
