register("src/domain/party.js", function(exports, require){
// party.js — the Party tab: a live roster (NPC entities tagged #character —
// see domain/statblocks.js hasCharacterTag) plus free-form, party-wide
// resource trackers that aren't tied to any one entity (credits, custom
// clocks, timers). Ported from the old prototype's split between an
// entity-driven roster and a generic tracker list (see PROGRESS.md
// ISSUES/FINDINGS #1) — kept as two separate concerns here too, since a
// tracker like "party credits" has no natural entity to live on.

const {listEntities, getEntity} = require("src/domain/entities.js");
const {hasCharacterTag} = require("src/domain/statblocks.js");
const {findProgressDifficulty, STARFORGED_PROGRESS_TRACK_MAX, STARFORGED_MOMENTUM_MIN, STARFORGED_MOMENTUM_MAX, STARFORGED_MOMENTUM_RESET, STARFORGED_SUPPLY_MAX,} = require("src/data/rulesets.js");
const {isGameSystemActivated} = require("src/data/rulesConstitution.js");

function clone(c) { try { return structuredClone(c); } catch { return JSON.parse(JSON.stringify(c)); } }

function ensure(campaign) {
  if (!campaign.party || typeof campaign.party !== 'object') campaign.party = { trackers: [] };
  if (!Array.isArray(campaign.party.trackers)) campaign.party.trackers = [];
  if (campaign.party.sharedGear === undefined) campaign.party.sharedGear = '';
  if (!Array.isArray(campaign.party.sharedAssets)) campaign.party.sharedAssets = [];
  if (!Array.isArray(campaign.party.sharedAssetIds)) campaign.party.sharedAssetIds = [];
  // Relationships (direct follow-up request: "add a Relationships section
  // similar to how used on Entity Editor. This treats the Party as an
  // entity for the mapping purposes") — one-directional, Party-side-only
  // storage: {to, label, type, strength}, same shape a real entity's own
  // `relationships` array uses (entities.js), but never mirrored onto the
  // target entity's own list — "Party" has no real entity record to mirror
  // onto. Starship (direct follow-up request): a single #vehicle-tagged
  // entity reference, exclusively tagged #starship campaign-wide — see
  // setPartyStarship/clearPartyStarship below. starshipCampaignTurn is the
  // Campaign panel's Starship tab's own independent turn counter (no
  // Planetfall accrual — direct follow-up request).
  if (!Array.isArray(campaign.party.relationships)) campaign.party.relationships = [];
  if (campaign.party.starshipEntityId === undefined) campaign.party.starshipEntityId = null;
  if (campaign.party.starshipCampaignTurn === undefined) campaign.party.starshipCampaignTurn = 0;
  // The Campaign panel's Warband tab (Five Leagues from the Borderlands) —
  // its own independent turn counter, same shape as starshipCampaignTurn
  // above. No warbandEntityId: a warband is the whole roster (already
  // visible via Cast/Party), not one reference-by-id entity like the
  // Starship tab's single-ship picker.
  if (campaign.party.warbandCampaignTurn === undefined) campaign.party.warbandCampaignTurn = 0;
  return campaign.party;
}

/** Party members = NPC entities tagged #character. */
function listPartyMembers(campaign) {
  return listEntities(campaign, ['npc']).filter(hasCharacterTag);
}

/** The member's own statblock fields (across every ENABLED — non-archived
 *  — statblock group they carry: a Character Sheet AND any Bestiary group
 *  at once, since #character NPCs can have both, or even two different
 *  rulesets' Character Sheets at once) whose key matches one of
 *  settings.partyHeadlineFields (case-insensitive) — what the Party
 *  Roster's collapsed member row shows as small right-aligned counters
 *  (direct request: "GM picks per-ruleset which fields surface"). Direct
 *  follow-up request: "whatever is added to 'Party Roster headline
 *  fields' should be checked as a statblock and displayed if present in
 *  any of the enabled character sheets" — ANY field kind (attribute,
 *  track, or plain text) is eligible, not just track fields as this used
 *  to require (a GM naming an attribute like Five Leagues' "Combat Skill"
 *  used to silently never surface here); an ARCHIVED group (the Bestiary/
 *  Character sheet currently swapped OUT of view, see ensureAutoStatblock)
 *  is skipped, since its fields aren't really "present" while hidden.
 *  Order follows settings.partyHeadlineFields, not field/group order, so a
 *  GM's chosen priority (e.g. "Health before Momentum") is honored
 *  regardless of how the underlying groups are sorted. Returns {f, gi, fi}
 *  triples — gi/fi index into entity.statblocks exactly like every other
 *  statblock mutator in this app expects. */
function listPartyHeadlineTracks(campaign, entity) {
  const wanted = ((campaign.settings && campaign.settings.partyHeadlineFields) || []).map((s) => s.trim().toLowerCase()).filter(Boolean);
  if (!wanted.length) return [];
  const groups = entity.statblocks || [];
  const found = [];
  groups.forEach((group, gi) => {
    if (group.archived) return;
    (group.fields || []).forEach((f, fi) => {
      if (f && wanted.includes(String(f.key || '').trim().toLowerCase())) found.push({ f, gi, fi });
    });
  });
  return wanted
    .map((name) => found.find(({ f }) => String(f.key || '').trim().toLowerCase() === name))
    .filter(Boolean);
}

function listPartyTrackers(campaign) {
  return ((campaign.party && campaign.party.trackers) || []);
}

// Which Party Tracker NAMES (lowercased) each ruleset's own auto-seed
// function below actually creates — a lookup, not a stored field on the
// tracker itself, since adding a `ruleset` field would be a schema change
// for something fully derivable from the name a GM hasn't renamed away
// from its seeded default (renaming one just means it stops being
// recognized as that ruleset's own, same as any other "matched by name"
// convention this app already uses — e.g. listPartyHeadlineTracks). Direct
// follow-up request ("the trackers on Navigator are for Starforged and
// should be filtered to that ruleset and all rulesets activated would
// have their trackers added to Navigator"): this is what lets the
// Navigator isolate "just Five Leagues' own trackers" out of a party.
// trackers array that may carry more than one ruleset's worth at once
// (ensureParty*Trackers below never removes a prior ruleset's own
// trackers when the GM switches statRuleset away from it).
const RULESET_OWNED_TRACKER_NAMES = {
  starforged: ['momentum', 'supply'],
  fiveleagues: ['gold marks', 'enemy threat', 'enemy plans'],
};

/** Whichever of campaign.party.trackers belong to `rulesetId`, matched by
 *  name against RULESET_OWNED_TRACKER_NAMES. Empty for a ruleset with no
 *  entry there yet (SWN/5PFH/Planetfall have no dedicated Party Tracker
 *  auto-seed of their own today) rather than throwing — callers can treat
 *  "no trackers" and "unrecognized ruleset" identically. */
function listPartyTrackersForRuleset(campaign, rulesetId) {
  const names = RULESET_OWNED_TRACKER_NAMES[rulesetId];
  if (!names) return [];
  return listPartyTrackers(campaign).filter((t) => names.includes(String(t.name || '').trim().toLowerCase()));
}

/** A tracker's kind (and, for a Starforged counter, its difficulty) is fixed
 *  for its lifetime — chosen once at creation, never edited afterward (see
 *  updatePartyTracker below). `max` (meter box count, "usually 5 or 10 in
 *  Starforged" but any size the GM wants) and `difficulty` (a counter, only
 *  when the campaign's stat ruleset is Starforged — one of
 *  data/rulesets.js's STARFORGED_PROGRESS_DIFFICULTIES) are both
 *  creation-time-only for the same reason. `min`/`max` only apply to a
 *  'gauge' (a bidirectional single-position track like Momentum, see
 *  setGaugeTrackerValue below — unlike 'meter', it can go negative and
 *  isn't a fill-from-zero count). */
function addPartyTracker(campaign, { name = 'New Tracker', kind = 'meter', value = 0, max = 5, min = -6, difficulty = '' } = {}) {
  const next = clone(campaign);
  const party = ensure(next);
  const validKind = ['meter', 'counter', 'currency', 'gauge'].includes(kind) ? kind : 'meter';
  const isStarforged = ((next.settings && next.settings.statRuleset) || 'starforged') === 'starforged';
  const rank = validKind === 'counter' && isStarforged ? findProgressDifficulty(difficulty) : null;
  const tracker = {
    id: 'ptrk_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    name, kind: validKind,
    value: Number(value) || 0,
  };
  if (validKind === 'meter') tracker.max = Math.max(1, Number(max) || 5);
  if (validKind === 'gauge') {
    tracker.min = Number.isFinite(Number(min)) ? Number(min) : -6;
    tracker.max = Number.isFinite(Number(max)) ? Number(max) : 10;
    tracker.value = Math.max(tracker.min, Math.min(tracker.max, tracker.value));
  }
  if (rank) tracker.difficulty = rank.id;
  party.trackers.push(tracker);
  return next;
}

/** Click-to-set a gauge tracker (Momentum) directly to n, clamped to its own
 *  [min, max] — unlike setPartyTrackerValue's meter boxes (fill-from-zero,
 *  click-the-filled-box-to-decrement), a gauge shows a single CURRENT
 *  POSITION that can be negative, so every box just sets the value to its
 *  own number outright — no toggle-off ambiguity. */
function setGaugeTrackerValue(campaign, id, n) {
  const next = clone(campaign);
  const party = ensure(next);
  const t = party.trackers.find((x) => x.id === id);
  if (!t || t.kind !== 'gauge') return next;
  const min = Number.isFinite(t.min) ? t.min : -6;
  const max = Number.isFinite(t.max) ? t.max : 10;
  t.value = Math.max(min, Math.min(max, Number(n) || 0));
  return next;
}

/** The 10 (or fewer, if the real range is smaller) consecutive integers to
 *  render as a gauge's boxes — a fixed-size WINDOW onto [min, max] that
 *  always contains the current value, centered on it where the range's own
 *  edges allow. Momentum's real range (-6..10, 17 values) can't all fit in
 *  10 boxes at once, so which box reads "0" shifts position within the
 *  rendered row as the window slides to follow the current value — a
 *  deliberate design choice (direct request), not a limitation glossed
 *  over. Pure/exported so the UI's rendering and this math share one tested
 *  source instead of the window logic living untested in drawers/index.js. */
function gaugeWindow(value, min, max, size = 10) {
  const v = Math.max(min, Math.min(max, Number(value) || 0));
  const span = Math.max(1, Math.min(size, max - min + 1));
  let start = v - Math.floor((span - 1) / 2);
  if (start < min) start = min;
  if (start + span - 1 > max) start = max - span + 1;
  return Array.from({ length: span }, (_, i) => start + i);
}

// Direct follow-up request, supersedes this function's own prior "never
// removed" design: "auto-setup and configure all trackers and shared
// fields in a game system module when that module is activated. Keep it
// in a record of module-specific functionality such that they are removed
// if the campaign or profile is modified or disabled where those
// trackers... are no longer applicable." Every tracker either ensure
// function below creates now carries its own `moduleId` — the ONE thing
// that lets this distinguish "auto-created by a module, safe to tear
// down" from a GM's own hand-added tracker (addPartyTracker, no moduleId
// — NEVER touched by this). Re-activating a module later recreates its
// trackers fresh (value reset to the same starting figure a brand-new
// one gets) rather than restoring whatever the GM had tracked before
// deactivating — an accepted, explicit tradeoff per this request's own
// wording, not an oversight.
/** Auto-populates Momentum (a 'gauge', -6..10, reset value +2) and Supply (a
 *  'meter', 0..5, starting full) onto the Party Tracker list the first time
 *  it's viewed under the Starforged ruleset (direct request) — idempotent
 *  (matched by name, case-insensitive) so it's safe to call on every Party
 *  drawer open rather than needing a one-time migration flag. Starforged
 *  has no Game System Activation gate of its own (always "on"), so
 *  statRuleset itself is the only real "is this the active one" signal —
 *  removes both (by moduleId, not name, so a GM's own same-named tracker
 *  is never caught in this) the moment statRuleset moves away from it. */
function ensurePartyStarforgedTrackers(campaign, settings = campaign.settings) {
  const isStarforged = ((settings && settings.statRuleset) || 'starforged') === 'starforged';
  const next = clone(campaign);
  const party = ensure(next);
  if (!isStarforged) {
    party.trackers = party.trackers.filter((t) => t.moduleId !== 'starforged');
    return next;
  }
  const hasByName = (name) => party.trackers.some((t) => (t.name || '').trim().toLowerCase() === name);
  if (!hasByName('momentum')) {
    party.trackers.push({
      id: 'ptrk_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
      name: 'Momentum', kind: 'gauge', moduleId: 'starforged',
      value: STARFORGED_MOMENTUM_RESET, min: STARFORGED_MOMENTUM_MIN, max: STARFORGED_MOMENTUM_MAX,
    });
  }
  if (!hasByName('supply')) {
    party.trackers.push({
      id: 'ptrk_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
      name: 'Supply', kind: 'meter', moduleId: 'starforged',
      value: STARFORGED_SUPPLY_MAX, max: STARFORGED_SUPPLY_MAX,
    });
  }
  return next;
}

/** Same idempotent-by-name, call-on-every-Party-open shape as
 *  ensurePartyStarforgedTrackers above, for Five Leagues from the
 *  Borderlands (direct follow-up request: "When the campaign ruleset
 *  assigns 5LFB, auto-create the Party trackers for Gold Marks currency
 *  tracker and other trackers common to the ruleset") — three real,
 *  warband-wide (not per-character) mechanics named in the rulebook's own
 *  Campaign Turn sequence (data/turnStepListFiveLeagues.js's own step
 *  text, confirmed against the real PDF): Gold Marks (a 'currency'
 *  tracker — "if the warband has no Gold Marks, check Hard Times," p.81),
 *  Enemy Threat (a 'counter' — "track and escalate the current Enemy
 *  Threat level as the campaign progresses," p.97), and Enemy Plans (a
 *  'counter' — "advance the current Enemy's own scheme per the Enemy
 *  Plans track," p.207). All three start at 0 rather than a guessed
 *  starting figure — a new warband's actual starting Gold Marks (and
 *  Threat/Plans position) depends on the specific scenario/campaign
 *  start the GM is running, not a single fixed rulebook number the way
 *  Starforged's own Momentum reset (+2) or Supply max are. Direct follow-
 *  up request ("auto-setup... when that module is activated... removed
 *  if... disabled") moved the trigger from statRuleset to the real
 *  fiveleagues Game System Activation checkbox itself (Settings →
 *  Licenses) — Five Leagues, unlike Starforged, actually has one — and
 *  all three now get torn down (by moduleId, not name, so a GM's own
 *  same-named tracker is never caught in this) the moment that checkbox
 *  is unchecked, rather than staying forever once created. */
function ensurePartyFiveLeaguesTrackers(campaign, settings = campaign.settings) {
  const isFiveLeaguesActive = isGameSystemActivated({ settings }, 'fiveleagues');
  const next = clone(campaign);
  const party = ensure(next);
  if (!isFiveLeaguesActive) {
    party.trackers = party.trackers.filter((t) => t.moduleId !== 'fiveleagues');
    return next;
  }
  const hasByName = (name) => party.trackers.some((t) => (t.name || '').trim().toLowerCase() === name);
  const newTracker = (name, kind) => ({ id: 'ptrk_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6), name, kind, value: 0, moduleId: 'fiveleagues' });
  if (!hasByName('gold marks')) party.trackers.push(newTracker('Gold Marks', 'currency'));
  if (!hasByName('enemy threat')) party.trackers.push(newTracker('Enemy Threat', 'counter'));
  if (!hasByName('enemy plans')) party.trackers.push(newTracker('Enemy Plans', 'counter'));
  return next;
}

/** Rename only — kind/difficulty/max are creation-time-only (see
 *  addPartyTracker), so they're stripped from any patch here rather than
 *  trusted to a caller that "shouldn't" send them. */
function updatePartyTracker(campaign, id, patch) {
  const next = clone(campaign);
  const party = ensure(next);
  const t = party.trackers.find((x) => x.id === id);
  if (t) {
    const { kind, difficulty, max, min, ...rest } = patch || {};
    Object.assign(t, rest);
  }
  return next;
}

/** Step a counter/currency tracker by delta. A Starforged-difficulty counter
 *  steps by that rank's tick count (Troublesome=12 ... Epic=1, out of a
 *  40-tick track — data/rulesets.js's STARFORGED_PROGRESS_DIFFICULTIES/
 *  STARFORGED_PROGRESS_TRACK_MAX) instead of a plain +1, so it actually
 *  behaves like the Vow/quest progress track it's standing in for. Meters
 *  are click-to-set (see setPartyTrackerValue) and don't step. */
function stepPartyTracker(campaign, id, delta) {
  const next = clone(campaign);
  const party = ensure(next);
  const t = party.trackers.find((x) => x.id === id);
  if (!t || t.kind === 'meter') return next;
  const rank = t.difficulty && findProgressDifficulty(t.difficulty);
  const step = rank ? rank.ticks : 1;
  const raw = (Number(t.value) || 0) + delta * step;
  t.value = rank ? Math.max(0, Math.min(STARFORGED_PROGRESS_TRACK_MAX, raw)) : Math.max(0, raw);
  return next;
}

/** Click-to-set a meter tracker's box (clicking the currently-filled box
 *  clears down by one) — the same interaction as an entity statblock's
 *  track boxes (see domain/statblocks.js's setStatblockTrackValue), now
 *  that a Party meter renders as boxes instead of a numeric ratio. */
function setPartyTrackerValue(campaign, id, n) {
  const next = clone(campaign);
  const party = ensure(next);
  const t = party.trackers.find((x) => x.id === id);
  if (!t || t.kind !== 'meter') return next;
  const max = t.max || 5;
  const target = t.value === n ? n - 1 : n;
  t.value = Math.max(0, Math.min(max, target));
  return next;
}

function removePartyTracker(campaign, id) {
  const next = clone(campaign);
  const party = ensure(next);
  party.trackers = party.trackers.filter((x) => x.id !== id);
  return next;
}

/** Party-wide free-text gear notes (not tied to any one character) —
 *  e.g. a shared toolkit, a ship's medkit. One field, overwritten
 *  wholesale on each edit like every other rich-text field in this app. */
function setPartySharedGear(campaign, text) {
  const next = clone(campaign);
  const party = ensure(next);
  party.sharedGear = String(text || '');
  return next;
}

/** Append a free-text Shared Asset. Mirrors addPartyTracker's shape
 *  (party-level, not entity-level — see entities.js's addFactionAsset
 *  for the entity-scoped equivalent this deliberately does NOT reuse). */
function addPartySharedAsset(campaign, text) {
  const next = clone(campaign);
  const party = ensure(next);
  const clean = String(text || '').trim();
  if (!clean) return next;
  party.sharedAssets.push(clean);
  return next;
}

/** Remove one Shared Asset by index. */
function removePartySharedAsset(campaign, index) {
  const next = clone(campaign);
  const party = ensure(next);
  const i = Number(index);
  if (!Number.isInteger(i) || i < 0 || i >= party.sharedAssets.length) return next;
  party.sharedAssets.splice(i, 1);
  return next;
}

/** A real Asset ENTITY (a vehicle, typically — see the "+Vehicle" picker,
 *  shell.js) linked into Shared Assets, distinct from the plain free-text
 *  strings above — this one renders as a real entity thumbnail (opens the
 *  Entity Editor, shows its Vehicle Statblock) rather than a static chip.
 *  Deliberately a separate array from sharedAssets rather than repurposing
 *  it, since existing campaigns' sharedAssets entries are plain typed
 *  strings with no entity behind them (migration rule 5 — never reinterpret
 *  an existing field's meaning). */
function addPartySharedAssetEntity(campaign, entityId) {
  const next = clone(campaign);
  const party = ensure(next);
  if (entityId && !party.sharedAssetIds.includes(entityId)) party.sharedAssetIds.push(entityId);
  return next;
}

function removePartySharedAssetEntity(campaign, entityId) {
  const next = clone(campaign);
  const party = ensure(next);
  party.sharedAssetIds = party.sharedAssetIds.filter((id) => id !== entityId);
  return next;
}

/** Direct follow-up request: "If an Asset is added to the party and then
 *  changed to 'vehicle' (but was originally added as just an Asset), then
 *  rescan the party shared assets and notify the user it will be removed
 *  since it changed asset type." Called from the Entity Editor's own tag-
 *  input commit (shell.js) right after a tag is added — a no-op unless
 *  `entityId` is BOTH currently linked in Shared Assets AND now tagged
 *  #vehicle (the "+Vehicle" create flow itself tags #vehicle BEFORE
 *  linking the entity here, so it never trips this; only a RETROACTIVE
 *  retag of an already-linked, previously-non-vehicle entity does).
 *  Returns `{ campaign, removed }` rather than just the campaign — shell.js
 *  uses `removed` to decide whether to toast the GM, without having to
 *  separately re-diff sharedAssetIds itself. */
function reconcilePartySharedAssetVehicleTag(campaign, entityId) {
  const party = campaign.party || {};
  const linked = (party.sharedAssetIds || []).includes(entityId);
  if (!linked) return { campaign, removed: false };
  const entity = getEntity(campaign, entityId);
  const isVehicle = !!(entity && (entity.tags || []).includes('vehicle'));
  if (!isVehicle) return { campaign, removed: false };
  return { campaign: removePartySharedAssetEntity(campaign, entityId), removed: true };
}

// --- Party Relationships (direct follow-up request: "add a Relationships
// section similar to how used on Entity Editor. This treats the Party as
// an entity for the mapping purposes") ---------------------------------
// One-directional, Party-side-only: campaign.party.relationships holds
// {to, label, type, strength}, the exact same shape a real entity's own
// relationships array uses (entities.js), and the SAME RELATIONSHIP_TYPES/
// RELATIONSHIP_TYPE_LABEL vocabulary (imported by the UI layer directly,
// not duplicated here) — but never mirrored onto the target entity's own
// list, since "Party" has no real entity record for entities.js's _link to
// push a reverse edge onto.
function clampStrength(n) {
  const v = Math.round(Number(n));
  return Number.isFinite(v) ? Math.max(0, Math.min(10, v)) : 0;
}

/** Adds (or, if one already exists to this target, REPLACES — same "at
 *  most one edge to a given target" invariant a real entity's relationship
 *  list already has) a Party relationship. */
function addPartyRelationship(campaign, targetId, label = 'linked', type = 'linked') {
  const next = clone(campaign);
  const party = ensure(next);
  party.relationships = party.relationships.filter((r) => r.to !== targetId);
  party.relationships.push({ to: targetId, label, type, strength: 0 });
  return next;
}

function removePartyRelationship(campaign, targetId) {
  const next = clone(campaign);
  const party = ensure(next);
  party.relationships = party.relationships.filter((r) => r.to !== targetId);
  return next;
}

function updatePartyRelationshipLabel(campaign, targetId, label) {
  const next = clone(campaign);
  const party = ensure(next);
  const r = party.relationships.find((rel) => rel.to === targetId);
  if (r) r.label = label;
  return next;
}

function updatePartyRelationshipType(campaign, targetId, type) {
  const next = clone(campaign);
  const party = ensure(next);
  const r = party.relationships.find((rel) => rel.to === targetId);
  if (r) r.type = type;
  return next;
}

function updatePartyRelationshipStrength(campaign, targetId, strength) {
  const next = clone(campaign);
  const party = ensure(next);
  const r = party.relationships.find((rel) => rel.to === targetId);
  if (r) r.strength = clampStrength(strength);
  return next;
}

// --- Party Starship (direct follow-up request) -------------------------
// A single #vehicle-tagged entity, exclusively tagged #starship
// campaign-wide (enforced here, not left to the UI): selecting one (a)
// strips #starship from whoever currently holds it — anywhere in
// campaign.entities.items, not just the previous party.starshipEntityId,
// so a manually-mistagged duplicate can never coexist — (b) tags the new
// entity #starship, (c) replaces any existing "Owns" Party relationship
// pointing at the OLD starship with one pointing at the new entity (owns
// already exists in entities.js's RELATIONSHIP_TYPES/expects target type
// 'asset' — no new relationship type needed), (d) sets
// party.starshipEntityId. clearPartyStarship reverses all three side
// effects. Both are single atomic mutators (not a compose-in-the-UI
// pattern) so the tag/relationship/field invariant can never drift apart.
function setPartyStarship(campaign, entityId) {
  const next = clone(campaign);
  const party = ensure(next);
  const items = (next.entities && next.entities.items) || [];
  for (const e of items) {
    if (e.id !== entityId && Array.isArray(e.tags) && e.tags.some((t) => t.toLowerCase() === 'starship')) {
      e.tags = e.tags.filter((t) => t.toLowerCase() !== 'starship');
    }
  }
  const target = items.find((e) => e.id === entityId);
  if (target) {
    if (!Array.isArray(target.tags)) target.tags = [];
    if (!target.tags.some((t) => t.toLowerCase() === 'starship')) target.tags.push('starship');
  }
  // Only the auto-managed "Owns" edge to the OLD starship is dropped — a
  // manually-added, differently-typed Party relationship to that same
  // entity (added via the generic Relationships section before it became
  // the starship) is left alone.
  party.relationships = party.relationships.filter((r) => !(r.type === 'owns' && r.to === party.starshipEntityId));
  if (target) {
    party.relationships = party.relationships.filter((r) => r.to !== entityId);
    party.relationships.push({ to: entityId, label: 'Owns', type: 'owns', strength: 0 });
  }
  party.starshipEntityId = target ? entityId : null;
  return next;
}

/** Detaches the current starship without picking a new one — untags the
 *  entity, drops the Owns relationship, nulls the field. No-op if none is
 *  currently set. */
function clearPartyStarship(campaign) {
  const next = clone(campaign);
  const party = ensure(next);
  if (!party.starshipEntityId) return next;
  const target = getEntity(next, party.starshipEntityId);
  if (target && Array.isArray(target.tags)) target.tags = target.tags.filter((t) => t.toLowerCase() !== 'starship');
  party.relationships = party.relationships.filter((r) => !(r.type === 'owns' && r.to === party.starshipEntityId));
  party.starshipEntityId = null;
  return next;
}

/** Brings a campaign's module-owned Party Trackers in line with its profile:
 *  adds the trackers of a module that's in use, removes those (tagged
 *  moduleId) of one that no longer is. A GM's own trackers are never
 *  touched. `settings` is the profile-overlaid settings (a store.update()
 *  mutator only sees the raw doc). */
function syncModuleTrackers(campaign, settings = campaign.settings) {
  return ensurePartyFiveLeaguesTrackers(ensurePartyStarforgedTrackers(campaign, settings), settings);
}

/** Older campaigns' module trackers were created before trackers carried a
 *  moduleId, so nothing ever removed them when the game system changed.
 *  Tags an untagged tracker whose name is one a module seeds with that
 *  module's id. Idempotent. */
function tagLegacyModuleTrackers(campaign) {
  const trackers = campaign && campaign.party && Array.isArray(campaign.party.trackers) ? campaign.party.trackers : null;
  const moduleFor = (t) => {
    const name = String(t.name || '').trim().toLowerCase();
    return Object.keys(RULESET_OWNED_TRACKER_NAMES).find((m) => RULESET_OWNED_TRACKER_NAMES[m].includes(name));
  };
  if (!trackers || !trackers.some((t) => !t.moduleId && moduleFor(t))) return campaign;
  const next = clone(campaign);
  for (const t of next.party.trackers) {
    if (t.moduleId) continue;
    const moduleId = moduleFor(t);
    if (moduleId) t.moduleId = moduleId;
  }
  return next;
}

exports.listPartyMembers = listPartyMembers;
exports.listPartyHeadlineTracks = listPartyHeadlineTracks;
exports.listPartyTrackers = listPartyTrackers;
exports.listPartyTrackersForRuleset = listPartyTrackersForRuleset;
exports.addPartyTracker = addPartyTracker;
exports.setGaugeTrackerValue = setGaugeTrackerValue;
exports.gaugeWindow = gaugeWindow;
exports.ensurePartyStarforgedTrackers = ensurePartyStarforgedTrackers;
exports.ensurePartyFiveLeaguesTrackers = ensurePartyFiveLeaguesTrackers;
exports.updatePartyTracker = updatePartyTracker;
exports.stepPartyTracker = stepPartyTracker;
exports.setPartyTrackerValue = setPartyTrackerValue;
exports.removePartyTracker = removePartyTracker;
exports.setPartySharedGear = setPartySharedGear;
exports.addPartySharedAsset = addPartySharedAsset;
exports.removePartySharedAsset = removePartySharedAsset;
exports.addPartySharedAssetEntity = addPartySharedAssetEntity;
exports.removePartySharedAssetEntity = removePartySharedAssetEntity;
exports.reconcilePartySharedAssetVehicleTag = reconcilePartySharedAssetVehicleTag;
exports.addPartyRelationship = addPartyRelationship;
exports.removePartyRelationship = removePartyRelationship;
exports.updatePartyRelationshipLabel = updatePartyRelationshipLabel;
exports.updatePartyRelationshipType = updatePartyRelationshipType;
exports.updatePartyRelationshipStrength = updatePartyRelationshipStrength;
exports.setPartyStarship = setPartyStarship;
exports.clearPartyStarship = clearPartyStarship;
exports.syncModuleTrackers = syncModuleTrackers;
exports.tagLegacyModuleTrackers = tagLegacyModuleTrackers;

});

register("src/domain/colony.js", function(exports, require){
// colony.js — the Colony tab: a flat turn-sheet matching the 5PFH Planetfall
// campaign-turn tracker (ported field-for-field from the old prototype, see
// PROGRESS.md ISSUES/FINDINGS #2), a crew roster that references
// character/vehicle entities instead of duplicating their stats, and a live
// filter over #lifeform-tagged entities for tracked encounters.
//
// Deliberately just one ruleset's data module — "genre-aware, not
// genre-locked" means a different colony-sim ruleset gets its own module
// and its own drawer section later, not a hardcoded branch in this one.

const {listEntities, createEntity, getEntity, addEntityStatblockGroup, removeEntityStatblockGroup} = require("src/domain/entities.js");
const {listPartyMembers} = require("src/domain/party.js");
const {freshCrewTaskProgress} = require("src/domain/crewTasks.js");
const {rollLifeformProfile, formatLifeformProfile} = require("src/domain/lifeforms.js");

function clone(c) { try { return structuredClone(c); } catch { return JSON.parse(JSON.stringify(c)); } }

const MAX_ENCOUNTERS = 10;

function ensure(campaign) {
  if (!campaign.colony || typeof campaign.colony !== 'object') campaign.colony = { fields: {}, crew: [], encounters: [] };
  if (!campaign.colony.fields || typeof campaign.colony.fields !== 'object') campaign.colony.fields = {};
  if (!Array.isArray(campaign.colony.crew)) campaign.colony.crew = [];
  if (!Array.isArray(campaign.colony.encounters)) campaign.colony.encounters = [];
  return campaign.colony;
}

// { key, label, type } — type is 'text' | 'number' | 'textarea', purely a
// rendering hint for the drawer.
const COLONY_FIELDS = [
  { key: 'name', label: 'Colony Name', type: 'text' },
  { key: 'campaignTurn', label: 'Campaign Turn', type: 'number' },
  { key: 'campaignMilestones', label: 'Campaign Milestones', type: 'number' },
  { key: 'rosterSize', label: 'Roster Size', type: 'number' },
  { key: 'colonyMorale', label: 'Colony Morale', type: 'number' },
  { key: 'colonyIntegrity', label: 'Colony Integrity', type: 'number' },
  { key: 'buildPointsPerTurn', label: 'Build Points / Turn', type: 'number' },
  { key: 'buildPoints', label: 'Build Points', type: 'number' },
  { key: 'researchPointsPerTurn', label: 'Research Points / Turn', type: 'number' },
  { key: 'researchPoints', label: 'Research Points', type: 'number' },
  { key: 'storyPoints', label: 'Story Points', type: 'number' },
  { key: 'ancientSigns', label: 'Ancient Signs', type: 'number' },
  { key: 'repairCapacity', label: 'Repair Capacity', type: 'number' },
  { key: 'augmentationPoints', label: 'Augmentation Points', type: 'number' },
  { key: 'colonyDefenses', label: 'Colony Defenses', type: 'number' },
  { key: 'rawMaterials', label: 'Raw Materials', type: 'number' },
  { key: 'calamityPoints', label: 'Calamity Points', type: 'number' },
  { key: 'grunts', label: 'Grunts', type: 'number' },
  { key: 'enemyInformation', label: 'Enemy Information', type: 'number' },
  { key: 'missionData', label: 'Mission Data', type: 'number' },
  { key: 'conditionNotes', label: 'Condition Notes', type: 'textarea' },
  { key: 'notes', label: 'Notes', type: 'textarea' },
];

function getColonyFields(campaign) {
  return (campaign.colony && campaign.colony.fields) || {};
}

function setColonyField(campaign, key, value) {
  const next = clone(campaign);
  const colony = ensure(next);
  const def = COLONY_FIELDS.find((f) => f.key === key);
  colony.fields[key] = def && def.type === 'number' ? Number(value) || 0 : value;
  return next;
}

// Campaign Turn / Campaign Milestones (COLONY_FIELDS above) are the ONE
// real "what turn/milestone is it" state for a 5PFH Planetfall campaign —
// the World Tracker module (worldTracker.js) reads/writes these same
// fields via these helpers rather than keeping its own separate counter,
// so a GM never has two different turn numbers to keep in sync by hand.
// Milestones clamp 0-7 (the campaign's fixed win condition) only through
// these dedicated +/- actions — direct edits to the underlying field via
// setColonyField above stay a plain unclamped number, matching every other
// COLONY_FIELDS entry's generic-number-input convention.
function advanceCampaignTurn(campaign) {
  const current = Number(getColonyFields(campaign).campaignTurn) || 0;
  return setColonyField(campaign, 'campaignTurn', current + 1);
}

/** The 5PFH Planetfall Campaign Turn sequence's automatic per-turn
 *  bookkeeping (assets/docs/5PFH/Five Parsecs - Planetfall 1.2.pdf), applied when a new
 *  Campaign Turn starts (direct follow-up request — "add any points/turn
 *  calculations... as per the rulebook"):
 *    - Step 14 (Research) / Step 15 (Building): each stat's own "/Turn"
 *      rate is added onto its running total — Build Points += Build
 *      Points/Turn, Research Points += Research Points/Turn.
 *    - Step 11 (Colony Morale Adjustments): "your Colony Morale score
 *      automatically drops 1 point during this step, regardless of any
 *      actions taken" (p.67) — the rulebook's own wording for an
 *      UNCONDITIONAL drop, distinct from the further -1/battle-casualty
 *      it also describes, which this app has no casualty count to apply
 *      automatically (no such field exists anywhere in this schema).
 *  Story Points and every other COLONY_FIELDS stat (Roster Size, Colony
 *  Integrity, Colony Defenses, Raw Materials, Calamity Points, Grunts,
 *  Ancient Signs, Repair Capacity, Augmentation Points) are deliberately
 *  left untouched — the rulebook ties each of those to a specific
 *  mission/event/purchase (p.55-56), not a flat per-turn rate, so there is
 *  nothing to compute automatically without inventing a rule this app has
 *  no data source for.
 *  Returns { campaign, turn, changes } (not just campaign, matching the
 *  existing rollRandomInvestigationSite/{campaign,...} return shape this
 *  codebase already uses when a caller needs to know what happened, not
 *  just get the new document) — changes is [{key, label, from, to}] for
 *  whichever stats actually changed, for the caller to build one combined
 *  Journal entry from. */
function advanceCampaignTurnWithAccrual(campaign) {
  const before = getColonyFields(campaign);
  let next = advanceCampaignTurn(campaign);
  const turn = Number(getColonyFields(next).campaignTurn) || 0;
  const changes = [];

  const buildRate = Number(before.buildPointsPerTurn) || 0;
  if (buildRate) {
    const from = Number(before.buildPoints) || 0;
    const to = from + buildRate;
    next = setColonyField(next, 'buildPoints', to);
    changes.push({ key: 'buildPoints', label: 'Build Points', from, to });
  }

  const researchRate = Number(before.researchPointsPerTurn) || 0;
  if (researchRate) {
    const from = Number(before.researchPoints) || 0;
    const to = from + researchRate;
    next = setColonyField(next, 'researchPoints', to);
    changes.push({ key: 'researchPoints', label: 'Research Points', from, to });
  }

  const moraleFrom = Number(before.colonyMorale) || 0;
  const moraleTo = moraleFrom - 1;
  next = setColonyField(next, 'colonyMorale', moraleTo);
  changes.push({ key: 'colonyMorale', label: 'Colony Morale', from: moraleFrom, to: moraleTo });

  // Crew Tasks eligibility (design/adr/rules-profiles-multi-campaign.md,
  // direct follow-up request) — "not yet performed a crew task this
  // campaign turn" resets here, alongside every other per-turn bookkeeping
  // this function already does, so both places that actually advance the
  // Campaign Turn (World Tracker's End Turn ▸, and Turn Step's own "start
  // the next Campaign Turn" confirm) clear it for free.
  next.crewTaskProgress = freshCrewTaskProgress();

  return { campaign: next, turn, changes };
}

/** Plain-text Journal note for advanceCampaignTurnWithAccrual's result —
 *  one combined entry covering the turn change and every stat it touched,
 *  per the direct follow-up request ("Make a note of all changes as a
 *  Journal entry"), plus a heads-up once Colony Morale reaches the
 *  rulebook's own -10 "you must test for Colony Morale" threshold (p.67). */
function formatTurnAdvanceNote(turn, changes) {
  const lines = [`Campaign Turn changed to ${turn}.`];
  for (const c of changes) {
    const delta = c.to - c.from;
    lines.push(`${c.label}: ${c.from} → ${c.to} (${delta > 0 ? `+${delta}` : delta}).`);
  }
  const morale = changes.find((c) => c.key === 'colonyMorale');
  if (morale && morale.to <= -10) lines.push('Colony Morale is at -10 or worse — test for Colony Morale (5PFH Planetfall p.89).');
  return lines.join('\n');
}

function incrementCampaignMilestones(campaign) {
  const current = Number(getColonyFields(campaign).campaignMilestones) || 0;
  return setColonyField(campaign, 'campaignMilestones', Math.min(7, current + 1));
}

function decrementCampaignMilestones(campaign) {
  const current = Number(getColonyFields(campaign).campaignMilestones) || 0;
  return setColonyField(campaign, 'campaignMilestones', Math.max(0, current - 1));
}

// Crew Role list — the three character classes 5PFH Planetfall's colony
// roster actually uses (assets/docs/5PFH/Five Parsecs - Planetfall 1.2.pdf, "Your Colony
// Crew"). There is no Pilot/Engineer/Medic/Gunner/Quartermaster/Diplomat
// role table in the book — that was a placeholder guess pending the real
// source, since replaced with the actual class list.
const CREW_ROLES = [
  { id: 'scout', label: 'Scout' },
  { id: 'scientist', label: 'Scientist' },
  { id: 'trooper', label: 'Trooper' },
];

function listCrewRows(campaign) {
  return ((campaign.colony && campaign.colony.crew) || []);
}

function addCrewRow(campaign, { characterId = '', assetId = '', role = '' } = {}) {
  const next = clone(campaign);
  const colony = ensure(next);
  colony.crew.push({ id: 'crew_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6), characterId, assetId, role });
  return next;
}

function updateCrewRow(campaign, id, patch) {
  const next = clone(campaign);
  const colony = ensure(next);
  const row = colony.crew.find((r) => r.id === id);
  if (row) Object.assign(row, patch);
  return next;
}

function removeCrewRow(campaign, id) {
  const next = clone(campaign);
  const colony = ensure(next);
  colony.crew = colony.crew.filter((r) => r.id !== id);
  return next;
}

/** Keeps the Crew Roster's membership in sync with the Party (direct
 *  follow-up request: "adding and removing from Party likewise updates
 *  the Crew Roster") — additive/idempotent, safe to call after ANY entity
 *  or tag change: pushes one blank-role crew row for each current party
 *  member (party.js's listPartyMembers — an NPC tagged #character) not
 *  already represented, and drops any crew row whose characterId no
 *  longer belongs to a current party member. A crew row with no
 *  characterId yet (added the old one-at-a-time way, no member picked
 *  yet) is left alone either way — only rows actually pointing at a
 *  member get pruned. Also IS the Crew Roster's empty-state "+ Crew"
 *  bulk-load action (direct follow-up request) — "add every current
 *  member" and "keep every current member in sync" are the same rule. */
function syncCrewRosterWithParty(campaign) {
  const next = clone(campaign);
  const colony = ensure(next);
  const memberIds = new Set(listPartyMembers(next).map((m) => m.id));
  colony.crew = colony.crew.filter((r) => !r.characterId || memberIds.has(r.characterId));
  const present = new Set(colony.crew.map((r) => r.characterId).filter(Boolean));
  for (const id of memberIds) {
    if (present.has(id)) continue;
    colony.crew.push({ id: `crew_${Date.now().toString(36)}_${id}`, characterId: id, assetId: '', role: '' });
  }
  return next;
}

/** Live filter over entities tagged #lifeform, OR (direct follow-up
 *  request — lifeform is now a peer entity type, entities.js's
 *  ENTITY_TYPES) typed 'lifeform' directly — encounters worth tracking
 *  across a Planetfall campaign, not a separate stored list. Both count so
 *  a campaign that used the old #lifeform-tagged-NPC convention keeps
 *  showing those entries unchanged. */
function listLifeformEncounters(campaign) {
  return listEntities(campaign).filter((e) => e.type === 'lifeform' || (Array.isArray(e.tags) && e.tags.some((t) => /^lifeforms?$/i.test(String(t).trim()))));
}

/** The Colony's own Encounters log (direct follow-up request — "follow the
 *  rules and workflow for Encounters in the 5PFH Planetfall rules"): a
 *  fixed MAX_ENCOUNTERS rows (direct follow-up request — "default to 10
 *  rows"), each a free-text note plus an optional reference to a specific
 *  Lifeform entity once one's been identified in play. Distinct from
 *  listLifeformEncounters() above (an unbounded, automatic filter over
 *  every Lifeform-typed/tagged Cast entity) — this is the GM's own
 *  per-campaign turn-sheet row list, matching the physical 10-row
 *  Encounters table exactly (a fixed grid, not a growable list). A brand
 *  new campaign is seeded with the full 10 rows already (schema.js's
 *  defaultCampaign); an existing campaign with fewer is padded up to 10 by
 *  migrate.js (MAX_ENCOUNTERS, exported below, is that backfill's target
 *  count too — kept in one place so the two can't silently drift apart). */
function listColonyEncounters(campaign) {
  return ((campaign.colony && campaign.colony.encounters) || []);
}

function updateColonyEncounter(campaign, id, patch) {
  const next = clone(campaign);
  const colony = ensure(next);
  const row = colony.encounters.find((r) => r.id === id);
  if (row) Object.assign(row, patch);
  return next;
}

/** Detaches a row's linked Lifeform entity without touching its note or
 *  removing the row itself — rows are a fixed grid now, so there's no
 *  "delete this row" action any more, just clearing what's on it. */
function detachColonyEncounterEntity(campaign, id) {
  return updateColonyEncounter(campaign, id, { entityId: '' });
}

/** Direct follow-up request — "fulfill the ruleset for encountering a new
 *  lifeform using the Generating Lifeforms rules on p.146 of Planetfall":
 *  creates a new `lifeform` entity, rolls its full profile
 *  (domain/lifeforms.js), replaces the auto-attached generic Bestiary
 *  group with one populated `'planetfall-lifeform'` group (same "create
 *  entity, then fill a group's fields by key" shape entities.js's own
 *  createItemFromCatalog already uses), and links it to the target
 *  encounter row — its `note` gets the same one-line summary the
 *  rulebook's own example table entries use, so the row reads correctly
 *  even without opening the entity. */
function createGeneratedLifeform(campaign, rowId, name, rng = Math.random) {
  const { campaign: withEntity, id } = createEntity(campaign, { type: 'lifeform', name });
  const profile = rollLifeformProfile(rng);
  let next = removeEntityStatblockGroup(withEntity, id, 0);
  next = addEntityStatblockGroup(next, id, 'npc', 'planetfall-lifeform');
  const entity = getEntity(next, id);
  const group = entity.statblocks[entity.statblocks.length - 1];
  const setField = (key, value) => { const f = group.fields.find((fl) => fl.key === key); if (f) f.value = value; };
  setField('Speed', profile.speed);
  setField('Combat', profile.combat);
  setField('Melee Damage', profile.meleeDamage);
  setField('Toughness', profile.toughness);
  setField('Armor / Notes', profile.toughnessNote);
  setField('Special', [...profile.specialAttacks, ...(profile.uniqueAbility ? [profile.uniqueAbility] : [])].join(', '));
  setField('KP', profile.kp);
  return updateColonyEncounter(next, rowId, { entityId: id, note: formatLifeformProfile(name, profile) });
}

exports.MAX_ENCOUNTERS = MAX_ENCOUNTERS;
exports.COLONY_FIELDS = COLONY_FIELDS;
exports.getColonyFields = getColonyFields;
exports.setColonyField = setColonyField;
exports.advanceCampaignTurn = advanceCampaignTurn;
exports.advanceCampaignTurnWithAccrual = advanceCampaignTurnWithAccrual;
exports.formatTurnAdvanceNote = formatTurnAdvanceNote;
exports.incrementCampaignMilestones = incrementCampaignMilestones;
exports.decrementCampaignMilestones = decrementCampaignMilestones;
exports.CREW_ROLES = CREW_ROLES;
exports.listCrewRows = listCrewRows;
exports.addCrewRow = addCrewRow;
exports.updateCrewRow = updateCrewRow;
exports.removeCrewRow = removeCrewRow;
exports.syncCrewRosterWithParty = syncCrewRosterWithParty;
exports.listLifeformEncounters = listLifeformEncounters;
exports.listColonyEncounters = listColonyEncounters;
exports.updateColonyEncounter = updateColonyEncounter;
exports.detachColonyEncounterEntity = detachColonyEncounterEntity;
exports.createGeneratedLifeform = createGeneratedLifeform;

});

register("src/domain/lifeforms.js", function(exports, require){
// lifeforms.js — Planetfall's own "Generating Lifeforms" procedure
// (rulebook p.146-148, see data/lifeformGenerationTables.js for the
// transcribed tables and citation). Pure, DOM-free, mirrors worldbuilding.js's
// self-contained generator shape (rollX/formatX pair) — direct request:
// "fulfill the ruleset for encountering a new lifeform using the Generating
// Lifeforms rules on p.146 of Planetfall." Real randomness by default
// (Math.random); only tests pass a seeded rng (CLAUDE.md convention).

const {LIFEFORM_MOBILITY_TABLE, LIFEFORM_COMBAT_SKILL_TABLE, LIFEFORM_STRIKE_POWER_TABLE, LIFEFORM_SPECIAL_ATTACKS_TABLE, LIFEFORM_TOUGHNESS_TABLE, LIFEFORM_UNIQUE_ABILITY_TABLE, LIFEFORM_ENCOUNTER_RANGES,} = require("src/data/lifeformGenerationTables.js");

function rollD100(rng) { return Math.floor(rng() * 100) + 1; }
function endsInZeroOrFive(n) { return n % 10 === 0 || n % 10 === 5; }
function fromRanges(table, n) { return table.find((row) => n <= row.max); }

/** Runs the full 5-step Generating Lifeforms procedure once, producing one
 *  creature's profile. See data/lifeformGenerationTables.js for each
 *  table's own rulebook citation. */
function rollLifeformProfile(rng = Math.random) {
  const mobilityRoll = rollD100(rng);
  const mobility = fromRanges(LIFEFORM_MOBILITY_TABLE, mobilityRoll);
  const partiallyAirborne = endsInZeroOrFive(mobilityRoll);

  const combatRoll = rollD100(rng);
  const combat = fromRanges(LIFEFORM_COMBAT_SKILL_TABLE, combatRoll).combat;

  const strikeRoll = rollD100(rng);
  const meleeDamage = fromRanges(LIFEFORM_STRIKE_POWER_TABLE, strikeRoll).meleeDamage;

  // "If either roll ends in a 0 or a 5, the creature has a Special Attack
  // as well... If both rolls end in a 0 or a 5, the creature rolls twice
  // for Special Attacks. Ignore a duplicate result... and count it as no
  // additional attack" — a Set naturally implements that dedupe.
  const specialAttackRolls = (endsInZeroOrFive(combatRoll) ? 1 : 0) + (endsInZeroOrFive(strikeRoll) ? 1 : 0);
  const specialAttacks = new Set();
  for (let i = 0; i < specialAttackRolls; i++) {
    specialAttacks.add(fromRanges(LIFEFORM_SPECIAL_ATTACKS_TABLE, rollD100(rng)).name);
  }

  const toughnessRoll = rollD100(rng);
  const toughnessRow = fromRanges(LIFEFORM_TOUGHNESS_TABLE, toughnessRoll);

  const uniqueRoll = rollD100(rng);
  const uniqueName = fromRanges(LIFEFORM_UNIQUE_ABILITY_TABLE, uniqueRoll).name;

  return {
    speed: mobility.speed,
    partiallyAirborne,
    combat,
    meleeDamage,
    toughness: toughnessRow.toughness,
    toughnessNote: toughnessRow.note || '',
    kp: toughnessRow.kp || 0,
    specialAttacks: [...specialAttacks],
    uniqueAbility: uniqueName === 'None' ? null : uniqueName,
  };
}

/** Renders a rolled profile as the same one-line summary the rulebook's own
 *  example table entries use, e.g. `Nickname 'Turbostone': Speed 7",
 *  Combat +1, Melee +1 Damage, Toughness 5`. A Special Attack and a Unique
 *  Ability are folded into one trailing "Special:" list — confirmed by the
 *  book's own "Vaportrail" example (Overpower is a Special Attack, Hinder
 *  is a Unique Ability, listed together). */
function formatLifeformProfile(name, profile) {
  const parts = [
    `Speed ${profile.speed}"${profile.partiallyAirborne ? ' (Partially Airborne)' : ''}`,
    `Combat +${profile.combat}`,
    `Melee +${profile.meleeDamage} Damage`,
    `Toughness ${profile.toughness}`,
  ];
  if (profile.toughnessNote) parts.push(profile.toughnessNote);
  if (profile.kp) parts.push(`${profile.kp} KP`);
  const specials = [...profile.specialAttacks, ...(profile.uniqueAbility ? [profile.uniqueAbility] : [])];
  if (specials.length) parts.push(`Special: ${specials.join(', ')}`);
  return `Nickname '${name}': ${parts.join(', ')}`;
}

/** "01-18" style label for the Colony tab's Lifeform Encounters range
 *  column, row index 0-9 (row 1 = index 0) — direct request: "add a column
 *  with that same % breakdown as the first column." */
function lifeformEncounterRangeLabel(index) {
  const max = LIFEFORM_ENCOUNTER_RANGES[index];
  if (max == null) return '';
  const prevMax = index === 0 ? 0 : LIFEFORM_ENCOUNTER_RANGES[index - 1];
  const lo = String(prevMax + 1).padStart(2, '0');
  const hi = max === 100 ? '00' : String(max).padStart(2, '0');
  return `${lo}-${hi}`;
}

/** Maps a D100 roll (1-100) to which of the 10 Lifeform Encounters rows
 *  (1-10) it falls in, per the rulebook's own example table's fixed %
 *  breakdown — the header dice roller's own "roll D100 on the Campaign
 *  Lifeform Encounters table" step (p.146). */
function resolveLifeformEncounterSlot(d100) {
  return LIFEFORM_ENCOUNTER_RANGES.findIndex((max) => d100 <= max) + 1;
}

exports.rollLifeformProfile = rollLifeformProfile;
exports.formatLifeformProfile = formatLifeformProfile;
exports.lifeformEncounterRangeLabel = lifeformEncounterRangeLabel;
exports.resolveLifeformEncounterSlot = resolveLifeformEncounterSlot;

});

register("src/domain/worldTracker.js", function(exports, require){
// worldTracker.js — the strategic World Tracker's pure storage
// (requirements/PLANETFALL_world_tracker.md): a fixed 6x6 grid of sectors
// for 5PFH Planetfall-style colony play (home base, exploration/resource/
// hazard state, mobile enemy-camp features, mission-hook suggestions).
// Distinct from battlemaps.js (that's the TACTICAL miniatures grid; this
// is the STRATEGIC colony/exploration map) — no shared code between them,
// since the layout models differ (fixed integer grid cells here vs.
// freeform 0-1 fractional placement there).
//
// `sectors` is a SPARSE map keyed "x,y" (1-based, 1..gridSize each) — a
// coordinate with no entry yet is read (getSector) as a synthesized
// default unexplored sector, never written until something actually
// touches it, same additive-lazy-init posture schema.js uses throughout.
//
// Campaign Turn / Campaign Milestones deliberately live in colony.js
// (colony.fields.campaignTurn/campaignMilestones, the same 5PFH Planetfall
// ruleset's existing Turn Sheet) — not duplicated here. advanceWorldTurn
// below only clears this module's OWN per-turn state (migration ghost
// markers); callers combine it with colony.js's advanceCampaignTurn.

const {WORLD_TRACKER_MISSION_HOOKS} = require("src/data/worldTrackerMissionHooks.js");

function clone(c) { try { return structuredClone(c); } catch { return JSON.parse(JSON.stringify(c)); } }

function ensure(campaign) {
  if (!campaign.worldTracker || typeof campaign.worldTracker !== 'object') campaign.worldTracker = {};
  const wt = campaign.worldTracker;
  if (!Number.isFinite(wt.gridSize) || wt.gridSize < 1) wt.gridSize = 6;
  if (!wt.sectors || typeof wt.sectors !== 'object') wt.sectors = {};
  if (wt.homeBaseSector === undefined) wt.homeBaseSector = null;
  if (typeof wt.notes !== 'string') wt.notes = '';
  return wt;
}

function newId(prefix) { return prefix + '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6); }

function key(x, y) { return `${x},${y}`; }

function clampCoord(n, gridSize) {
  const v = Math.round(Number(n));
  if (!Number.isFinite(v)) return 1;
  return Math.max(1, Math.min(gridSize, v));
}

function rollDie(sides, rng) { return Math.floor(rng() * sides) + 1; }

// 5PFH Planetfall p.53 "Initial Placements": after picking/rolling a home
// sector, the GM marks exactly 10 OTHER sectors as investigation sites
// (the only ones that start showing a '?') — NOT every unexplored sector
// on the grid, which is what this used to assume (a real reported
// inaccuracy). This cap is advisory, not enforced here (see
// toggleInvestigationSite below) — a GM correcting a mistake mid-campaign
// shouldn't be hard-blocked by a rule about INITIAL setup.
const MAX_INVESTIGATION_SITES = 10;

function defaultSector() {
  return {
    state: 'unexplored',
    investigationSite: false,
    resourceLevel: null, resourceHarvested: false,
    hazardLevel: null, hazardTags: [],
    features: [],
    cornerLabels: [],
    overlayIcon: null,
    notes: '',
  };
}

function gridSizeOf(campaign) {
  return (campaign.worldTracker && campaign.worldTracker.gridSize) || 6;
}

/** Read-only — the real sector record, or a synthesized default. Never
 *  mutates the campaign, so callers scanning many/all sectors (a render
 *  loop, generateMissionHooks) don't need to clone anything themselves. */
function getSector(campaign, x, y) {
  const wt = campaign.worldTracker || {};
  const rec = (wt.sectors || {})[key(x, y)];
  return rec ? { ...rec, x, y } : { ...defaultSector(), x, y };
}

/** Every sector actually touched (present in the sparse map) so far, each
 *  tagged with its own {x,y} — the Sectors/Features/Missions tabs and
 *  generateMissionHooks all scan this rather than all 36 possible
 *  coordinates, so a fresh campaign starts with an empty, uncluttered list
 *  instead of 36 identical "unexplored" entries. */
function listTouchedSectors(campaign) {
  const wt = campaign.worldTracker || {};
  return Object.entries(wt.sectors || {}).map(([k, rec]) => {
    const [x, y] = k.split(',').map(Number);
    return { ...rec, x, y };
  });
}

function countInvestigationSites(campaign) {
  return listTouchedSectors(campaign).filter((s) => s.investigationSite).length;
}

/** Toggles the p.53 "investigation site" marker for one sector — the only
 *  thing that makes an unexplored sector show a '?' (see deriveSectorIcon
 *  below). Un-marking is always allowed; marking is advisory-capped (see
 *  MAX_INVESTIGATION_SITES's own comment) rather than hard-blocked. */
function toggleInvestigationSite(campaign, x, y) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = getOrCreateSectorRecord(wt, clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize));
  sector.investigationSite = !sector.investigationSite;
  return next;
}

/** "Random" convenience (direct follow-up request): rolls 1d(gridSize) x
 *  1d(gridSize) — the same die the home-base roll always uses, first roll
 *  = X, second = Y — to pick a sector to mark as an investigation site,
 *  rerolling if that lands on the home base sector, an already-marked
 *  sector, or one that's no longer unexplored (5PFH Planetfall p.53:
 *  investigation sites are 10 UNEXPLORED sectors other than home base).
 *  No-op once already at the advisory MAX_INVESTIGATION_SITES cap (see its
 *  own comment) — same "never hard-blocks a GM correcting mid-campaign"
 *  posture as toggleInvestigationSite, just refusing to pick a NEW one
 *  past the cap rather than refusing to un-mark an existing one. Bounded
 *  retry, then an in-order scan fallback, so a nearly-full grid can't
 *  spin forever re-rolling the same handful of occupied sectors. Returns
 *  { campaign, x, y } — x/y null (campaign unchanged) if the cap is
 *  already reached or no eligible sector exists at all. */
function rollRandomInvestigationSite(campaign, { rng = Math.random } = {}) {
  if (countInvestigationSites(campaign) >= MAX_INVESTIGATION_SITES) return { campaign, x: null, y: null };
  const wt = campaign.worldTracker || {};
  const gridSize = wt.gridSize || 6;
  const home = wt.homeBaseSector;
  const isEligible = (x, y) => {
    if (home && home.x === x && home.y === y) return false;
    const sector = getSector(campaign, x, y);
    return sector.state === 'unexplored' && !sector.investigationSite;
  };
  let x = null;
  let y = null;
  for (let attempt = 0; attempt < 200; attempt++) {
    const rx = rollDie(gridSize, rng);
    const ry = rollDie(gridSize, rng);
    if (isEligible(rx, ry)) { x = rx; y = ry; break; }
  }
  if (x == null) {
    scan:
    for (let sx = 1; sx <= gridSize; sx++) {
      for (let sy = 1; sy <= gridSize; sy++) {
        if (isEligible(sx, sy)) { x = sx; y = sy; break scan; }
      }
    }
  }
  if (x == null) return { campaign, x: null, y: null };
  return { campaign: toggleInvestigationSite(campaign, x, y), x, y };
}

function getOrCreateSectorRecord(wt, x, y) {
  const k = key(x, y);
  if (!wt.sectors[k]) wt.sectors[k] = defaultSector();
  return wt.sectors[k];
}

/** Rolls resource/hazard levels (flat 1d6 each — the literal Planetfall
 *  roll tables aren't in this repo, only that these are rolled ints; see
 *  the requirements doc) and flips state to 'explored'. No-op if this
 *  sector has already been explored (or surveyed) — revealing is a
 *  one-time event per sector, not re-rollable by re-tapping it. */
function revealSector(campaign, x, y, { rng = Math.random } = {}) {
  const next = clone(campaign);
  const wt = ensure(next);
  const gx = clampCoord(x, wt.gridSize), gy = clampCoord(y, wt.gridSize);
  const sector = getOrCreateSectorRecord(wt, gx, gy);
  if (sector.state !== 'unexplored') return next;
  sector.resourceLevel = rollDie(6, rng);
  sector.hazardLevel = rollDie(6, rng);
  sector.state = 'explored';
  // Spec 4.1's "standard use" — resource value in one corner, hazard in
  // another — applied automatically on reveal; a GM can still overwrite
  // either corner with setSectorCornerLabel afterward (source:'custom'
  // simply replaces whatever was here, same one-label-per-corner rule).
  // Hazard defaults to bottom_left (direct follow-up request — was
  // top_right); resource stays top_left.
  sector.cornerLabels = sector.cornerLabels.filter((c) => c.corner !== 'top_left' && c.corner !== 'bottom_left');
  sector.cornerLabels.push({ corner: 'top_left', text: `R${sector.resourceLevel}`, source: 'resource' });
  sector.cornerLabels.push({ corner: 'bottom_left', text: `H${sector.hazardLevel}`, source: 'hazard' });
  return next;
}

// Resource/Hazard Level editable fields (direct follow-up request — same
// number-field format as Colony's own COLONY_FIELDS). Clamped to 0 and up
// (direct follow-up request — no negative levels); keeps the auto-managed
// R#/H# corner label (source 'resource'/'hazard') in sync with the edited
// number so the grid cell's corner text — and, via its own CSS custom
// property, the cell's resource-shading/hazard-badge intensity — never
// drifts from the sidebar's own value; a corner the GM has since
// overwritten by hand (source:'custom') is left alone — editing the level
// only ever touches the label IT put there.
function setSectorResourceLevel(campaign, x, y, value) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = getOrCreateSectorRecord(wt, clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize));
  const level = value === '' || value == null || !Number.isFinite(Number(value)) ? null : Math.max(0, Math.round(Number(value)));
  sector.resourceLevel = level;
  const label = sector.cornerLabels.find((c) => c.corner === 'top_left' && c.source === 'resource');
  if (label) label.text = level == null ? '' : `R${level}`;
  return next;
}
function setSectorHazardLevel(campaign, x, y, value) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = getOrCreateSectorRecord(wt, clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize));
  const level = value === '' || value == null || !Number.isFinite(Number(value)) ? null : Math.max(0, Math.round(Number(value)));
  sector.hazardLevel = level;
  const label = sector.cornerLabels.find((c) => c.corner === 'bottom_left' && c.source === 'hazard');
  if (label) label.text = level == null ? '' : `H${level}`;
  return next;
}

/** 'explored' -> 'surveyed' only; no-op on an unexplored or already-
 *  surveyed sector. */
function surveySector(campaign, x, y) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = wt.sectors[key(clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize))];
  if (sector && sector.state === 'explored') sector.state = 'surveyed';
  return next;
}

/** Marks the sector's resource as harvested — generateMissionHooks below
 *  suppresses just that sector's resource_node hook afterward, never the
 *  sector's other hooks (spec: "once harvested, sector stops generating
 *  RESOURCE-based mission hooks", not ALL of its hooks). No-op if the
 *  sector has no rolled resource at all. */
function harvestSectorResource(campaign, x, y) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = wt.sectors[key(clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize))];
  if (sector && sector.resourceLevel != null) sector.resourceHarvested = true;
  return next;
}

function setSectorNotes(campaign, x, y, notes) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = getOrCreateSectorRecord(wt, clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize));
  sector.notes = String(notes || '');
  return next;
}

/** `iconKey: null` clears a manual override back to deriveSectorIcon's
 *  automatic, feature-priority-based choice (see below) — the same
 *  "explicit override coexists with automatic derivation" shape
 *  CornerLabel's own source:'custom' already uses. Picking 'unexplored'
 *  specifically (direct follow-up request) does more than swap the icon —
 *  it resets the sector back to blank: rolled levels, resourceHarvested,
 *  investigation-site marker, features, and corner labels all cleared,
 *  state back to 'unexplored'. Notes are left alone (GM scratch text, not
 *  "Levels and other features"); overlayIcon stays 'unexplored' so the
 *  '?' the GM explicitly asked for keeps showing regardless of
 *  investigationSite (which the reset just cleared). Every other icon key
 *  keeps the original cosmetic-only behavior. */
function setSectorOverlayIcon(campaign, x, y, iconKey) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = getOrCreateSectorRecord(wt, clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize));
  if (iconKey === 'unexplored') {
    const notes = sector.notes;
    Object.assign(sector, defaultSector(), { notes, overlayIcon: 'unexplored' });
    return next;
  }
  sector.overlayIcon = iconKey || null;
  return next;
}

const CORNERS = ['top_left', 'top_right', 'bottom_left', 'bottom_right'];

/** Each corner holds at most one label — setting one replaces whatever was
 *  there before at that SAME corner, the other three corners untouched. */
function setSectorCornerLabel(campaign, x, y, corner, text, source = 'custom') {
  if (!CORNERS.includes(corner)) return clone(campaign);
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = getOrCreateSectorRecord(wt, clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize));
  sector.cornerLabels = sector.cornerLabels.filter((c) => c.corner !== corner);
  const t = String(text || '').trim();
  if (t) sector.cornerLabels.push({ corner, text: t, source });
  return next;
}

function removeSectorCornerLabel(campaign, x, y, corner) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = wt.sectors[key(clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize))];
  if (sector) sector.cornerLabels = sector.cornerLabels.filter((c) => c.corner !== corner);
  return next;
}

const FEATURE_KINDS = ['alien_site', 'enemy_camp', 'resource_node', 'milestone_site'];

/** Features stack — a sector can carry more than one, e.g. a migrated camp
 *  landing on a sector that's already an alien site (spec 1.4). */
function addSectorFeature(campaign, x, y, kind) {
  if (!FEATURE_KINDS.includes(kind)) return clone(campaign);
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = getOrCreateSectorRecord(wt, clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize));
  sector.features.push({ id: newId('wtf'), kind, mobile: kind === 'enemy_camp', discovered: false, linkedMissionType: null, movedFrom: null, notes: '' });
  return next;
}

function discoverSectorFeature(campaign, x, y, featureId) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = wt.sectors[key(clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize))];
  const feature = sector && sector.features.find((f) => f.id === featureId);
  if (feature) feature.discovered = true;
  return next;
}

/** The Features tab/Sector detail's own eye icon toggle (direct follow-up
 *  request — able to roll a decision back, unlike discoverSectorFeature
 *  above, which stays one-way since it's also how a resolved mission hook
 *  marks its feature discovered — reversing THAT should be a deliberate
 *  separate action, not implied by running a mission). */
function toggleSectorFeatureDiscovered(campaign, x, y, featureId) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = wt.sectors[key(clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize))];
  const feature = sector && sector.features.find((f) => f.id === featureId);
  if (feature) feature.discovered = !feature.discovered;
  return next;
}

/** Direct follow-up request: "add a two-row, expandable Description
 *  textbox... accessed by clicking on the feature listed from Features tab
 *  on World panel" — a feature predating this change simply has no `notes`
 *  key yet; the UI reads it as '' (esc(f.notes || '')), so no migration
 *  backfill is needed for a plain optional string field like this one. */
function updateSectorFeatureNotes(campaign, x, y, featureId, notes) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = wt.sectors[key(clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize))];
  const feature = sector && sector.features.find((f) => f.id === featureId);
  if (feature) feature.notes = String(notes || '');
  return next;
}

function removeSectorFeature(campaign, x, y, featureId) {
  const next = clone(campaign);
  const wt = ensure(next);
  const sector = wt.sectors[key(clampCoord(x, wt.gridSize), clampCoord(y, wt.gridSize))];
  if (sector) sector.features = sector.features.filter((f) => f.id !== featureId);
  return next;
}

/** Plain square 4-neighbor adjacency (up/down/left/right), clamped to the
 *  grid — no diagonals, no hex (5PFH Planetfall's grid is a plain d6xd6
 *  square, confirmed against the rulebook). Pure coordinate math, no
 *  campaign needed. */
function adjacentSectors(x, y, gridSize = 6) {
  const candidates = [{ x, y: y - 1 }, { x, y: y + 1 }, { x: x - 1, y }, { x: x + 1, y }];
  return candidates.filter((c) => c.x >= 1 && c.x <= gridSize && c.y >= 1 && c.y <= gridSize);
}

/** GM-manual migration only (direct decision — no rulebook-derived auto-
 *  suggestion): no-ops if the feature isn't found, isn't mobile, or the
 *  target isn't actually adjacent to the source. The arriving copy is
 *  stamped with movedFrom so the UI can render a one-turn "moved from"
 *  ghost marker (spec 4.2); advanceWorldTurn below clears it. */
function migrateFeature(campaign, fromX, fromY, featureId, toX, toY) {
  const next = clone(campaign);
  const wt = ensure(next);
  const gx = clampCoord(fromX, wt.gridSize), gy = clampCoord(fromY, wt.gridSize);
  const tx = clampCoord(toX, wt.gridSize), ty = clampCoord(toY, wt.gridSize);
  const source = wt.sectors[key(gx, gy)];
  const feature = source && source.features.find((f) => f.id === featureId);
  if (!feature || !feature.mobile) return next;
  if (!adjacentSectors(gx, gy, wt.gridSize).some((c) => c.x === tx && c.y === ty)) return next;
  source.features = source.features.filter((f) => f.id !== featureId);
  const dest = getOrCreateSectorRecord(wt, tx, ty);
  dest.features.push({ ...feature, movedFrom: { x: gx, y: gy } });
  return next;
}

function setHomeBase(campaign, x, y) {
  const next = clone(campaign);
  const wt = ensure(next);
  wt.homeBaseSector = { x: clampCoord(x, wt.gridSize), y: clampCoord(y, wt.gridSize) };
  return next;
}

/** "Home base can be chosen or rolled randomly in any square" (5PFH
 *  Planetfall p.53) — 1d6 x 1d6, same die the whole grid is sized around. */
function rollHomeBase(campaign, { rng = Math.random } = {}) {
  const wt = campaign.worldTracker || {};
  const gridSize = wt.gridSize || 6;
  return setHomeBase(campaign, rollDie(gridSize, rng), rollDie(gridSize, rng));
}

/** End-of-turn step, THIS module's part of it only (spec 1.6: "mobile
 *  features may migrate... new sectors get revealed" — migration/reveal
 *  themselves are separate GM actions above; this just clears every
 *  feature's movedFrom campaign-wide so a migration's ghost marker shows
 *  for exactly one turn, then disappears on the next). Callers combine
 *  this with colony.js's advanceCampaignTurn in the same store.update. */
function advanceWorldTurn(campaign) {
  const next = clone(campaign);
  const wt = ensure(next);
  for (const sector of Object.values(wt.sectors)) {
    for (const feature of sector.features) feature.movedFrom = null;
  }
  return next;
}

// Priority order for the ONE overlay icon slot a sector can show at once
// (spec 4.1.3: "home base > active camp > alien site > milestone > plain
// unexplored ?" — resource_node isn't in the spec's own worked example
// list; inserted here between alien_site and milestone_site as the most
// sensible slot, easily reordered later since this is the only place the
// order is expressed).
const ICON_PRIORITY = ['enemy_camp', 'alien_site', 'resource_node', 'milestone_site'];

/** Pure — never reads/writes IndexedDB or the DOM. Only consulted by the
 *  UI when sector.overlayIcon (a manual override) is null. An unexplored
 *  sector only shows '?' if it's one of the GM's marked investigation
 *  sites (p.53 "Initial Placements" — a real reported inaccuracy: this
 *  used to show '?' on EVERY unexplored sector); a plain untouched/
 *  unmarked sector shows no icon at all. */
function deriveSectorIcon(sector, isHomeBase) {
  if (isHomeBase) return 'home_base';
  for (const kind of ICON_PRIORITY) {
    if ((sector.features || []).some((f) => f.kind === kind)) return kind;
  }
  if (sector.state === 'unexplored' && sector.investigationSite) return 'unexplored';
  return null;
}

function hookFor(signal) { return WORLD_TRACKER_MISSION_HOOKS.find((h) => h.signal === signal) || null; }

/** Scans every TOUCHED sector (listTouchedSectors — an untouched, never-
 *  interacted-with coordinate isn't "on the map" for hook purposes yet, so
 *  a fresh 6x6 grid doesn't start with 36 identical "go explore" hooks)
 *  against WORLD_TRACKER_MISSION_HOOKS' signal->missionType data. A hook
 *  retires itself once its underlying signal no longer applies — the
 *  harvested-resource flag suppresses a resource_node's hook (spec 1.3),
 *  and a feature's own `discovered` flag suppresses its hook the same way
 *  once the GM has run that mission (see the `resolve` field's own
 *  comment in the data file). Returns [{x, y, missionType, reason, signal,
 *  featureId}] — `featureId` only set for a feature-kind hook, since a
 *  sector can carry more than one feature (each gets its own hook, not
 *  deduplicated by kind); most-recently-touched order is NOT guaranteed —
 *  this is a suggestion list of currently-available missions, not a log
 *  of completed ones. */
function generateMissionHooks(campaign) {
  const hooks = [];
  for (const sector of listTouchedSectors(campaign)) {
    // Only a marked investigation site's own "Investigation" hook (p.53) —
    // not every touched-but-still-unexplored sector (e.g. one that merely
    // has a note or a corner label on it isn't automatically a mission
    // hook).
    if (sector.state === 'unexplored' && sector.investigationSite) {
      const def = hookFor('unexplored');
      if (def) hooks.push({ x: sector.x, y: sector.y, missionType: def.missionType, reason: def.reason, signal: 'unexplored' });
    }
    if (sector.state === 'explored') {
      const def = hookFor('explored');
      if (def) hooks.push({ x: sector.x, y: sector.y, missionType: def.missionType, reason: def.reason, signal: 'explored' });
    }
    for (const feature of sector.features) {
      if (feature.discovered) continue;
      if (feature.kind === 'resource_node' && sector.resourceHarvested) continue;
      const def = hookFor(feature.kind);
      if (def) hooks.push({ x: sector.x, y: sector.y, missionType: def.missionType, reason: def.reason, signal: feature.kind, featureId: feature.id });
    }
  }
  return hooks;
}

function setWorldTrackerNotes(campaign, notes) {
  const next = clone(campaign);
  ensure(next).notes = String(notes || '');
  return next;
}

/** "Reset" (direct follow-up request — a button at the bottom of the
 *  World Tracker): wipes every sector, the home base, and the world-level
 *  notes back to a brand-new grid — gridSize is the one thing preserved
 *  (a structural setting, not "the grid" being cleared). The UI gates this
 *  behind a confirm() dialog, same posture as every other hard-to-reverse
 *  action in this app. */
function resetWorldTracker(campaign) {
  const next = clone(campaign);
  const gridSize = gridSizeOf(next);
  next.worldTracker = { gridSize, sectors: {}, homeBaseSector: null, notes: '' };
  return next;
}

/** The Overview tab's guided-workflow checklist (direct request: surface
 *  each pending decision as a step in the tool's own UI instead of
 *  requiring the GM to notice it by clicking through tabs — and never
 *  decide it FOR them; every item here is something the GM still has to
 *  act on). Pure and read-only, same "just look at current state" shape
 *  generateMissionHooks already uses — nothing here is itself a decision,
 *  only a surfaced one. Order matches the natural p.53 setup sequence
 *  (home base, then investigation sites) followed by whatever's currently
 *  actionable in play (every generateMissionHooks entry, one item each).
 *  Returns [{ kind: 'home-base' | 'investigation-sites' | 'mission', label, detail, ...hook }]
 *  — a 'mission' item spreads its generateMissionHooks entry directly
 *  (x/y/missionType/reason/signal/featureId) so the UI can reuse the exact
 *  same "Run this" control the Missions tab already has, no duplicate
 *  markup or a second resolution code path. */
function worldTrackerAttentionItems(campaign) {
  const items = [];
  const wt = campaign.worldTracker || {};
  if (!wt.homeBaseSector) {
    items.push({ kind: 'home-base', label: 'Set your home base', detail: 'Pick one on the grid (Sectors tab), or roll it randomly (5PFH Planetfall p.53).' });
  }
  const marked = countInvestigationSites(campaign);
  if (marked < MAX_INVESTIGATION_SITES) {
    items.push({
      kind: 'investigation-sites',
      label: `${MAX_INVESTIGATION_SITES - marked} more investigation site${MAX_INVESTIGATION_SITES - marked === 1 ? '' : 's'} to mark`,
      detail: `${marked} / ${MAX_INVESTIGATION_SITES} marked so far — mark them from a sector's own detail panel (Sectors tab).`,
    });
  }
  // Only one actionable mission per sector here (direct follow-up request:
  // "Only one actionable option should be available for a Sector" — this
  // Attention list was showing a sector's state-progression hook, e.g.
  // Investigation Mission for a still-unexplored marked sector, right next
  // to that SAME sector's own feature hooks, which read as contradictory
  // since the two aren't about the same thing). A sector's own state
  // (unexplored -> explored -> surveyed, the exact field the Sectors tab's
  // "State:" label reads) takes priority over any of its individual
  // undiscovered features — so whatever's shown here always matches
  // "State:" on the Sectors tab, and "Run this" (which resolves 'reveal'/
  // 'survey' for a state hook) always advances that same state. Once a
  // sector has no more state hook (fully surveyed), its own feature hooks
  // become the one shown instead — generateMissionHooks itself, and the
  // Missions tab that reads it directly, are unaffected: this dedup is
  // Attention-list-only, since Missions is a deliberate full-list browse.
  const bySector = new Map();
  const isStateHook = (h) => h.signal === 'unexplored' || h.signal === 'explored';
  for (const hook of generateMissionHooks(campaign)) {
    const key = `${hook.x},${hook.y}`;
    const existing = bySector.get(key);
    if (!existing || (isStateHook(hook) && !isStateHook(existing))) bySector.set(key, hook);
  }
  for (const hook of bySector.values()) {
    items.push({ kind: 'mission', label: `Sector ${hook.x},${hook.y}: ${hook.missionType} available`, detail: hook.reason, ...hook });
  }
  return items;
}

exports.MAX_INVESTIGATION_SITES = MAX_INVESTIGATION_SITES;
exports.gridSizeOf = gridSizeOf;
exports.getSector = getSector;
exports.listTouchedSectors = listTouchedSectors;
exports.countInvestigationSites = countInvestigationSites;
exports.toggleInvestigationSite = toggleInvestigationSite;
exports.rollRandomInvestigationSite = rollRandomInvestigationSite;
exports.revealSector = revealSector;
exports.setSectorResourceLevel = setSectorResourceLevel;
exports.setSectorHazardLevel = setSectorHazardLevel;
exports.surveySector = surveySector;
exports.harvestSectorResource = harvestSectorResource;
exports.setSectorNotes = setSectorNotes;
exports.setSectorOverlayIcon = setSectorOverlayIcon;
exports.setSectorCornerLabel = setSectorCornerLabel;
exports.removeSectorCornerLabel = removeSectorCornerLabel;
exports.addSectorFeature = addSectorFeature;
exports.discoverSectorFeature = discoverSectorFeature;
exports.toggleSectorFeatureDiscovered = toggleSectorFeatureDiscovered;
exports.updateSectorFeatureNotes = updateSectorFeatureNotes;
exports.removeSectorFeature = removeSectorFeature;
exports.adjacentSectors = adjacentSectors;
exports.migrateFeature = migrateFeature;
exports.setHomeBase = setHomeBase;
exports.rollHomeBase = rollHomeBase;
exports.advanceWorldTurn = advanceWorldTurn;
exports.deriveSectorIcon = deriveSectorIcon;
exports.generateMissionHooks = generateMissionHooks;
exports.setWorldTrackerNotes = setWorldTrackerNotes;
exports.resetWorldTracker = resetWorldTracker;
exports.worldTrackerAttentionItems = worldTrackerAttentionItems;

});

register("src/domain/trade.js", function(exports, require){
// trade.js — Merchant Rules Lens (ADR 0003, refined by ADR 0004): a
// contract-driven trade minigame built on top of a per-Location commodity
// pricing engine, not a second product. Two things share this module
// because ADR 0004 makes the second the primary loop and the first its
// engine:
//
//   1. Pricing: a Location entity gains an optional `market` — a per-
//      commodity {supply, demand} dial pair (0-100, GM-set, not a live
//      simulation) — and priceAt() turns that into a live price. buy()/
//      sell() move goods into/out of a party-wide cargo manifest and nudge
//      the local market's supply dial the direction a real transaction
//      would, so two Locations' prices are never forced to agree — that
//      divergence is the entire "plan a purchase and transport" loop.
//   2. Contracts: "a contract is a Thread with a few extra fields," not a
//      new state machine — see createContract/generateContract below. This
//      reuses domain/threads.js's clock, 7-state lifecycle, and Co-Pilot
//      surfacing entirely; the thread mutators there (advanceThread,
//      setThreadStatus, setThreadPriority, removeThread) already work on a
//      contract unchanged, since it lives in the same campaign.threads
//      array as any other thread and only carries a few extra optional
//      properties (kind: 'contract', type, patronId, originId,
//      destinationId, payout).
//
// Pure, DOM-free, clone-and-return — same shape as every other domain
// module (colony.js/party.js's ensure() pattern, threads.js's clock).

const {COMMODITIES, findCommodity} = require("src/data/commodities.js");
const {ECONOMY_TYPES, findEconomyType} = require("src/data/economyTypes.js");
const {findBiome} = require("src/data/biomes.js");
const {getEntity} = require("src/domain/entities.js");
const {addThread, listThreads} = require("src/domain/threads.js");
const {tablesWithOverrides, pick} = require("src/domain/oracles.js");
const {gatherSceneContext} = require("src/domain/copilot.js");
const {QUEST_REWARD_RULES, DEFAULT_QUEST_REWARD, VOW_RANKS, VOW_PROGRESS_BOXES} = require("src/data/questRewards.js");
const {QUEST_BRIEFS} = require("src/data/questOracles.js");
const {findGenrePack} = require("src/data/genrePacks.js");

function clone(c) { try { return structuredClone(c); } catch { return JSON.parse(JSON.stringify(c)); } }

function ensureTrade(campaign) {
  if (!campaign.trade || typeof campaign.trade !== 'object') campaign.trade = { manifest: [] };
  if (!Array.isArray(campaign.trade.manifest)) campaign.trade.manifest = [];
  return campaign.trade;
}

const clampDial = (n) => Math.max(0, Math.min(100, Number(n) || 0));

function ensureMarketDial(location, commodityId) {
  if (!location.market || typeof location.market !== 'object') location.market = {};
  if (!location.market[commodityId]) location.market[commodityId] = { supply: 50, demand: 50 };
  return location.market[commodityId];
}

/** A Location's market, read-only and fully populated — every known
 *  commodity defaults to a neutral 50/50 dial (a fresh market has no
 *  reason to already read as scarce or oversupplied) whether or not it's
 *  been touched yet, same "undefined means the neutral default" posture as
 *  the Narrative Trackers and a statblock field's rollMethod. */
function getMarket(location) {
  const stored = (location && location.market) || {};
  const out = {};
  for (const c of COMMODITIES) {
    const d = stored[c.id] || {};
    out[c.id] = { supply: clampDial(d.supply ?? 50), demand: clampDial(d.demand ?? 50) };
  }
  return out;
}

/** GM-set market dial (supply or demand, 0-100) for one commodity at one
 *  Location. No-op on an unknown location/commodity/field. */
function setMarketDial(campaign, locationId, commodityId, field, value) {
  const next = clone(campaign);
  const loc = getEntity(next, locationId);
  if (!loc || loc.type !== 'location' || !findCommodity(commodityId) || (field !== 'supply' && field !== 'demand')) return next;
  const dial = ensureMarketDial(loc, commodityId);
  dial[field] = clampDial(value);
  return next;
}

/** The economy type a Location's tags name, if any — checked against BOTH
 *  models regardless of which is currently active (docs/adr/0013), so
 *  switching settings.tradeEconomyModel never orphans a tag a GM already
 *  set on an existing Location. A plain tag match (case-insensitive), not
 *  a separate structured field — Locations already have a freeform tag
 *  system (entities.js); this reuses it rather than adding a new one. */
function economyTypeForLocation(location) {
  const tags = new Set((location && location.tags || []).map((t) => t.toLowerCase()));
  return ECONOMY_TYPES.find((t) => tags.has(t.label.toLowerCase())) || null;
}

// Shared by economyBiasAt/developmentLevelBiasAt and biomeBiasAt below —
// the same "0-10 scarcity dial -> a 0.6x-1.4x price multiplier" mapping,
// just fed from two different dial sources (docs/adr/0025).
function biasFromDial(dial) {
  return 0.6 + (Math.max(0, Math.min(10, dial)) / 10) * 0.8;
}

/** A 0.6x-1.4x price multiplier from a Location's tagged economy type, or
 *  exactly 1 (no change) if the Location carries no recognized economy-type
 *  tag — additive to the existing supply/demand dials, never a replacement.
 *  Raw commodities price off `scarcity` (scarce locally = pricier);
 *  manufactured commodities price off the inverse of `manufacturing` (weak
 *  local fabrication = pricier) — two dials instead of a literal tech
 *  level, per docs/adr/0013. Kept exactly as it was (still exported, still
 *  the tag-scan path) — developmentLevelBiasAt below wraps it as a
 *  fallback rather than replacing it, so a Location tagged before ADR 0025
 *  added a real `developmentLevel` field keeps pricing unchanged. */
function economyBiasAt(location, commodityId) {
  const c = findCommodity(commodityId);
  const et = economyTypeForLocation(location);
  if (!c || !et) return 1;
  const dial = c.category === 'manufactured' ? (10 - et.manufacturing) : et.scarcity;
  return biasFromDial(dial);
}

/** Development level bias (docs/adr/0025-location-biome-trade.md) —
 *  prefers a Location's real `developmentLevel` field if set (a GM-picked
 *  dropdown now, entities.js's ensureLocationFields), falling back to the
 *  pre-existing tag-scan (economyTypeForLocation, same as economyBiasAt
 *  above) when it isn't. This is what priceAt() actually calls now;
 *  economyBiasAt stays as the narrower tag-only piece this wraps. */
function developmentLevelBiasAt(location, commodityId) {
  const c = findCommodity(commodityId);
  const et = (location && location.developmentLevel && findEconomyType(location.developmentLevel)) || economyTypeForLocation(location);
  if (!c || !et) return 1;
  const dial = c.category === 'manufactured' ? (10 - et.manufacturing) : et.scarcity;
  return biasFromDial(dial);
}

/** A second, independent 0.6x-1.4x price multiplier from a Location's
 *  biome (data/biomes.js) — compounds with developmentLevelBiasAt rather
 *  than replacing it: development level answers "how built-up is this
 *  place," biome answers "what does the environment itself have plenty or
 *  little of." Reads the commodity's finer `resourceType` (water/fuel/
 *  food/ore/tech/luxury), not the coarser raw/manufactured `category`
 *  developmentLevelBiasAt uses, so the two can genuinely diverge on the
 *  same commodity (a Waterworld prices Water cheap regardless of whether
 *  it's also tagged/set Industrial). Exactly 1 (no change) if the
 *  Location has no biome set or the commodity has no resourceType. */
function biomeBiasAt(location, commodityId) {
  const c = findCommodity(commodityId);
  const biome = location && location.biome && findBiome(location.biome);
  if (!c || !biome || !c.resourceType) return 1;
  const dial = biome.resourceScarcity[c.resourceType];
  if (dial === undefined) return 1;
  return biasFromDial(dial);
}

/** basePrice * demandFactor / supplyFactor * developmentLevelBias *
 *  biomeBias — pure and stateless. The supply/demand dials are 0-100
 *  around a neutral midpoint of 50; each maps onto a 0.5x-1.5x multiplier,
 *  so a fresh market (50/50) with neither bias set prices at exactly
 *  basePrice. High demand or low supply raises the price; low demand or
 *  high supply lowers it — never below 1 (a price of 0 would make a
 *  commodity worthless to trade, which isn't a state this model needs). */
function priceAt(location, commodityId) {
  const c = findCommodity(commodityId);
  if (!c || !location) return 0;
  const { supply, demand } = getMarket(location)[commodityId];
  const demandFactor = 0.5 + demand / 100;
  const supplyFactor = 0.5 + supply / 100;
  const bias = developmentLevelBiasAt(location, commodityId) * biomeBiasAt(location, commodityId);
  return Math.max(1, Math.round((c.basePrice * demandFactor * bias) / supplyFactor));
}

/** The party's shared cargo manifest — {commodityId, qty} rows. Not tied
 *  to any one Vehicle/Asset entity (a party may have several transports);
 *  cargo CAPACITY, by contrast, lives on the Vehicle Stats statblock kind
 *  as an ordinary field (see data/statblockTemplates.js), not here. */
function listCargoManifest(campaign) {
  return (campaign.trade && campaign.trade.manifest) || [];
}

/** Buy `qty` of a commodity at a Location: adds it to the party's cargo
 *  manifest and drains that Location's supply dial by the same amount
 *  (buying scarce goods scarcer raises the NEXT price there) — the
 *  mechanic that keeps two Locations' prices from ever settling into
 *  agreement. No-op if the location/commodity don't resolve. */
function buyCommodity(campaign, locationId, commodityId, qty = 1) {
  const next = clone(campaign);
  const loc = getEntity(next, locationId);
  if (!loc || loc.type !== 'location' || !findCommodity(commodityId)) return next;
  const amount = Math.max(1, Math.round(Number(qty)) || 1);
  const dial = ensureMarketDial(loc, commodityId);
  dial.supply = clampDial(dial.supply - amount);
  const trade = ensureTrade(next);
  const row = trade.manifest.find((m) => m.commodityId === commodityId);
  if (row) row.qty += amount; else trade.manifest.push({ commodityId, qty: amount });
  return next;
}

/** Sell up to `qty` of a commodity (clamped to what the party actually
 *  has) at a Location: removes it from the manifest and floods that
 *  Location's supply dial by the same amount (lowering the next price
 *  there). No-op if the location/commodity don't resolve, or the party
 *  isn't carrying any of that commodity at all. */
function sellCommodity(campaign, locationId, commodityId, qty = 1) {
  const next = clone(campaign);
  const loc = getEntity(next, locationId);
  if (!loc || loc.type !== 'location' || !findCommodity(commodityId)) return next;
  const trade = ensureTrade(next);
  const row = trade.manifest.find((m) => m.commodityId === commodityId);
  const have = row ? row.qty : 0;
  if (have <= 0) return next;
  const amount = Math.max(1, Math.min(have, Math.round(Number(qty)) || 1));
  row.qty -= amount;
  if (row.qty <= 0) trade.manifest = trade.manifest.filter((m) => m.commodityId !== commodityId);
  const dial = ensureMarketDial(loc, commodityId);
  dial.supply = clampDial(dial.supply + amount);
  return next;
}

/** Every open (and closed) contract — Threads carrying `kind: 'contract'`.
 *  Ordinary Threads (kind unset) are excluded, so the Trade drawer's
 *  contract board doesn't also list every unrelated WHY-question thread. */
function listContracts(campaign) {
  return listThreads(campaign).filter((t) => t.kind === 'contract');
}

function addJournalEntry(campaign, text, source) {
  if (!Array.isArray(campaign.journal)) campaign.journal = [];
  campaign.journal.push({
    id: 'j' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    createdAt: new Date().toISOString(),
    source: source || 'Trade',
    text,
    isHtml: false,
  });
}

/** A contract is a Thread with a few extra reference fields (ADR 0004) —
 *  patronId/originId/destinationId point at existing NPC/Location entities
 *  ("reference by id, don't duplicate stats," the same pattern colony.js's
 *  crew roster already uses) and are all optional, since a GM may roll a
 *  contract's type before deciding who's offering it or where it goes.
 *  Delegates the actual clock/lifecycle creation to addThread — a contract
 *  gets the exact same 7-state lifecycle, priority dial, and Co-Pilot
 *  surfacing as any other thread, then this just patches the trade-specific
 *  fields onto the thread addThread just pushed (always the last one).
 *  Also logs a Journal entry (type/patron/route/payout, resolved to entity
 *  names where set) the same way generateNpc()/rollOracle() already record
 *  what they created — a contract is exactly the kind of session event a
 *  returning GM should see in "Previously on..." without having to dig
 *  through the Trade drawer's contract board to reconstruct it. */
function createContract(campaign, { name = '', type = '', patronId = '', originId = '', destinationId = '', payout = 0, payoutUnit = '', segments = 4, description = '', conflict = '', opportunity = '' } = {}) {
  const next = addThread(campaign, name || type || 'New contract', segments);
  const t = next.threads[next.threads.length - 1];
  Object.assign(t, {
    kind: 'contract',
    type: type || '',
    patronId: patronId || '',
    originId: originId || '',
    destinationId: destinationId || '',
    payout: Math.max(0, Math.round(Number(payout)) || 0),
    // The payout's currency/reward unit ('credits', 'gold marks', 'Cr',
    // 'gp', 'XP'…) — set by generateContract from the stat ruleset; blank
    // for a hand-made contract or a trade-route payout.
    payoutUnit: payoutUnit || '',
    // Free-text flavor fields (UX batch) — same "opt-in, no roll-up
    // mechanic" posture as Faction's HQ/Leadership/Agenda: what the job
    // actually is, what's working against the party, and what upside
    // exists beyond the flat payout.
    description: description || '',
    conflict: conflict || '',
    opportunity: opportunity || '',
  });
  const patron = patronId && getEntity(next, patronId);
  const origin = originId && getEntity(next, originId);
  const destination = destinationId && getEntity(next, destinationId);
  const details = [
    type && `Type: ${type}`,
    patron && `Patron: ${patron.name || 'Unnamed'}`,
    (origin || destination) && `Route: ${origin ? (origin.name || 'Unnamed') : '?'} → ${destination ? (destination.name || 'Unnamed') : '?'}`,
    `Payout: ${t.payout}${t.payoutUnit ? ' ' + t.payoutUnit : ''}`,
  ].filter(Boolean).join(' · ');
  addJournalEntry(next, `New contract: ${t.name}${details ? ' — ' + details : ''}`, 'Trade');
  return { campaign: next, id: t.id };
}

/** Patch a contract's trade-specific fields (type/patron/route/payout/
 *  description/conflict/opportunity) — its clock/status/priority still
 *  go through threads.js's own mutators, since a contract's progress
 *  clock IS an ordinary Thread's. No-op on an id that isn't actually a
 *  contract. */
function updateContract(campaign, id, patch = {}) {
  const next = clone(campaign);
  const t = (next.threads || []).find((x) => x.id === id);
  if (!t || t.kind !== 'contract') return next;
  if (patch.type !== undefined) t.type = patch.type;
  if (patch.patronId !== undefined) t.patronId = patch.patronId;
  if (patch.originId !== undefined) t.originId = patch.originId;
  if (patch.destinationId !== undefined) t.destinationId = patch.destinationId;
  if (patch.payout !== undefined) t.payout = Math.max(0, Math.round(Number(patch.payout)) || 0);
  if (patch.payoutUnit !== undefined) t.payoutUnit = String(patch.payoutUnit || '');
  if (patch.description !== undefined) t.description = patch.description;
  if (patch.conflict !== undefined) t.conflict = patch.conflict;
  if (patch.opportunity !== undefined) t.opportunity = patch.opportunity;
  return next;
}

/** If both origin and destination resolve to real Locations, price a
 *  commodity at each and pay out ten times the gap between them — a real
 *  price delta (buy low, sell high) turned into a contract's stakes,
 *  instead of a flat, hand-tuned number (ADR 0003's "reward is framed as
 *  the price delta... not a flat margin"). Null when there's no priced
 *  route yet — generateContract then uses the game system's own reward
 *  (rollQuestReward) instead. */
function estimateRoutePayout(campaign, originId, destinationId, commodityId) {
  const origin = getEntity(campaign, originId);
  const destination = getEntity(campaign, destinationId);
  const commodity = findCommodity(commodityId);
  if (origin && destination && origin.type === 'location' && destination.type === 'location' && commodity) {
    const delta = Math.abs(priceAt(destination, commodity.id) - priceAt(origin, commodity.id));
    return Math.max(20, delta * 10);
  }
  return null;
}

/** A generated quest's reward and progress clock, in the stat ruleset's
 *  own terms (data/questRewards.js): a few credits for Five Parsecs, gold
 *  marks for Five Leagues, thousands of Cr for Traveller, a gp purse for
 *  D&D 5e — or, for Starforged/Ironsworn, a sworn vow of a rolled rank
 *  whose reward is that rank's experience on a 10-box progress track.
 *  Returns {payout, unit, segments, rank} (rank is null except for a vow). */
function rollQuestReward(statRuleset, rng = Math.random) {
  const rule = QUEST_REWARD_RULES[statRuleset] || DEFAULT_QUEST_REWARD;
  if (rule.vow) {
    const rank = pick(VOW_RANKS, rng);
    return { payout: rank.xp, unit: 'XP', segments: VOW_PROGRESS_BOXES, rank };
  }
  let total = 0;
  if (rule.dice) for (let i = 0; i < rule.dice.count; i++) total += 1 + Math.floor(rng() * rule.dice.sides);
  return { payout: total * (rule.multiplier || 1) + (rule.bonus || 0), unit: rule.unit || '', segments: rule.segments || 4, rank: null };
}

function capitalizeFirst(s) {
  const text = String(s || '');
  return text ? text[0].toUpperCase() + text.slice(1) : text;
}

/** A generated quest's Description, Conflict and Opportunity: an oracle roll
 *  for each, tied to what's actually in play via copilot.js's
 *  gatherSceneContext — the current location, a present faction or bystander
 *  as patron (when the caller didn't pick one), scene antagonists, a rival
 *  faction, a Conflict here, open threads/foreshadowing, and any dial far
 *  enough from its default to matter. An empty scene just reads as the
 *  rolls. Returns {patronId, description, conflict, opportunity}. */
function seedQuestFields(campaign, { job, opposition, benefit, reward, patronId, rng }) {
  const ctx = gatherSceneContext(campaign);
  const scenes = campaign.scenes || [];
  const scene = scenes[scenes.length - 1] || {};
  const sentences = (parts) => parts.filter(Boolean).map((p) => String(p).replace(/[.\s]+$/, '')).join('. ') + '.';
  const named = (list) => list.filter((e) => e && e.name);
  const sceneActors = (ids) => named((ids || []).map((id) => getEntity(campaign, id)));
  const pickOne = (list) => (list.length ? pick(list, rng) : null);

  const factions = named(ctx.factionsHere);
  const patron = patronId
    ? getEntity(campaign, patronId)
    : pickOne([...factions, ...sceneActors(scene.bystanderIds)]);
  const patronName = patron && patron.name;
  const where = (named(ctx.whereLocations)[0] || {}).name;

  let description = capitalizeFirst(job);
  if (patronName) description = `${patronName}${where ? ` at ${where}` : ''} hires the party to ${job}`;
  else if (where) description = `Word at ${where}: someone is needed to ${job}`;

  const foe = pickOne(sceneActors(scene.antagonistIds));
  const rival = pickOne(factions.filter((f) => !patron || f.id !== patron.id));
  const clash = pickOne(named(ctx.conflictsHere));
  const conflict = sentences([
    foe && `${foe.name} is already in the way`,
    rival && `${rival.name} has its own stake in the outcome`,
    capitalizeFirst(opposition),
    clash && `This runs straight into ${clash.name}`,
    ctx.threat >= 7 && 'Danger here is already high, so trouble comes early',
  ]);

  const lead = benefit ? `${patronName || 'The patron'} ${benefit}` : capitalizeFirst(reward);
  const lines = [
    ...named(ctx.openThreads).map((t) => `It could also move "${t.name}" forward`),
    ...ctx.foreshadowing.filter((f) => f.text).map((f) => `It's a chance to pay off: ${f.text}`),
  ];
  const opportunity = sentences([
    lead,
    pickOne(lines),
    ctx.resources <= 3 && 'The pay would ease the party\'s short supplies',
    ctx.reputation <= 3 && 'A clean finish would mend the party\'s standing',
  ]);

  return { patronId: patron ? patron.id : '', description: sentences([description]), conflict, opportunity };
}

/** Generates a whole quest/contract in one action — the 🎲 Generate button
 *  (Navigator's Quests/Contracts, and the Trade/Party copies of the same
 *  section). Type comes from Quests > Quest Type (falling back to Trade &
 *  Cargo > Contract Type); Description, Conflict and Opportunity are seeded
 *  from the oracles and the current scene (seedQuestFields), the job itself
 *  matching the Type via QUEST_BRIEFS. The reward and clock follow the stat
 *  ruleset (rollQuestReward), unless a priced trade route is given.
 *  genrePack/statRuleset default to the campaign's own settings; a caller
 *  inside store.update() (which hands over the raw doc, without the Rules
 *  Profile's overlay) passes store.get()'s instead. Pure/RNG-injectable like
 *  every other roll here; only tests pass a seeded rng. */
function generateContract(campaign, { rng = Math.random, patronId = '', originId = '', destinationId = '', commodityId = '', segments, genrePack, statRuleset } = {}) {
  const next = clone(campaign);
  const settings = next.settings || {};
  genrePack = genrePack || settings.genrePack;
  statRuleset = statRuleset || settings.statRuleset;
  const tables = tablesWithOverrides(next.oracles?.overrides, genrePack) || {};
  const roll = (...paths) => {
    for (const [cat, name] of paths) {
      const t = tables[cat] && tables[cat][name];
      if (Array.isArray(t) && t.length) return String(pick(t, rng));
    }
    return '';
  };
  const type = roll(['Quests', 'Quest Type'], ['Trade & Cargo', 'Contract Type']) || 'Courier';
  const brief = (QUEST_BRIEFS[findGenrePack(genrePack).id] || {})[type];
  const seeded = seedQuestFields(next, {
    job: brief || roll(['Missions', 'Mission Type']),
    opposition: roll(['Quests', 'Opposition'], ['Adventure', 'Complication'], ['Miscellaneous', 'Story Complication']),
    benefit: roll(['Missions', 'Patron Benefit']),
    reward: roll(['Missions', 'Reward']),
    patronId, rng,
  });
  const reward = rollQuestReward(statRuleset, rng);
  const routePayout = estimateRoutePayout(next, originId, destinationId, commodityId);
  const noun = genrePack === 'fantasy' || genrePack === 'dnd5e' ? 'quest' : 'contract';
  const name = reward.rank ? `${reward.rank.label} ${type} vow` : `${type} ${noun}`;
  return createContract(next, {
    name, type, originId, destinationId, ...seeded,
    payout: routePayout != null ? routePayout : reward.payout,
    payoutUnit: routePayout != null ? '' : reward.unit,
    segments: segments != null ? segments : reward.segments,
  });
}

exports.getMarket = getMarket;
exports.setMarketDial = setMarketDial;
exports.economyBiasAt = economyBiasAt;
exports.developmentLevelBiasAt = developmentLevelBiasAt;
exports.biomeBiasAt = biomeBiasAt;
exports.priceAt = priceAt;
exports.listCargoManifest = listCargoManifest;
exports.buyCommodity = buyCommodity;
exports.sellCommodity = sellCommodity;
exports.listContracts = listContracts;
exports.createContract = createContract;
exports.updateContract = updateContract;
exports.rollQuestReward = rollQuestReward;
exports.generateContract = generateContract;

});

register("src/domain/factions.js", function(exports, require){
// factions.js — Phase 10's Faction Pressure Track: Hostile Colony Builder's
// Stability/Instability escalation ladder and 5PFH Compendium's Power/
// Influence/Faction Activity table both reduce to the same shape Threads
// already model — a filling clock with GM-set state, not a live
// simulation. A faction's pressure track is a Thread tagged
// `kind: 'faction-pressure'` with a `factionId` reference, exactly the
// pattern domain/trade.js's Contracts already established for "reuse
// Threads' clock/lifecycle instead of a second implementation" — every
// existing thread mutator (advanceThread, setThreadStatus, setThreadPriority,
// removeThread) works on one unchanged, since it lives in the same
// campaign.threads array as any other thread.
//
// Reconciled against gameplay-mechanics.md's four-dial Influence/Resources/
// Patience/Agenda-Progress proposal (ADR 0008): kept the single-clock
// design deliberately — split later if something concrete needs the
// distinction, not speculatively now.
//
// advanceFactionTurns() below is "faction-turn/rumor automation" scoped
// small and deliberately manual: a GM-triggered bulk advance-and-roll-a-
// rumor action, not a background scheduler or live simulation.

const {getEntity, setFactionStat, addFactionAsset} = require("src/domain/entities.js");
const {addThread, listThreads, advanceThread} = require("src/domain/threads.js");
const {tablesWithOverrides, pick} = require("src/domain/oracles.js");
const {factionPowersGroup} = require("src/data/genrePacks.js");

function clone(c) { try { return structuredClone(c); } catch { return JSON.parse(JSON.stringify(c)); } }

// --- Faction turn mini-game (2026-07-06, docs/adr/0011-swn-cwn-content.md)
// -------------------------------------------------------------------------
// A faction's Force/Cunning/Wealth stats (entities.js) drive a small dice
// resolution instead of pure narration — the concrete "turn-based mini-
// game" a GM can run for a tracked faction, one stat check at a time,
// rather than opposed faction-vs-faction combat (which would need a
// target-faction picker and a second faction's own stats; out of scope for
// this pass — see the ADR's Alternatives Considered). Each action type is
// resolved against whichever stat it plays to; a d10 + that stat vs. a
// flat difficulty (12 for a clean win, 8 to avoid an outright setback)
// keeps the math identical in shape to this app's existing flat/Traveller
// checks (domain/dice.js) rather than inventing a new curve.
const FACTION_ACTION_TYPES = {
  attack: { stat: 'force', verb: 'moves against a rival with open force' },
  scheme: { stat: 'cunning', verb: 'schemes and maneuvers in the shadows' },
  expand: { stat: 'wealth', verb: 'expands its economic reach' },
};

/** Pick an action type weighted toward whichever stat is currently
 *  strongest (a faction plays to its strength more often than not, without
 *  ever being forced into always the same move). */
function pickActionType(faction, rng) {
  const weights = [
    ['attack', Math.max(1, faction.force || 0)],
    ['scheme', Math.max(1, faction.cunning || 0)],
    ['expand', Math.max(1, faction.wealth || 0)],
  ];
  const total = weights.reduce((s, [, w]) => s + w, 0);
  let roll = rng() * total;
  for (const [type, w] of weights) { if ((roll -= w) <= 0) return type; }
  return weights[0][0];
}

/** Resolve one faction's turn as a stat check: d10 + the acting stat vs a
 *  flat difficulty. >=12 is a strong success (the acting stat ticks up, to
 *  a max of 10); 8-11 a partial success (no change); <8 a setback (the
 *  faction's Pressure Track — if it has one — advances an extra tick, on
 *  top of the ordinary per-turn advance). Pure and RNG-injectable, like
 *  every other roll in this app. Returns null for a non-faction/missing
 *  entity. */
function resolveFactionTurn(campaign, factionId, { rng = Math.random, actionType } = {}) {
  const faction = getEntity(campaign, factionId);
  if (!faction || faction.type !== 'faction') return null;
  const type = (actionType && FACTION_ACTION_TYPES[actionType]) ? actionType : pickActionType(faction, rng);
  const { stat, verb } = FACTION_ACTION_TYPES[type];
  const statValue = faction[stat] || 0;
  const roll = Math.floor(rng() * 10) + 1;
  const total = roll + statValue;
  const outcome = total >= 12 ? 'strong success' : total >= 8 ? 'partial success' : 'setback';
  return { factionId, factionName: faction.name || 'Unnamed faction', type, verb, stat, statValue, roll, total, outcome };
}

/** Apply a resolveFactionTurn() result to the campaign: a strong success
 *  raises the acting stat by 1 (capped 10); a setback advances the
 *  faction's Pressure Track by one extra tick if it has one (nothing to
 *  advance otherwise — a faction nobody's tracking just gets the narrative
 *  result with no numeric consequence). */
function applyFactionTurnResult(campaign, result) {
  let next = campaign;
  if (result.outcome === 'strong success') {
    next = setFactionStat(next, result.factionId, result.stat, (getEntity(next, result.factionId)[result.stat] || 0) + 1);
  } else if (result.outcome === 'setback') {
    const track = getPressureTrack(next, result.factionId);
    if (track) next = advanceThread(next, track.id, 1);
  }
  return next;
}

/** Render one resolveFactionTurn() result as a Journal-friendly line. */
function formatFactionTurnResult(r) {
  const label = { attack: 'Attack', scheme: 'Scheme', expand: 'Expand' }[r.type] || r.type;
  return `${r.factionName} ${r.verb} (${label}, ${r.stat} ${r.statValue} + d10 ${r.roll} = ${r.total}) — ${r.outcome}.`;
}

/** Roll a Faction Asset (the pack's factionPowersGroup) and append it directly to
 *  the faction's Assets list — the "roll and structurally add" action, same
 *  shape as generateContract/generateMission rolling a table into a
 *  concrete record instead of just journaling flavor text. No-op (returns
 *  the campaign unchanged, empty asset) if the entity isn't a faction. */
function rollFactionAsset(campaign, factionId, { rng = Math.random, genrePack } = {}) {
  const faction = getEntity(campaign, factionId);
  if (!faction || faction.type !== 'faction') return { campaign, asset: '' };
  const activeGenre = genrePack || (campaign.settings && campaign.settings.genrePack);
  const tables = tablesWithOverrides(campaign.oracles && campaign.oracles.overrides, activeGenre);
  const powers = tables && tables[factionPowersGroup(activeGenre)];
  const list = (powers && powers['Faction Asset']) || [];
  const asset = list.length ? pick(list, rng) : '';
  if (!asset) return { campaign, asset: '' };
  return { campaign: addFactionAsset(campaign, factionId, asset), asset };
}

/** A faction's pressure track, if one has been added — at most one per
 *  faction. Returns null if the faction doesn't exist or has none yet
 *  (opt-in, GM-triggered — not every faction automatically gets a clock
 *  cluttering the WHY question's thread list). */
function getPressureTrack(campaign, factionId) {
  return listThreads(campaign).find((t) => t.kind === 'faction-pressure' && t.factionId === factionId) || null;
}

/** Add a pressure track to a faction entity. No-op if the entity isn't a
 *  faction, or already has one (never creates a duplicate). */
function createPressureTrack(campaign, factionId, segments = 4) {
  const entity = getEntity(campaign, factionId);
  if (!entity || entity.type !== 'faction' || getPressureTrack(campaign, factionId)) return clone(campaign);
  const next = addThread(campaign, `${entity.name || 'Faction'} — Pressure`, segments);
  const t = next.threads[next.threads.length - 1];
  t.kind = 'faction-pressure';
  t.factionId = factionId;
  return next;
}

/** Every faction whose pressure track is filled or nearly filled (>=75%,
 *  the same "one more push" threshold copilot.js's threadUnderPressure
 *  already uses for ordinary threads) and not yet Resolved/Archived — for
 *  a Co-Pilot "this faction is about to act" surfacing, and the
 *  Faction Rumor -> Mission seed link (copilot.js's advise()). */
function factionsUnderPressure(campaign) {
  return listThreads(campaign)
    .filter((t) => t.kind === 'faction-pressure' && !t.done && t.status !== 'resolved' && t.status !== 'archived' && t.filled / t.segments >= 0.75)
    .map((t) => ({ ...t, faction: getEntity(campaign, t.factionId) }))
    .filter((t) => t.faction);
}

/** "Advance Faction Turns" — a GM-triggered bulk action (a button press,
 *  not a background scheduler; Article II, the GM always retains creative
 *  authority), the concrete, small-scoped shape "faction-turn automation"
 *  takes here rather than a live simulation: every faction that already
 *  has a pressure track (skips ones nobody's tracking) advances by one
 *  tick, rolls a "rumor" — a Faction Activity oracle entry (the same table
 *  the Faction card's own 🎲 button rolls) describing what it did — and
 *  (2026-07-06) also resolves one stat-based turn (resolveFactionTurn
 *  above) against its own Force/Cunning/Wealth, so the mini-game's dice
 *  outcome is part of the same bulk action rather than a separate click per
 *  faction. The per-tick advancement itself stays deterministic (+1,
 *  matching the existing per-faction advance button, plus one more on a
 *  mechanical setback) — only the flavor text and the stat check are
 *  randomized. Returns the new campaign plus the rumors rolled, for the UI
 *  to journal (formatFactionTurnRumors below). */
function advanceFactionTurns(campaign, { rng = Math.random, genrePack } = {}) {
  let next = clone(campaign);
  const activeGenre = genrePack || (next.settings && next.settings.genrePack);
  const tables = tablesWithOverrides(next.oracles && next.oracles.overrides, activeGenre);
  const powers = tables && tables[factionPowersGroup(activeGenre)];
  const activityTable = (powers && powers['Faction Activity']) || [];
  const tracks = listThreads(next).filter((t) => t.kind === 'faction-pressure' && !t.done);
  const rumors = [];
  for (const track of tracks) {
    const faction = getEntity(next, track.factionId);
    if (!faction) continue;
    next = advanceThread(next, track.id, 1);
    const activity = activityTable.length ? pick(activityTable, rng) : '';
    const result = resolveFactionTurn(next, track.factionId, { rng });
    if (result) next = applyFactionTurnResult(next, result);
    if (activity || result) rumors.push({ factionName: faction.name || 'Unnamed faction', activity, result });
  }
  return { campaign: next, rumors };
}

/** Render a faction turn's rumors as one Journal-friendly block — each
 *  faction's flavor rumor on one line, its mechanical turn result on the
 *  next. */
function formatFactionTurnRumors(rumors) {
  if (!rumors.length) return 'Faction turn: no factions are being tracked yet — add a Pressure Track to a faction first.';
  const lines = ['Faction turn:'];
  for (const r of rumors) {
    if (r.activity) lines.push(`${r.factionName} ${r.activity}.`);
    if (r.result) lines.push(formatFactionTurnResult(r.result));
  }
  return lines.join('\n');
}

exports.FACTION_ACTION_TYPES = FACTION_ACTION_TYPES;
exports.resolveFactionTurn = resolveFactionTurn;
exports.formatFactionTurnResult = formatFactionTurnResult;
exports.rollFactionAsset = rollFactionAsset;
exports.getPressureTrack = getPressureTrack;
exports.createPressureTrack = createPressureTrack;
exports.factionsUnderPressure = factionsUnderPressure;
exports.advanceFactionTurns = advanceFactionTurns;
exports.formatFactionTurnRumors = formatFactionTurnRumors;

});

register("src/domain/factionTurnEngine.js", function(exports, require){
// factionTurnEngine.js — the SWN Faction Turn Engine (docs/adr/0031-swn-
// faction-turn-engine.md). Pure, DOM-free, RNG-injectable, clone-and-
// return-new-campaign — same discipline as every other domain module.
// Builds a second, deeper layer on top of domain/factions.js's existing
// small Force/Cunning/Wealth mini-game (kept, untouched): real HP/
// FacCreds/XP, a homeworld + Bases of Influence, structured purchasable
// assets transcribed from data/swnFactionData.js, SWN Faction Tags, and a
// current Goal tracked as a Thread (domain/threads.js, `kind:'faction-
// goal'`, mirroring domain/factions.js's own Pressure Track pattern).
//
// Propose-then-confirm (Article II: the GM always retains creative
// authority): proposeFactionTurn()/advanceFactionTurnRound() compute a
// full DRAFT — goal check, action choice, targets, every die roll — against
// a scratch clone of the campaign and return it for review, never
// mutating the real campaign. A draft carries its own fully-resolved
// `resultCampaign` (the scratch clone with the action already applied) so
// commitFactionTurn() is a trivial, deterministic "what you reviewed is
// exactly what lands" — no separate replay step that could re-roll dice.
// A full round chains each faction's proposal against the previous
// faction's resultCampaign (so faction 2's draft already reflects faction
// 1's proposed changes) — by design this makes a round's drafts an
// all-or-nothing batch for this pass: "Commit All" applies the chain,
// there's no partial per-faction accept once a round has been proposed.
// Re-run advanceFactionTurnRound to get a fresh batch instead.
//
// Faction Events follow-up (docs/adr/0031 addendum, same day): every
// event is now a Faction-LOCATION pair, not just a faction record —
// `locationId` (where it happened), `coLocatedFactions` (every OTHER
// faction present there at the time, tagged ally/rival/neutral via
// `relationshipStanceBetween`, frozen at propose time so a later
// relationship change never rewrites history), and `witnessed` (whether
// that location is where the party currently is, per WHERE's own Focus
// @mentions — `getCurrentWhereLocations`). Attack/Seize Planet targeting
// now respects stance: an allied co-located faction is never picked as a
// target, only rivals (falling back to neutral if no rival is present).
//
// Scope, called out explicitly (see the ADR for the full rationale):
// - Seize Planet is a single-turn HP-pool check against total unstealthed
//   non-allied HP at a location, continued via `seizeProgress` across
//   turns — not the book's full multi-turn siege bookkeeping per asset.
// - Change Homeworld always takes exactly one turn to transit — the
//   book's "+1 turn per hex of distance" isn't modeled, since most
//   Locations in a non-Hostile genre pack carry no hex coordinate at all.
// - Use Asset Ability mechanically resolves the ~5 simple dice-for-
//   FacCreds abilities (data/swnFactionData.js's SWN_AUTOMATIC_ASSET_
//   ABILITIES); every other asset's special text is surfaced for the GM
//   to adjudicate and type an outcome for, matching SWN's own stated
//   philosophy that the system "is not meant to be a standalone game
//   that doesn't require GM involvement."
// - Expand Influence's "any rival may free-Attack the new Base" contest
//   is resolved as a flat 1d6 hit against the new Base (not a specific
//   chosen rival asset) for whichever rivals beat the roll — a
//   deliberately simple stand-in for a full targeted counter-attack.
// - "District" is a single-level contains/located_at check (entities.js's
//   isSameDistrict), not deep ancestor recursion.

const {getEntity, updateEntity, listEntities, getRelationshipBetween, isSameDistrict, ensureFactionTurnFields, getContainingLocation, getContainedLocations, getEntityFaction, setEntityFactionMembership, RELATIONSHIP_TYPE_LABEL} = require("src/domain/entities.js");
const {listThreads, addThread, advanceThread, removeThread} = require("src/domain/threads.js");
// Provider indirection (docs/adr/0032): every asset/tag/goal catalog lookup
// below resolves through factionProviderFor(campaign, faction) instead of
// importing data/swnFactionData.js's SWN_* constants directly, so a
// faction's own `rulesProvider` (or the campaign's `settings.
// rulesProviderChoices.factions` default) decides whether it draws from
// SWN's transcribed content or GMAtlas Core's original-content mirror.
const {factionProviderFor} = require("src/data/factionRulesProviders.js");

function clone(c) { try { return structuredClone(c); } catch { return JSON.parse(JSON.stringify(c)); } }

/** Every faction fetch in this module goes through here instead of a raw
 *  getEntity() — backfills factionAssets/basesOfInfluence/etc. on a
 *  possibly-stale entity (one created before these fields existed, or
 *  simply never touched via updateEntity since) before anything in this
 *  module reads/mutates them. Without this, a `for (const a of
 *  f.factionAssets)` on an old entity throws "is not iterable" instead of
 *  treating a missing field as empty — getEntity() itself never lazily
 *  defaults anything (only _create/updateEntity do). No-op/harmless on
 *  an already-current entity. */
function getFaction(campaign, id) {
  const e = getEntity(campaign, id);
  if (e && e.type === 'faction') ensureFactionTurnFields(e);
  return e;
}

// --- dice --------------------------------------------------------------
function rollD10(rng) { return Math.floor(rng() * 10) + 1; }

/** Parses a transcribed dice expression ("2d6+4", "1d4-1", "special", null)
 *  into a rolled total. "special"/null/unparseable expressions roll 0 —
 *  the caller surfaces the raw text for the GM instead (see
 *  useAssetAbility). */
function rollDiceExpr(expr, rng) {
  if (!expr || expr === 'special') return { total: 0, rolls: [], expr: expr || '' };
  const m = String(expr).match(/^(\d+)d(\d+)([+-]\d+)?$/);
  if (!m) return { total: 0, rolls: [], expr };
  const count = Number(m[1]); const sides = Number(m[2]); const mod = m[3] ? Number(m[3]) : 0;
  const rolls = Array.from({ length: count }, () => Math.floor(rng() * sides) + 1);
  return { total: Math.max(0, rolls.reduce((a, b) => a + b, 0) + mod), rolls, expr };
}

function assetMaintenanceCost(provider, catalogId) { return provider.maintenance[catalogId] || 0; }

// --- WHO/WHERE tie-in: relationship stance, co-location, "here" -----------

/** 'ally'|'rival'|'neutral' between two factions — an explicit
 *  allied_with/rival_of relationship type wins outright; otherwise the
 *  existing 0-10 strength dial decides (>=7 ally, <=3 rival); no
 *  relationship at all is 'neutral' (strangers, not enemies). Simple
 *  thresholds on purpose — GM-legible over a continuous/opaque formula,
 *  matching this codebase's existing style (e.g. factionsUnderPressure's
 *  0.75 cutoff). */
function relationshipStanceBetween(campaign, aId, bId) {
  const rel = getRelationshipBetween(campaign, aId, bId);
  if (rel && rel.type === 'allied_with') return 'ally';
  if (rel && rel.type === 'rival_of') return 'rival';
  const strength = rel ? Number(rel.strength) || 0 : 0;
  if (strength >= 7) return 'ally';
  if (rel && strength <= 3) return 'rival';
  return 'neutral';
}

/** Every OTHER faction present at `locationId` — an active, unstealthed
 *  asset there, its homeworld, or a Base of Influence there — each tagged
 *  with `.stance` (relationshipStanceBetween, from `factionId`'s side).
 *  A faction with an asset there gets one entry per asset (so attack
 *  targeting can pick a specific one); a faction present only via
 *  homeworld/Base (no asset) gets a single `asset: null` entry, still
 *  useful for "who else is here" narrative purposes even though it can't
 *  be an attack target. */
function factionsAtLocation(campaign, factionId, locationId) {
  const out = [];
  for (const f of listEntities(campaign, 'faction')) {
    if (f.id === factionId) continue;
    const stance = relationshipStanceBetween(campaign, factionId, f.id);
    const assets = (f.factionAssets || []).filter((a) => a.locationId === locationId && a.status === 'active' && !a.stealthed);
    if (assets.length) {
      for (const asset of assets) out.push({ faction: f, asset, stance });
    } else if (f.homeworldId === locationId || (f.basesOfInfluence || []).some((b) => b.locationId === locationId)) {
      out.push({ faction: f, asset: null, stance });
    }
  }
  return out;
}

/** Every location structurally related to `locationId` — its full
 *  located_at ancestor chain PLUS every location any of those ancestors
 *  (and locationId itself) `contains`, walked breadth-first. A single
 *  `visited` Set both prevents re-queuing (so a cycle, though today's
 *  data can't produce one, can't infinite-loop) and is itself the only
 *  cycle guard the descend phase needs; `maxDepth` additionally caps how
 *  far up the ancestor chain climbing goes, as a second, independent
 *  backstop. Distinct from isSameDistrict's deliberate single-hop scope —
 *  this is the deep-traversal counterpart for "every location anywhere in
 *  this location's whole region," not "is this the same immediate
 *  district." */
function regionLocationIds(campaign, locationId, maxDepth) {
  const visited = new Set();
  if (!locationId) return visited;
  const queue = [locationId];
  visited.add(locationId);
  let cursor = locationId;
  let depth = 0;
  while (depth < maxDepth) {
    const parent = getContainingLocation(campaign, cursor);
    if (!parent || visited.has(parent.id)) break;
    visited.add(parent.id);
    queue.push(parent.id);
    cursor = parent.id;
    depth++;
  }
  let i = 0;
  while (i < queue.length) {
    const id = queue[i]; i++;
    for (const child of getContainedLocations(campaign, id)) {
      if (!visited.has(child.id)) { visited.add(child.id); queue.push(child.id); }
    }
  }
  return visited;
}

/** Every faction with ANY presence — an asset, homeworld, Base of
 *  Influence, a governed location, a location whose own membership
 *  (entities.js's getEntityFaction) points at them, or a manual
 *  `located_at` relationship (the generic relationship system, same one
 *  the Entity Editor's own Relationships block already exposes — the
 *  GM's own "this faction operates here" note when none of the
 *  mechanical SWN fields apply) — anywhere in `locationId`'s full region
 *  (regionLocationIds above), not just the single co-located location
 *  factionsAtLocation checks. This is the "location is the central
 *  determining factor in which factions are active" query: it's what a
 *  Region view or faction-driven mission/encounter generation (Phase C)
 *  reads from instead of reinventing a named Region entity type. Tags
 *  each with `.stance` relative to `anchorFactionId` when one is given
 *  (same shape as factionsAtLocation's own `.stance`); 'neutral' when no
 *  anchor is given, since there's nothing to compare against. */
function factionsInRegion(campaign, locationId, { anchorFactionId = null, maxDepth = 6 } = {}) {
  const regionIds = regionLocationIds(campaign, locationId, maxDepth);
  const out = [];
  for (const f of listEntities(campaign, 'faction')) {
    if (f.id === anchorFactionId) continue;
    const viaAsset = (f.factionAssets || []).some((a) => regionIds.has(a.locationId));
    const viaHomeworld = regionIds.has(f.homeworldId);
    const viaBase = (f.basesOfInfluence || []).some((b) => regionIds.has(b.locationId));
    const viaGoverned = (f.governedLocationIds || []).some((id) => regionIds.has(id));
    const viaRelationship = (f.relationships || []).some((r) => r.type === 'located_at' && regionIds.has(r.to));
    const viaMembership = Array.from(regionIds).some((id) => {
      const owner = getEntityFaction(campaign, id);
      return owner && !owner.synthetic && owner.id === f.id;
    });
    if (viaAsset || viaHomeworld || viaBase || viaGoverned || viaRelationship || viaMembership) {
      const stance = anchorFactionId ? relationshipStanceBetween(campaign, anchorFactionId, f.id) : 'neutral';
      out.push({ faction: f, stance });
    }
  }
  return out;
}

/** Every faction actually present AT `locationId` specifically — active
 *  asset, homeworld, Base of Influence, a governed location, a manual
 *  `located_at` relationship, or the location's own faction membership
 *  (entities.js's getEntityFaction) — the single-location, no-exclusions
 *  counterpart to factionsAtLocation (which always excludes one anchor
 *  faction, for targeting) and factionsInRegion (which walks the whole
 *  containment tree, for a wider "active nearby" query). Used to scope
 *  the Faction Events panel and WHO/WHERE's own presence displays to
 *  whoever's narratively active at WHERE's own current location, rather
 *  than listing every faction in the campaign regardless of relevance. */
function factionsPresentAt(campaign, locationId) {
  if (!locationId) return [];
  const owner = getEntityFaction(campaign, locationId);
  return listEntities(campaign, 'faction').filter((f) => {
    const viaAsset = (f.factionAssets || []).some((a) => a.locationId === locationId && a.status === 'active' && !a.stealthed);
    const viaHomeworld = f.homeworldId === locationId;
    const viaBase = (f.basesOfInfluence || []).some((b) => b.locationId === locationId);
    const viaGoverned = (f.governedLocationIds || []).includes(locationId);
    const viaRelationship = (f.relationships || []).some((r) => r.type === 'located_at' && r.to === locationId);
    const viaMembership = owner && !owner.synthetic && owner.id === f.id;
    return viaAsset || viaHomeworld || viaBase || viaGoverned || viaRelationship || viaMembership;
  });
}

/** Why a faction reads as present at one of `locationIds` — every matching
 *  structural signal (Asset here/Homeworld/Base of Influence/Governs) PLUS
 *  the ACTUAL relationship type linking it to that location, whatever that
 *  type is (direct follow-up request, WHERE's "Factions here": "include
 *  any linked relationship types connecting to a faction" — not just the
 *  'located_at' type factionsPresentAt itself checks for presence, since a
 *  GM may have typed the link as Controls/Allied With/Member Of/etc.
 *  instead; a second direct follow-up corrected the ownership check's own
 *  label from an invented generic "Owns" to the real relationship type
 *  underneath it, RELATIONSHIP_TYPE_LABEL.member_of — getEntityFaction
 *  resolves that ownership via a literal member_of edge, so the label
 *  should say so). A non-empty result IS the membership test for WHERE's
 *  "Factions present here" digest now (locationFactionsBlock,
 *  workspace/index.js — a full replacement for the narrower
 *  factionsPresentAt as that block's own filter, though factionsPresentAt
 *  itself is untouched for its other callers). Small, human-readable
 *  labels for a thumbnail badge row, not a data structure meant for
 *  further logic; a bare 'linked' relationship type is skipped as
 *  uninformative noise (every OTHER typed relationship the location's
 *  side names auto-mirrors back onto the faction's own side as generic
 *  'linked' unless it's located_at/contains — see entities.js's _link —
 *  so showing it here would just echo whichever real label already fired). */
function factionPresenceReasons(campaign, faction, locationIds) {
  const ids = new Set(Array.isArray(locationIds) ? locationIds : [locationIds]);
  const reasons = [];
  if ((faction.factionAssets || []).some((a) => ids.has(a.locationId) && a.status === 'active' && !a.stealthed)) reasons.push('Asset here');
  if (ids.has(faction.homeworldId)) reasons.push('Homeworld');
  if ((faction.basesOfInfluence || []).some((b) => ids.has(b.locationId))) reasons.push('Base of Influence');
  if ((faction.governedLocationIds || []).some((id) => ids.has(id))) reasons.push('Governs');
  for (const id of ids) {
    const owner = getEntityFaction(campaign, id);
    if (owner && !owner.synthetic && owner.id === faction.id) { reasons.push(RELATIONSHIP_TYPE_LABEL.member_of); break; }
  }
  for (const r of faction.relationships || []) {
    if (r.type !== 'linked' && ids.has(r.to)) {
      const label = RELATIONSHIP_TYPE_LABEL[r.type] || r.label || 'Linked';
      if (!reasons.includes(label)) reasons.push(label);
    }
  }
  return reasons;
}

/** factionsAtLocation entries actually eligible as an Attack/Seize Planet
 *  target — must have a real asset (a Base/homeworld-only presence can't
 *  be attacked directly) and must NOT be an ally. Rivals are preferred;
 *  neutrals are only a fallback when no rival is present (see
 *  pickAttackTarget). */
function attackableTargetsAt(campaign, factionId, locationId) {
  return factionsAtLocation(campaign, factionId, locationId).filter((e) => e.asset && e.stance !== 'ally');
}

function pickAttackTarget(campaign, factionId, locationId, rng) {
  const candidates = attackableTargetsAt(campaign, factionId, locationId);
  if (!candidates.length) return null;
  const rivals = candidates.filter((e) => e.stance === 'rival');
  const pool = rivals.length ? rivals : candidates;
  return pool[Math.floor(rng() * pool.length)];
}

/** Deduplicated {factionId, factionName, stance} for every OTHER faction
 *  co-located at `locationId` — one entry per faction regardless of how
 *  many assets it has there. Frozen onto an event at propose time (see
 *  makeEvent) so a later relationship change never rewrites history. */
function coLocatedSummary(campaign, factionId, locationId) {
  const seen = new Map();
  for (const entry of factionsAtLocation(campaign, factionId, locationId)) {
    if (!seen.has(entry.faction.id)) seen.set(entry.faction.id, { factionId: entry.faction.id, factionName: entry.faction.name || 'Unnamed faction', stance: entry.stance });
  }
  return Array.from(seen.values());
}

/** Every Location entity currently @mentioned in WHERE's own Focus text —
 *  "where the party is right now," derived from the existing @mention
 *  infrastructure rather than a new structured pointer (a past redesign
 *  deliberately removed context.where.entityIds as duplicative of Focus;
 *  reviving that reasoning here rather than refighting it). */
// Direct follow-up request ("remove Focus... under WHERE it happens"):
// this used to scan context.where.summary for @mentions — WHERE no
// longer has a Focus field, so the current scene's own curated
// locationIds (scenes.js, GM-picked via WHERE's "Location details" "+")
// is the one source of truth now, same "no free-text derivation, an
// explicit list instead" shift WHO's Actors went through earlier. The
// first entry is "the" primary current location everywhere that concept
// is used.
function getCurrentWhereLocations(campaign) {
  const scenes = campaign.scenes || [];
  const scene = scenes[scenes.length - 1];
  if (!scene) return [];
  return (scene.locationIds || []).map((id) => getEntity(campaign, id)).filter(Boolean);
}

/** Whether `locationId` is where the party currently is (or shares an
 *  immediate district with one of those locations) — the "witnessed vs.
 *  news" split for Faction Events. */
function isWitnessedAt(campaign, locationId) {
  if (!locationId) return false;
  return getCurrentWhereLocations(campaign).some((loc) => isSameDistrict(campaign, locationId, loc.id));
}

// Event scope (docs/adr/0032): a plain lookup, not hardcoded branching, so
// a later action type only needs one new entry here. 'self' = internal to
// the acting faction alone; 'faction-vs-faction' = a direct two-faction
// exchange (Attack); 'faction-vs-world' = touches a whole location and
// everyone present there (Expand Influence's contested roll, Seize
// Planet) — the only scope that generates regional faction responses
// (generateFactionResponses below) and nudges the WHAT tab's Threat
// tracker on commit (see the WHAT-tab consequence hook below).
const ACTION_SCOPE = {
  buyAsset: 'self', sellAsset: 'self', repairAssetOrFaction: 'self', refitAsset: 'self',
  useAssetAbility: 'self', changeHomeworld: 'self', none: 'self', busy: 'self',
  attack: 'faction-vs-faction',
  expandInfluence: 'faction-vs-world', seizePlanet: 'faction-vs-world',
};

function makeEvent(campaign, { turnNumber, factionId, factionName, action, locationId, targets = [], rollsSummary = '', outcome = 'info', narrative }) {
  return {
    id: 'fev_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    turnNumber, createdAt: new Date().toISOString(),
    factionId, factionName, action, locationId, targets, rollsSummary, outcome, narrative,
    scope: ACTION_SCOPE[action] || 'self',
    coLocatedFactions: locationId ? coLocatedSummary(campaign, factionId, locationId) : [],
    witnessed: isWitnessedAt(campaign, locationId),
  };
}

// --- regional faction responses (faction-vs-world events only) ---------

/** Templated reaction statements, keyed by stance — deliberately small
 *  (2-3 phrasings each), `rng`-picked like every other faction-turn
 *  randomness. Reads generically off any event shape (locationId/
 *  coLocatedFactions/scope), not the SWN action set specifically, so a
 *  future non-faction-turn "world event" generator (a regional hazard,
 *  the 5PFH-style "the party must flee, and every local faction reacts"
 *  case named when this was scoped) can reuse it too — not built here,
 *  called out explicitly as future work. */
const RESPONSE_TEMPLATES = {
  ally: [
    'reinforces its own position nearby, wary of the disruption.',
    'moves to shield its own assets from the fallout.',
  ],
  rival: [
    'moves to exploit the opening while it lasts.',
    'presses its own advantage in the confusion.',
  ],
  neutral: [
    'holds position, watching to see how this settles.',
    'quietly re-routes its own activity away from the disruption.',
  ],
};

/** For a `'faction-vs-world'` event only: one `{factionId, factionName,
 *  stance, statement}` per faction in `event.coLocatedFactions` — a real
 *  logged reaction for everyone the event affects, not just a co-located
 *  tag. Returns `[]` for any other scope (a self/faction-vs-faction event
 *  doesn't ripple out to the whole region the same way). */
function generateFactionResponses(campaign, event, rng = Math.random) {
  if (!event || event.scope !== 'faction-vs-world') return [];
  return (event.coLocatedFactions || []).map((entry) => {
    const pool = RESPONSE_TEMPLATES[entry.stance] || RESPONSE_TEMPLATES.neutral;
    const statement = pool[Math.floor(rng() * pool.length)];
    return { factionId: entry.factionId, factionName: entry.factionName, stance: entry.stance, statement };
  });
}

// --- read-aloud narrative expansion -------------------------------------

const ACTION_VERB_PHRASE = {
  attack: 'launches an attack',
  buyAsset: 'moves to acquire new assets',
  sellAsset: 'liquidates assets',
  repairAssetOrFaction: 'moves to repair and recover',
  refitAsset: 'refits its holdings',
  expandInfluence: 'moves to plant a new foothold',
  changeHomeworld: 'relocates its base of operations',
  seizePlanet: 'moves against the planet itself',
  useAssetAbility: 'puts a key asset into motion',
  none: 'stays quiet this turn',
  busy: 'remains in transit',
};

/** Template-composes a 2-4 sentence GM-facing paragraph from fields
 *  already known on a committed event — no RNG, purely recombines already-
 *  rolled/resolved facts (action, outcome, location, witnessed-vs-news
 *  framing, co-located factions' stance, `responses` if present), same
 *  spirit as scenes.js's recomposeSceneText. Meant to be read aloud as-is,
 *  or hand-edited first — the caller stores the result on `event.
 *  readAloud`, separate from the terse `narrative` used in the compact
 *  feed row. */
function expandEventReadAloud(campaign, event) {
  if (!event) return '';
  const loc = event.locationId ? getEntity(campaign, event.locationId) : null;
  const locName = loc ? loc.name : 'an unnamed world';
  const verb = ACTION_VERB_PHRASE[event.action] || 'takes action';
  const factionName = event.factionName || 'A faction';
  const sentences = [];
  sentences.push(event.witnessed
    ? `Before your eyes, ${factionName} ${verb} at ${locName}.`
    : `Word reaches you: ${factionName} ${verb} at ${locName}.`);
  if (event.narrative) sentences.push(event.narrative);
  if (event.outcome === 'failure') sentences.push('The attempt comes to nothing.');
  else if (event.outcome === 'partial') sentences.push('The outcome is mixed, and unresolved tension remains.');
  const rivals = (event.coLocatedFactions || []).filter((c) => c.stance === 'rival');
  const allies = (event.coLocatedFactions || []).filter((c) => c.stance === 'ally');
  if (rivals.length) sentences.push(`${rivals.map((r) => r.factionName).join(', ')} ${rivals.length === 1 ? 'has' : 'have'} a stake in what happens here, and won't sit idle.`);
  if (allies.length) sentences.push(`${allies.map((a) => a.factionName).join(', ')} ${allies.length === 1 ? 'stands' : 'stand'} ready to back the effort.`);
  if (event.responses && event.responses.length) {
    for (const r of event.responses) sentences.push(`${r.factionName} ${r.statement}`);
  }
  return sentences.join(' ');
}

/** Sets (or hand-edits) a committed event's `readAloud` field — used both
 *  by the initial "Expand to Read-Aloud" generation (expandEventReadAloud
 *  above) and by the GM's own edits typed into the resulting field
 *  afterward, so both paths go through the same clone-and-return mutator
 *  rather than the UI touching `factionEvents` directly. */
function setEventReadAloud(campaign, eventId, text) {
  const next = clone(campaign);
  const event = (next.factionEvents || []).find((e) => e.id === eventId);
  if (event) event.readAloud = text;
  return next;
}

// WHAT-tab consequence hook (docs/adr/0032): a witnessed, non-failure
// faction-vs-world event nudges Threat up by 1 (clamped at 10) — mirrors
// session.js's continueStory() "consequences gently escalate" heuristic
// exactly, just keyed off the event's own scope/outcome instead of regex-
// sniffed scene text. No new tracker invented; Reputation is deliberately
// left untouched here (no defensible rule yet for which faction outcomes
// should swing it — a scope cut, not an oversight).
function applyWhatTabConsequence(campaign, event) {
  if (!event || event.scope !== 'faction-vs-world' || !event.witnessed || event.outcome === 'failure') return;
  campaign.context = campaign.context || {};
  campaign.context.what = campaign.context.what || {};
  campaign.context.what.threat = Math.min(10, (campaign.context.what.threat || 0) + 1);
}

function pushEvent(campaign, event) {
  if (!Array.isArray(campaign.factionEvents)) campaign.factionEvents = [];
  campaign.factionEvents.push(event);
  applyWhatTabConsequence(campaign, event);
}

// --- goal tracking (reuses Threads, mirrors factions.js's Pressure Track) --

function getFactionGoalTrack(campaign, factionId) {
  return listThreads(campaign).find((t) => t.kind === 'faction-goal' && t.factionId === factionId) || null;
}

/** Creates (or replaces a stale) goal-progress Thread for a faction's
 *  current goal. No-op if the faction/goal is missing or the track
 *  already tracks this exact goal. Thread `segments` = the goal's
 *  computed difficulty (clamped 2-12 by addThread itself — a difficulty-1
 *  goal reads as a 2-segment clock, the same clamp every other Thread in
 *  this app already accepts). */
function ensureFactionGoalTrack(campaign, factionId, goalId) {
  const faction = getFaction(campaign, factionId);
  const goal = faction ? factionProviderFor(campaign, faction).findGoal(goalId) : null;
  if (!faction || !goal) return clone(campaign);
  const existing = getFactionGoalTrack(campaign, factionId);
  if (existing && existing.goalId === goalId) return clone(campaign);
  let next = clone(campaign);
  if (existing) next = removeThread(next, existing.id);
  const difficulty = Math.max(1, Math.round(typeof goal.difficulty === 'function' ? goal.difficulty(faction) : goal.difficulty));
  next = addThread(next, `${faction.name || 'Faction'} — ${goal.name}`, difficulty);
  const t = next.threads[next.threads.length - 1];
  t.kind = 'faction-goal';
  t.factionId = factionId;
  t.goalId = goalId;
  return next;
}

/** Applies whichever delta matches the faction's CURRENT goal's countable
 *  criteria (data/swnFactionData.js's `goal.countable`), and — if that
 *  completes the track — awards XP equal to the goal's difficulty and
 *  clears currentGoalId so a new one can be picked next turn. No-op if
 *  the faction has no active goal/track, or the delta doesn't match. */
function advanceGoalProgress(campaign, factionId, delta = {}) {
  let next = clone(campaign);
  const faction = getFaction(next, factionId);
  if (!faction || !faction.currentGoalId) return next;
  const goal = factionProviderFor(next, faction).findGoal(faction.currentGoalId);
  const track = getFactionGoalTrack(next, factionId);
  if (!goal || !track) return next;
  const c = goal.countable || {};
  let amount = 0;
  if (c.statTypeDestroyed && delta.statTypeDestroyed === c.statTypeDestroyed) amount += delta.count || 1;
  if (c.hpDamageDealt && delta.hpDamageDealt) amount += delta.hpDamageDealt;
  if (c.facCredsSpent && delta.facCredsSpent) amount += delta.facCredsSpent;
  if (c.expandInfluence && delta.expandInfluence) amount += 1;
  if (c.seizePlanet && delta.seizePlanet) amount += 1;
  if (c.destroyRivalFaction && delta.destroyRivalFaction) amount += goal.difficulty();
  if (!amount) return next;
  next = advanceThread(next, track.id, amount);
  const updated = getFactionGoalTrack(next, factionId);
  if (updated && updated.done) {
    const f = getFaction(next, factionId);
    next = updateEntity(next, factionId, { xp: (f.xp || 0) + updated.segments, currentGoalId: '' });
  }
  return next;
}

/** Factions whose current goal is >=75% complete and not yet resolved —
 *  mirrors domain/factions.js's factionsUnderPressure exactly, for
 *  copilot.js's advise(). */
function factionsWithGoalNearCompletion(campaign) {
  return listThreads(campaign)
    .filter((t) => t.kind === 'faction-goal' && !t.done && t.status !== 'resolved' && t.status !== 'archived' && t.filled / t.segments >= 0.75)
    .map((t) => ({ ...t, faction: getFaction(campaign, t.factionId) }))
    .filter((t) => t.faction);
}

/** A single read-only rollup of everything this faction "is" — its own
 *  record, every entity actually a member of it (real member_of edges,
 *  not the synthetic Unaligned fallback), the locations it governs, its
 *  current goal (definition + progress track), its allies/rivals, and its
 *  slice of the campaign-wide Faction Events log. This is what "the
 *  faction forms track all faction history, NPCs, assets, colonies, and
 *  storyline" cashes out to: one query a faction's inspector card reads,
 *  not a new stored record — everything here is already tracked
 *  elsewhere (entities' relationships, the faction's own fields, the
 *  shared event log); this just assembles the view. Returns null for a
 *  missing/non-faction id. */
function getFactionDossier(campaign, factionId) {
  const faction = getFaction(campaign, factionId);
  if (!faction || faction.type !== 'faction') return null;
  const memberEntities = listEntities(campaign)
    .filter((e) => e.id !== factionId && (e.relationships || []).some((r) => r.type === 'member_of' && r.to === factionId));
  const governedLocations = (faction.governedLocationIds || []).map((id) => getEntity(campaign, id)).filter(Boolean);
  const provider = factionProviderFor(campaign, faction);
  const goalDefinition = faction.currentGoalId ? provider.findGoal(faction.currentGoalId) : null;
  const goalTrack = getFactionGoalTrack(campaign, factionId);
  const allies = []; const rivals = [];
  for (const other of listEntities(campaign, 'faction')) {
    if (other.id === factionId) continue;
    const stance = relationshipStanceBetween(campaign, factionId, other.id);
    if (stance === 'ally') allies.push(other);
    else if (stance === 'rival') rivals.push(other);
  }
  const events = (campaign.factionEvents || []).filter((e) => e.factionId === factionId);
  return { faction, memberEntities, governedLocations, goal: { definition: goalDefinition, track: goalTrack }, allies, rivals, events };
}

/** Living Faction Engine Phase B — a derived read, not a stored flag
 *  (same "compute on every read" convention as isRelationshipFlagged/
 *  overlookedThreads): true once enough scenes have passed since the
 *  last committed faction round to make one due. `settings.factionPacing`
 *  is additive/lazy — an old campaign without it reads as the schema
 *  default (3 scenes) rather than throwing. */
function isFactionRoundDue(campaign) {
  const p = (campaign.settings && campaign.settings.factionPacing) || { scenesPerRound: 3, scenesSinceLastRound: 0 };
  const threshold = p.scenesPerRound != null ? p.scenesPerRound : 3;
  if (threshold <= 0) return false; // 0 (or negative) is the "off" setting, not "always due"
  return (p.scenesSinceLastRound || 0) >= threshold;
}

/** Resets the pacing counter — called once a faction turn is actually
 *  committed (Step or Full Round), never on propose/discard, since only a
 *  committed turn represents party activity actually being "spent." */
function resetFactionPacing(campaign) {
  const next = clone(campaign);
  next.settings = next.settings || {};
  const p = next.settings.factionPacing || { scenesPerRound: 3, scenesSinceLastRound: 0 };
  next.settings.factionPacing = { ...p, scenesSinceLastRound: 0 };
  return next;
}

/** Every committed Faction Event grouped by `turnNumber`, most recent
 *  round first — Round History browsing (Living Faction Engine Phase D).
 *  A pure grouping over the existing log; no new stored state. */
function factionEventsByRound(campaign, { factionId } = {}) {
  const log = Array.isArray(campaign.factionEvents) ? campaign.factionEvents : [];
  const filtered = factionId ? log.filter((e) => e.factionId === factionId) : log;
  const byRound = new Map();
  for (const e of filtered) {
    const tn = e.turnNumber || 0;
    if (!byRound.has(tn)) byRound.set(tn, []);
    byRound.get(tn).push(e);
  }
  return Array.from(byRound.entries())
    .sort((a, b) => b[0] - a[0])
    .map(([turnNumber, events]) => ({ turnNumber, events }));
}

/** Faction Conflict's escalation clock — a Thread (`kind:
 *  'faction-conflict-escalation', conflictId`), mirroring the faction
 *  goal track's exact shape/UI (the same pip clock, the same advance/
 *  back controls) — deliberately the single most prominent piece of a
 *  conflict's UI, per the design's own validation against GM-community
 *  sentiment on Blades in the Dark-style clocks being the most beloved
 *  "track pressure without homework" pattern in the hobby. */
function getConflictEscalationTrack(campaign, conflictId) {
  return listThreads(campaign).find((t) => t.kind === 'faction-conflict-escalation' && t.conflictId === conflictId) || null;
}

/** Creates a conflict's escalation Thread the first time it's needed —
 *  no-op if one already exists. Unlike a faction's goal track (replaced
 *  whenever the goal changes), a conflict's escalation clock is
 *  permanent for that conflict's whole lifetime — there's nothing to
 *  swap it for. `segments` defaults to 6 (Cold/Simmering/Skirmish/
 *  Active/Escalated/Open War), but a GM can size a shorter/longer
 *  conflict differently at creation time. */
function ensureConflictEscalationTrack(campaign, conflictId, segments = 6) {
  const conflict = getEntity(campaign, conflictId);
  if (!conflict || conflict.type !== 'conflict') return clone(campaign);
  if (getConflictEscalationTrack(campaign, conflictId)) return clone(campaign);
  let next = clone(campaign);
  next = addThread(next, conflict.name || 'Conflict', segments);
  const t = next.threads[next.threads.length - 1];
  t.kind = 'faction-conflict-escalation';
  t.conflictId = conflictId;
  return next;
}

/** Faction Conflict × Faction Turn Engine integration (docs/adr/0036
 *  follow-up — closing the "the clock is GM-vibes-only, disconnected
 *  from what the dice actually resolved" gap): given the ids of one or
 *  more just-COMMITTED Faction Events, finds every Conflict whose
 *  `involves` relationships plausibly cover BOTH sides of that event —
 *  the acting faction, plus either the Attack's named defender
 *  (`event.targets[0].factionId`, the only action with one specific
 *  named opponent) or any RIVAL co-located faction for a faction-vs-
 *  world event (Expand Influence/Seize Planet have no single named
 *  opponent — every co-located rival is a plausible match). A
 *  SUGGESTION only — this never advances anything itself; the caller
 *  surfaces each match for the GM to accept (advance the conflict's own
 *  escalation Thread, same `advanceThread` every other clock in this
 *  app already uses) or dismiss (Article II — the dice informed this,
 *  they didn't decide it). */
function suggestedConflictEscalations(campaign, eventIds) {
  if (!eventIds || !eventIds.length) return [];
  const events = (campaign.factionEvents || []).filter((e) => eventIds.includes(e.id));
  if (!events.length) return [];
  const conflicts = listEntities(campaign, 'conflict');
  if (!conflicts.length) return [];
  const out = [];
  for (const event of events) {
    if (event.scope !== 'faction-vs-faction' && event.scope !== 'faction-vs-world') continue;
    const opposingIds = new Set();
    if (event.scope === 'faction-vs-faction') {
      const defenderId = event.targets && event.targets[0] && event.targets[0].factionId;
      if (defenderId) opposingIds.add(defenderId);
    } else {
      for (const c of event.coLocatedFactions || []) if (c.stance === 'rival') opposingIds.add(c.factionId);
    }
    if (!opposingIds.size) continue;
    for (const conflict of conflicts) {
      const involvedIds = new Set((conflict.relationships || []).filter((r) => r.type === 'involves').map((r) => r.to));
      if (!involvedIds.has(event.factionId)) continue;
      if (![...opposingIds].some((id) => involvedIds.has(id))) continue;
      out.push({ conflictId: conflict.id, conflictName: conflict.name || 'Unnamed conflict', eventId: event.id, factionName: event.factionName, narrative: event.narrative });
    }
  }
  return out;
}

// --- turn bookkeeping ----------------------------------------------------

function startTurnRound(campaign) {
  const next = clone(campaign);
  next.factionTurnNumber = (next.factionTurnNumber || 0) + 1;
  return next;
}

function initiativeOrder(factionIds, rng) {
  const n = Math.max(1, factionIds.length);
  const die = Math.floor(rng() * n);
  return factionIds.slice(die).concat(factionIds.slice(0, die));
}

/** FacCred income + asset maintenance for one faction's turn — half Wealth
 *  (rounded up) plus a quarter of Force+Cunning (rounded down), per SWN.
 *  Maintenance is the sum of each active asset's per-turn cost
 *  (data/swnFactionData.js's SWN_ASSET_MAINTENANCE) plus a 1-FacCred
 *  surcharge for every asset held past a stat's rating cap. If the
 *  faction can't cover total maintenance, every asset actually costing
 *  upkeep gets `missedMaintenance` bumped; two consecutive misses loses
 *  the asset (checked here, applied by the caller). */
function payFactionUpkeep(campaign, factionId) {
  let next = clone(campaign);
  const f = getFaction(next, factionId);
  if (!f || f.type !== 'faction') return { campaign: next, income: 0, maintenance: 0, lostAssetIds: [] };
  const provider = factionProviderFor(next, f);
  const income = Math.ceil((f.wealth || 0) / 2) + Math.floor(((f.force || 0) + (f.cunning || 0)) / 4);
  const active = (f.factionAssets || []).filter((a) => a.status === 'active');
  let maintenance = 0;
  for (const a of active) maintenance += assetMaintenanceCost(provider, a.catalogId);
  for (const statType of ['force', 'cunning', 'wealth']) {
    const count = active.filter((a) => a.statType === statType).length;
    const rating = f[statType] || 0;
    if (count > rating) maintenance += (count - rating);
  }
  const balance = (f.facCreds || 0) + income;
  const lostAssetIds = [];
  let facCreds = balance;
  if (balance < maintenance) {
    facCreds = 0; // every FacCred goes to partial upkeep; the shortfall is a missed turn
    for (const a of active) {
      if (assetMaintenanceCost(provider, a.catalogId) > 0) {
        a.missedMaintenance = (a.missedMaintenance || 0) + 1;
        if (a.missedMaintenance >= 2) lostAssetIds.push(a.id);
      }
    }
  } else {
    facCreds = balance - maintenance;
    for (const a of active) a.missedMaintenance = 0;
  }
  if (lostAssetIds.length) f.factionAssets = f.factionAssets.filter((a) => !lostAssetIds.includes(a.id));
  f.facCreds = facCreds;
  // Assets bought last turn (status 'assembling') come online now.
  for (const a of f.factionAssets) if (a.status === 'assembling') a.status = 'active';
  return { campaign: next, income, maintenance, lostAssetIds };
}

function pickGoalIfNone(campaign, factionId, { rng = Math.random } = {}) {
  let next = clone(campaign);
  const f = getFaction(next, factionId);
  if (!f || f.type !== 'faction' || f.currentGoalId) return next;
  const goals = factionProviderFor(next, f).goals;
  const goal = goals[Math.floor(rng() * goals.length)];
  next = updateEntity(next, factionId, { currentGoalId: goal.id });
  next = ensureFactionGoalTrack(next, factionId, goal.id);
  return next;
}

// --- helpers ---------------------------------------------------------------

function activeAsset(faction, factionAssetId) {
  return (faction.factionAssets || []).find((a) => a.id === factionAssetId) || null;
}

function catalogFor(provider, factionAsset) {
  return factionAsset ? provider.findAssetAnyStat(factionAsset.catalogId) : null;
}

function locationsOf(faction) {
  const set = new Set();
  if (faction.homeworldId) set.add(faction.homeworldId);
  for (const b of faction.basesOfInfluence || []) set.add(b.locationId);
  return set;
}

// --- actions -----------------------------------------------------------

/** Buy one asset from the catalog on the faction's homeworld or a world
 *  with one of its own Bases of Influence. Requires a sufficient stat
 *  rating and (loosely) a sufficient location tech level — this app's
 *  Location.techLevel is free text (docs/adr/0026), so the check is
 *  advisory only when a numeric techLevel is actually present. The new
 *  asset is 'assembling' (usable from next turn's upkeep pass). */
function buyAsset(campaign, { factionId, statType, catalogId, locationId, turnNumber } = {}) {
  const next = clone(campaign);
  const f = getFaction(next, factionId);
  const provider = factionProviderFor(next, f);
  const catalog = (provider.assets[statType] || []).find((a) => a.id === catalogId);
  const validLocation = f && (f.homeworldId === locationId || (f.basesOfInfluence || []).some((b) => b.locationId === locationId));
  if (!f || f.type !== 'faction' || !catalog || !validLocation || (f[statType] || 0) < catalog.rating || (f.facCreds || 0) < catalog.cost) {
    return { campaign: next, event: makeEvent(next, { turnNumber, factionId, factionName: f && f.name, action: 'buyAsset', locationId, outcome: 'failure', narrative: `Could not buy ${catalog ? catalog.name : catalogId} — insufficient rating, FacCreds, or an invalid location.` }) };
  }
  f.facCreds -= catalog.cost;
  const id = 'fa_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  f.factionAssets.push({ id, catalogId, statType, locationId, hp: catalog.hp, stealthed: false, status: 'assembling', missedMaintenance: 0 });
  const event = makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'buyAsset', locationId, targets: [{ locationId }], outcome: 'success', narrative: `${f.name} purchases ${catalog.name} (${statType} ${catalog.rating}) for ${catalog.cost} FacCred(s).` });
  return { campaign: next, event, factionAssetId: id };
}

/** Sell an asset for half its catalog cost (rounded down). */
function sellAsset(campaign, { factionId, factionAssetId, turnNumber } = {}) {
  const next = clone(campaign);
  const f = getFaction(next, factionId);
  const provider = factionProviderFor(next, f);
  const asset = f && activeAsset(f, factionAssetId);
  const catalog = catalogFor(provider, asset);
  if (!f || f.type !== 'faction' || !asset || !catalog) {
    return { campaign: next, event: makeEvent(next, { turnNumber, factionId, factionName: f && f.name, action: 'sellAsset', locationId: asset && asset.locationId, outcome: 'failure', narrative: 'No such asset to sell.' }) };
  }
  const refund = Math.floor(catalog.cost / 2);
  f.facCreds = (f.facCreds || 0) + refund;
  f.factionAssets = f.factionAssets.filter((a) => a.id !== factionAssetId);
  const event = makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'sellAsset', locationId: asset.locationId, outcome: 'success', narrative: `${f.name} sells ${catalog.name} for ${refund} FacCred(s).` });
  return { campaign: next, event };
}

/** Repair a damaged asset (heal = faction's rating in the asset's own
 *  stat per "increment," cost = 1+2+3+...+increments FacCreds) or, with
 *  no `factionAssetId`, heal the faction itself by the rounded average of
 *  its highest and lowest stat (flat 1 FacCred, per SWN). */
function repairAssetOrFaction(campaign, { factionId, factionAssetId = null, increments = 1, turnNumber } = {}) {
  const next = clone(campaign);
  const f = getFaction(next, factionId);
  if (!f || f.type !== 'faction') return { campaign: next, event: makeEvent(next, { turnNumber, factionId, action: 'repairAssetOrFaction', outcome: 'failure', narrative: 'No such faction.' }) };
  const provider = factionProviderFor(next, f);
  if (factionAssetId) {
    const asset = activeAsset(f, factionAssetId);
    const catalog = catalogFor(provider, asset);
    if (!asset || !catalog) return { campaign: next, event: makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'repairAssetOrFaction', outcome: 'failure', narrative: 'No such asset to repair.' }) };
    const n = Math.max(1, increments | 0);
    const cost = (n * (n + 1)) / 2;
    if ((f.facCreds || 0) < cost) return { campaign: next, event: makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'repairAssetOrFaction', locationId: asset.locationId, outcome: 'failure', narrative: `Not enough FacCreds to repair ${catalog.name}.` }) };
    f.facCreds -= cost;
    const healPer = f[asset.statType] || 1;
    asset.hp = Math.min(catalog.hp, asset.hp + healPer * n);
    const event = makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'repairAssetOrFaction', locationId: asset.locationId, outcome: 'success', narrative: `${f.name} repairs ${catalog.name} for ${healPer * n} HP (${cost} FacCred(s)).` });
    return { campaign: next, event };
  }
  if ((f.facCreds || 0) < 1) return { campaign: next, event: makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'repairAssetOrFaction', locationId: f.homeworldId, outcome: 'failure', narrative: 'Not enough FacCreds to repair.' }) };
  f.facCreds -= 1;
  const stats = [f.force || 0, f.cunning || 0, f.wealth || 0];
  const heal = Math.round((Math.max(...stats) + Math.min(...stats)) / 2);
  const maxHp = computeMaxHp(f);
  f.hp = Math.min(maxHp, (f.hp || 0) + heal);
  const event = makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'repairAssetOrFaction', locationId: f.homeworldId, outcome: 'success', narrative: `${f.name} recovers ${heal} HP.` });
  return { campaign: next, event };
}

function computeMaxHp(f) {
  // Mirrors entities.js's computeFactionMaxHp without importing it (that
  // module imports data only, this avoids a domain<->domain cross-import
  // cycle risk) — same SWN_XP_TABLE-backed formula.
  const table = { 1: 1, 2: 2, 3: 4, 4: 6, 5: 9, 6: 12, 7: 16, 8: 20 };
  const hpFor = (v) => table[Math.max(1, Math.min(8, Math.round(Number(v) || 0)))] || 1;
  return 4 + hpFor(f.force) + hpFor(f.cunning) + hpFor(f.wealth);
}

/** Swap one asset for another catalog entry of the same stat track,
 *  paying the difference if the new one costs more. Refitted asset goes
 *  'assembling' again. */
function refitAsset(campaign, { factionId, factionAssetId, newCatalogId, turnNumber } = {}) {
  const next = clone(campaign);
  const f = getFaction(next, factionId);
  const provider = factionProviderFor(next, f);
  const asset = f && activeAsset(f, factionAssetId);
  const oldCatalog = catalogFor(provider, asset);
  const newCatalog = asset && (provider.assets[asset.statType] || []).find((a) => a.id === newCatalogId);
  if (!f || f.type !== 'faction' || !asset || !oldCatalog || !newCatalog) {
    return { campaign: next, event: makeEvent(next, { turnNumber, factionId, factionName: f && f.name, action: 'refitAsset', locationId: asset && asset.locationId, outcome: 'failure', narrative: 'No such asset/refit target.' }) };
  }
  const diff = Math.max(0, newCatalog.cost - oldCatalog.cost);
  if ((f.facCreds || 0) < diff) return { campaign: next, event: makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'refitAsset', locationId: asset.locationId, outcome: 'failure', narrative: `Not enough FacCreds to refit into ${newCatalog.name}.` }) };
  f.facCreds -= diff;
  asset.catalogId = newCatalogId;
  asset.hp = newCatalog.hp;
  asset.status = 'assembling';
  const event = makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'refitAsset', locationId: asset.locationId, outcome: 'success', narrative: `${f.name} refits ${oldCatalog.name} into ${newCatalog.name}.` });
  return { campaign: next, event };
}

/** Plant a Base of Influence at a location where the faction already has
 *  some other asset. Contested by a Cunning check against every non-
 *  allied faction with assets there; one that beats the roll gets a flat
 *  1d6 hit on the new Base (a simplified stand-in for a chosen targeted
 *  attack — see the module doc comment). */
function expandInfluence(campaign, { factionId, locationId, hp, rng = Math.random, turnNumber } = {}) {
  const next = clone(campaign);
  const f = getFaction(next, factionId);
  const maxHp = f ? computeMaxHp(f) : 0;
  const budget = Math.max(1, Math.min(hp | 0 || 1, maxHp));
  if (!f || f.type !== 'faction' || (f.basesOfInfluence || []).some((b) => b.locationId === locationId) || (f.facCreds || 0) < budget) {
    return { campaign: next, event: makeEvent(next, { turnNumber, factionId, factionName: f && f.name, action: 'expandInfluence', locationId, outcome: 'failure', narrative: 'Could not expand influence there — already present, or insufficient FacCreds.' }) };
  }
  f.facCreds -= budget;
  const baseId = 'boi_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  const base = { id: baseId, locationId, hp: budget, maxHp: budget };
  f.basesOfInfluence.push(base);
  const rolls = [];
  const own = rollD10(rng) + (f.cunning || 0);
  for (const entry of factionsAtLocation(next, factionId, locationId)) {
    if (entry.stance === 'ally') continue;
    const rival = entry.faction;
    const rivalRoll = rollD10(rng) + (rival.cunning || 0);
    rolls.push(`${rival.name || 'rival'} ${rivalRoll} vs ${f.name} ${own}`);
    if (rivalRoll >= own) {
      const dmg = rollDiceExpr('1d6', rng).total;
      base.hp = Math.max(0, base.hp - dmg);
      f.hp = Math.max(0, (f.hp || 0) - dmg);
    }
  }
  if (base.hp <= 0) f.basesOfInfluence = f.basesOfInfluence.filter((b) => b.id !== baseId);
  const event = makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'expandInfluence', locationId, targets: [{ locationId }], rollsSummary: rolls.join('; '), outcome: base.hp > 0 ? 'success' : 'partial', narrative: `${f.name} expands influence to a new world${base.hp > 0 ? '' : ', but the new Base was thrown down before it could take hold'}.` });
  event.responses = generateFactionResponses(next, event, rng);
  let result = { campaign: next, event };
  result.campaign = advanceGoalProgress(result.campaign, factionId, { expandInfluence: true });
  return result;
}

/** Removes one Base of Influence outright — a GM correction tool (e.g. a
 *  mis-clicked Expand Influence, or a base that's fictionally gone but
 *  wasn't mechanically destroyed), NOT a mechanical action: no FacCred
 *  refund, no dice, no event logged, same "flag/fix, don't simulate"
 *  posture as the other plain entity-field edits in this app. Leaves
 *  `homeworldId` untouched even if it happens to equal `locationId` —
 *  Homeworld is its own separate field, not derived from this array, so
 *  removing a base a faction also calls home doesn't need a second
 *  decision made for it here. No-op on a non-faction entity or an id not
 *  actually in the faction's list. */
function removeFactionBase(campaign, factionId, locationId) {
  const next = clone(campaign);
  const f = getFaction(next, factionId);
  if (!f || !Array.isArray(f.basesOfInfluence)) return next;
  f.basesOfInfluence = f.basesOfInfluence.filter((b) => b.locationId !== locationId);
  return next;
}

/** Move to a different homeworld — requires an existing Base of Influence
 *  there. Always a flat one-turn transit (busyUntilTurn), and swaps Base
 *  HP per SWN: the new homeworld's Base is set to the faction's max HP,
 *  the old homeworld's Base takes on whatever HP the new one had. */
function changeHomeworld(campaign, { factionId, newLocationId, turnNumber } = {}) {
  const next = clone(campaign);
  const f = getFaction(next, factionId);
  const newBase = f && (f.basesOfInfluence || []).find((b) => b.locationId === newLocationId);
  if (!f || f.type !== 'faction' || !newBase) {
    return { campaign: next, event: makeEvent(next, { turnNumber, factionId, factionName: f && f.name, action: 'changeHomeworld', locationId: newLocationId, outcome: 'failure', narrative: 'No Base of Influence at the destination yet — Expand Influence there first.' }) };
  }
  const oldLocationId = f.homeworldId;
  const maxHp = computeMaxHp(f);
  const oldBaseHp = newBase.hp;
  newBase.hp = maxHp;
  if (oldLocationId) {
    let oldBase = f.basesOfInfluence.find((b) => b.locationId === oldLocationId);
    if (!oldBase) { oldBase = { id: 'boi_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6), locationId: oldLocationId, hp: 0, maxHp }; f.basesOfInfluence.push(oldBase); }
    oldBase.hp = oldBaseHp;
  }
  f.homeworldId = newLocationId;
  f.busyUntilTurn = (turnNumber || 0) + 1;
  const event = makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'changeHomeworld', locationId: newLocationId, targets: [{ locationId: newLocationId }], outcome: 'success', narrative: `${f.name} relocates its homeworld — in transit until its next turn.` });
  return { campaign: next, event };
}

/** Single-turn approximation of Seize Planet: tallies total unstealthed,
 *  non-allied HP at the location and reduces it by the attacker's active
 *  assets' expected damage (each asset that beats a flat defense roll of
 *  10 contributes its own attack dice). Continues via `seizeProgress`
 *  next turn if the pool isn't exhausted; on success, adds the location
 *  to `governedLocationIds` (Planetary Government, held per-world). An
 *  allied faction's assets at the target world are never counted as
 *  resistance. */
function seizePlanet(campaign, { factionId, locationId, rng = Math.random, turnNumber } = {}) {
  let next = clone(campaign);
  const f = getFaction(next, factionId);
  if (!f || f.type !== 'faction') return { campaign: next, event: makeEvent(next, { turnNumber, factionId, action: 'seizePlanet', outcome: 'failure', narrative: 'No such faction.' }) };
  const opposition = attackableTargetsAt(next, factionId, locationId);
  let remaining = f.seizeProgress && f.seizeProgress.locationId === locationId
    ? f.seizeProgress.remainingHp
    : opposition.reduce((sum, r) => sum + r.asset.hp, 0);
  if (remaining <= 0) {
    f.governedLocationIds = Array.from(new Set([...(f.governedLocationIds || []), locationId]));
    f.seizeProgress = null;
    // Conquest also flips the location's own faction membership (Living
    // Faction Engine: "the outpost location becomes a member of that
    // faction"), replacing any prior owner's member_of edge outright —
    // not just appending to the faction-side governedLocationIds array,
    // which is display-only and has no reciprocal linkage on its own.
    next = setEntityFactionMembership(next, locationId, factionId);
    const locName = (getEntity(next, locationId) || {}).name || 'The location';
    const event = makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'seizePlanet', locationId, targets: [{ locationId }], outcome: 'success', narrative: `${f.name} completes its seizure — no organized resistance remained. ${locName} is now under ${f.name}'s control.` });
    event.responses = generateFactionResponses(next, event, rng);
    let result = advanceGoalProgress(next, factionId, { seizePlanet: true });
    return { campaign: result, event };
  }
  const provider = factionProviderFor(next, f);
  const attackerAssets = (f.factionAssets || []).filter((a) => a.locationId === locationId && a.status === 'active');
  let dealt = 0; const rolls = [];
  for (const a of attackerAssets) {
    const catalog = catalogFor(provider, a);
    if (!catalog || !catalog.attack) continue;
    const roll = rollD10(rng) + (f[a.statType] || 0);
    if (roll >= 10) { const dmg = rollDiceExpr(catalog.attack.dice, rng).total; dealt += dmg; rolls.push(`${catalog.name} ${roll} → ${dmg} dmg`); }
    else rolls.push(`${catalog.name} ${roll} → no effect`);
  }
  remaining = Math.max(0, remaining - dealt);
  const done = remaining <= 0;
  let locName = null;
  if (done) {
    f.governedLocationIds = Array.from(new Set([...(f.governedLocationIds || []), locationId]));
    f.seizeProgress = null;
    next = setEntityFactionMembership(next, locationId, factionId);
    locName = (getEntity(next, locationId) || {}).name || 'the location';
  } else {
    f.seizeProgress = { locationId, remainingHp: remaining };
  }
  const event = makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'seizePlanet', locationId, targets: [{ locationId }], rollsSummary: rolls.join('; '), outcome: done ? 'success' : 'partial', narrative: `${f.name} presses its seizure of the planet — ${dealt} damage dealt, ${remaining} HP of resistance remain.${done ? ` ${locName} is now under ${f.name}'s control.` : ''}` });
  event.responses = generateFactionResponses(next, event, rng);
  let result = { campaign: next, event };
  if (done) result.campaign = advanceGoalProgress(result.campaign, factionId, { seizePlanet: true });
  return result;
}

/** Resolve one Attack between two factions' assets at a shared location.
 *  Attacker rolls 1d10 + its own asset's stat rating; defender rolls
 *  1d10 + the rating the attack's Attack line names. Damage on a win
 *  applies the attacker's Attack dice to the defending asset (redirected
 *  to a Base of Influence there if the hit would otherwise destroy the
 *  asset and a Base exists — SWN's own optional redirect, applied
 *  automatically rather than asked of the GM mid-resolution); a loss
 *  applies the defender's Counter dice back to the attacker, if it has
 *  one; a tie applies both. Callers (autoArgs/pickAttackTarget) already
 *  exclude allied co-located factions — this function itself doesn't
 *  re-check stance, so a GM-driven direct Attack (the inspector's own
 *  button, wired to this same function) can still deliberately strike an
 *  ally if they choose to. */
function attack(campaign, { attackerId, attackerFactionAssetId, defenderId, defenderFactionAssetId, rng = Math.random, turnNumber } = {}) {
  const next = clone(campaign);
  const attackerFaction = getFaction(next, attackerId);
  const defenderFaction = getFaction(next, defenderId);
  const attackerAsset = attackerFaction && activeAsset(attackerFaction, attackerFactionAssetId);
  const defenderAsset = defenderFaction && activeAsset(defenderFaction, defenderFactionAssetId);
  // Each side resolves its OWN provider independently — a mixed-provider
  // campaign (docs/adr/0032) can have an SWN faction attack a GMAtlas Core
  // one (or vice versa); each faction's catalogId only ever means anything
  // in its own faction's chosen catalog.
  const attackerCatalog = catalogFor(factionProviderFor(next, attackerFaction), attackerAsset);
  const defenderCatalog = catalogFor(factionProviderFor(next, defenderFaction), defenderAsset);
  if (!attackerFaction || !defenderFaction || !attackerAsset || !defenderAsset || !attackerCatalog || !attackerCatalog.attack) {
    return { campaign: next, event: makeEvent(next, { turnNumber, factionId: attackerId, factionName: attackerFaction && attackerFaction.name, action: 'attack', outcome: 'failure', narrative: 'Invalid attacker/defender/asset pairing.' }) };
  }
  const attackRoll = rollD10(rng) + (attackerFaction[attackerAsset.statType] || 0);
  const defenderStat = attackerCatalog.attack.vs;
  const defenseRoll = rollD10(rng) + (defenderFaction[defenderStat] || 0);
  const targets = [{ factionId: defenderId, factionName: defenderFaction.name, assetId: defenderFactionAssetId, locationId: defenderAsset.locationId }];
  let outcome; let narrative; let destroyedAssetId = null; let damage = 0;

  if (attackRoll > defenseRoll || attackRoll === defenseRoll) {
    const dmg = rollDiceExpr(attackerCatalog.attack.dice, rng);
    damage = dmg.total;
    const base = (defenderFaction.basesOfInfluence || []).find((b) => b.locationId === defenderAsset.locationId);
    if (base && damage >= defenderAsset.hp) {
      base.hp = Math.max(0, base.hp - damage);
      defenderFaction.hp = Math.max(0, (defenderFaction.hp || 0) - damage);
      if (base.hp <= 0) defenderFaction.basesOfInfluence = defenderFaction.basesOfInfluence.filter((b) => b.id !== base.id);
      narrative = `${attackerFaction.name}'s ${attackerCatalog.name} strikes through to ${defenderFaction.name}'s Base of Influence for ${damage} damage.`;
    } else {
      defenderAsset.hp = Math.max(0, defenderAsset.hp - damage);
      if (defenderAsset.hp <= 0) { destroyedAssetId = defenderAsset.id; defenderFaction.factionAssets = defenderFaction.factionAssets.filter((a) => a.id !== destroyedAssetId); }
      narrative = `${attackerFaction.name}'s ${attackerCatalog.name} hits ${defenderFaction.name}'s ${defenderCatalog ? defenderCatalog.name : 'asset'} for ${damage} damage${destroyedAssetId ? ' — destroyed!' : '.'}`;
    }
    outcome = 'success';
  }
  if (attackRoll < defenseRoll || attackRoll === defenseRoll) {
    if (defenderCatalog && defenderCatalog.counter) {
      const cdmg = rollDiceExpr(defenderCatalog.counter.dice, rng);
      attackerAsset.hp = Math.max(0, attackerAsset.hp - cdmg.total);
      if (attackerAsset.hp <= 0) attackerFaction.factionAssets = attackerFaction.factionAssets.filter((a) => a.id !== attackerFactionAssetId);
      narrative = (narrative ? narrative + ' ' : '') + `${defenderFaction.name}'s ${defenderCatalog.name} counterattacks for ${cdmg.total} damage${attackerAsset.hp <= 0 ? ' — destroyed!' : '.'}`;
    } else if (attackRoll < defenseRoll) {
      narrative = `${attackerFaction.name}'s attack fails to penetrate.`;
    }
    if (attackRoll < defenseRoll) outcome = 'failure';
  }

  const event = makeEvent(next, { turnNumber, factionId: attackerId, factionName: attackerFaction.name, action: 'attack', locationId: attackerAsset.locationId, targets, rollsSummary: `Attack ${attackRoll} vs Defense ${defenseRoll}`, outcome, narrative });
  let resultCampaign = next;
  if (destroyedAssetId) resultCampaign = advanceGoalProgress(resultCampaign, attackerId, { statTypeDestroyed: defenderAsset.statType, count: 1 });
  if (damage) resultCampaign = advanceGoalProgress(resultCampaign, attackerId, { hpDamageDealt: damage });
  return { campaign: resultCampaign, event };
}

/** Resolve one asset's special ability. The small set of purely numeric,
 *  self-contained abilities (data/swnFactionData.js's
 *  SWN_AUTOMATIC_ASSET_ABILITIES) are rolled and applied here; every
 *  other asset just surfaces its ability text — `needsGmAdjudication:
 *  true` on the returned event tells the review UI to collect a free-text
 *  outcome from the GM before this draft is committed. */
function useAssetAbility(campaign, { factionId, factionAssetId, rng = Math.random, turnNumber } = {}) {
  const next = clone(campaign);
  const f = getFaction(next, factionId);
  const provider = factionProviderFor(next, f);
  const asset = f && activeAsset(f, factionAssetId);
  const catalog = catalogFor(provider, asset);
  if (!f || f.type !== 'faction' || !asset || !catalog) {
    return { campaign: next, event: makeEvent(next, { turnNumber, factionId, factionName: f && f.name, action: 'useAssetAbility', outcome: 'failure', narrative: 'No such asset.' }) };
  }
  const auto = provider.autoAbilities[asset.catalogId];
  if (auto) {
    const roll = Math.floor(rng() * Number(auto.roll.match(/\d+$/)[0])) + 1;
    const result = auto.effect(roll);
    if (result.destroyed) { f.factionAssets = f.factionAssets.filter((a) => a.id !== factionAssetId); }
    else if (typeof result.facCreds === 'number') f.facCreds = Math.max(0, (f.facCreds || 0) + result.facCreds);
    const event = makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'useAssetAbility', locationId: asset.locationId, rollsSummary: `${auto.roll} → ${roll}`, outcome: result.destroyed ? 'partial' : 'success', narrative: `${f.name} uses ${catalog.name}'s ability: ${result.destroyed ? 'the asset is lost.' : `${result.facCreds >= 0 ? 'gains' : 'loses'} ${Math.abs(result.facCreds || 0)} FacCred(s).`}` });
    return { campaign: next, event };
  }
  const event = makeEvent(next, { turnNumber, factionId, factionName: f.name, action: 'useAssetAbility', locationId: asset.locationId, outcome: 'info', narrative: `${catalog.name}: ${catalog.special || 'No further mechanical text.'}` });
  event.needsGmAdjudication = true;
  return { campaign: next, event };
}

/** Manually flip an asset's Stealthed flag — a directly editable status
 *  (docs/adr/0032's "everything should be editable" ask), not a turn
 *  action: SWN normally sets Stealth via specific assets/tags (Secretive,
 *  Psychic Assassins, Stealth) rather than a GM toggle, so this is a plain
 *  flag flip with no dice/cost/event — same "no event" posture as
 *  toggleStatblockFieldTrack elsewhere in this app for a similar reason. */
function toggleAssetStealth(campaign, { factionId, factionAssetId } = {}) {
  const next = clone(campaign);
  const f = getFaction(next, factionId);
  const asset = f && activeAsset(f, factionAssetId);
  if (asset) asset.stealthed = !asset.stealthed;
  return { campaign: next };
}

// --- propose / commit -------------------------------------------------

const ACTIONS = { attack, buyAsset, sellAsset, repairAssetOrFaction, refitAsset, expandInfluence, changeHomeworld, seizePlanet, useAssetAbility };

/** Which actions are currently plausible for this faction, given its own
 *  state — feeds the propose heuristic below. Not exhaustive precondition
 *  checking (the action functions themselves still validate/no-op) — just
 *  enough to avoid proposing something obviously impossible. */
function candidateActions(campaign, f) {
  const provider = factionProviderFor(campaign, f);
  const out = [];
  const activeAssets = (f.factionAssets || []).filter((a) => a.status === 'active');
  const damagedAssets = activeAssets.filter((a) => { const c = catalogFor(provider, a); return c && a.hp < c.hp; });
  const cheapestAffordable = ['force', 'cunning', 'wealth'].some((s) => (provider.assets[s] || []).some((a) => a.rating <= (f[s] || 0) && a.cost <= (f.facCreds || 0)));
  if (f.homeworldId && cheapestAffordable) out.push('buyAsset');
  if (activeAssets.length) out.push('sellAsset');
  // Both repair paths (a damaged asset, or the faction's own self-heal)
  // cost at least 1 FacCred (repairAssetOrFaction's own increments=1
  // formula) — this must gate on affordability exactly like buyAsset/
  // expandInfluence already do above, or a 0-FacCred faction whose max HP
  // has risen above its current HP (a stat raised after creation — the
  // "never raises hp automatically, that's Repair's job" design in
  // entities.js's setFactionStat) gets stuck proposing a guaranteed-fail
  // Repair as its ONLY candidate, forever, since nothing else in this list
  // requires anything the faction lacks either — a real reported bug
  // ("Step always proposes Repair, which always fails").
  if ((f.facCreds || 0) >= 1 && (damagedAssets.length || (f.hp || 0) < computeMaxHp(f))) out.push('repairAssetOrFaction');
  if (activeAssets.length) out.push('refitAsset');
  if (f.homeworldId && (f.facCreds || 0) >= 1) out.push('expandInfluence');
  if ((f.basesOfInfluence || []).length) out.push('changeHomeworld');
  const attackable = activeAssets.some((a) => attackableTargetsAt(campaign, f.id, a.locationId).length > 0);
  if (attackable) out.push('attack');
  if (activeAssets.some((a) => { const c = catalogFor(provider, a); return c && c.hasAction; })) out.push('useAssetAbility');
  const seizeTargetable = activeAssets.some((a) => attackableTargetsAt(campaign, f.id, a.locationId).length > 0);
  if (seizeTargetable) out.push('seizePlanet');
  return out.length ? out : ['useAssetAbility'];
}

/** A specific, GM-legible reason a faction's turn produced no viable
 *  action — "no Homeworld set" vs "not enough FacCreds" vs "nothing to
 *  attack," instead of one generic message for every case (direct
 *  request, following the real "stuck for 13 rounds" report this was
 *  diagnosed from). `attemptedAction` is whichever action type
 *  `pickActionHeuristic` actually chose before its `autoArgs` came back
 *  null — with ANY active asset, sellAsset is always a viable fallback
 *  (its own autoArgs never fails), so "no viable action" can only occur
 *  once assets exist if the heuristic specifically landed on a
 *  DIFFERENT, narrower action instead; the message is keyed to that
 *  actual attempt rather than re-guessing independently, so it's always
 *  accurate to what was actually tried. With zero assets, `homeworldId`/
 *  affordability alone fully determine the reason (buyAsset/
 *  expandInfluence's own autoArgs never fails once their candidateActions
 *  gate passes), so `attemptedAction` isn't needed for those two cases. */
function explainNoViableAction(campaign, f, attemptedAction) {
  const activeAssets = (f.factionAssets || []).filter((a) => a.status === 'active');
  if (!activeAssets.length) {
    if (!f.homeworldId) return "no Homeworld set — it can't buy its first asset or Expand Influence anywhere until one is chosen (Entity Editor → Faction Turn card)";
    return `not enough FacCreds to buy its first asset (has ${f.facCreds || 0})`;
  }
  switch (attemptedAction) {
    case 'attack':
    case 'seizePlanet':
      return 'nothing to attack or seize here — no rival or neutral faction has an asset at the same location';
    case 'useAssetAbility':
      return 'none of its assets have a usable ability';
    case 'refitAsset':
      return 'no alternative asset at its current rating to refit into';
    case 'expandInfluence':
      return 'no known location (Homeworld or a Base of Influence) to expand influence into';
    case 'changeHomeworld':
      return 'no other Base of Influence to relocate to';
    default:
      return 'nothing productive available this turn';
  }
}

/** Weighted pick among plausible actions — favors whatever the faction's
 *  current goal counts toward, then falls back to a flat random choice.
 *  This is a heuristic "AI," not a claim of optimal play — the whole
 *  point of propose-then-confirm is that the GM can reject/regenerate a
 *  batch that doesn't read right. */
function pickActionHeuristic(campaign, f, goalId, rng) {
  const candidates = candidateActions(campaign, f);
  const goal = factionProviderFor(campaign, f).findGoal(goalId);
  const weights = candidates.map((a) => {
    let w = 1;
    if (goal) {
      const c = goal.countable || {};
      if (a === 'attack' && (c.statTypeDestroyed || c.hpDamageDealt)) w += 3;
      if (a === 'expandInfluence' && c.expandInfluence) w += 3;
      if (a === 'seizePlanet' && c.seizePlanet) w += 3;
      if (a === 'repairAssetOrFaction' && !c.statTypeDestroyed) w += 0; // no bonus, still valid
    }
    return [a, w];
  });
  const total = weights.reduce((s, [, w]) => s + w, 0);
  let roll = rng() * total;
  for (const [a, w] of weights) { if ((roll -= w) <= 0) return a; }
  return weights[0][0];
}

/** Fills in reasonable target/argument choices for a chosen action type —
 *  the "auto-pilot" half of propose-then-confirm. Picks the cheapest
 *  affordable asset to buy, the most damaged asset to repair, a rival
 *  (never an ally) co-located asset to attack, etc. Returns args ready to
 *  pass straight to the matching action function. */
function autoArgs(campaign, f, actionType, rng) {
  const provider = factionProviderFor(campaign, f);
  const activeAssets = (f.factionAssets || []).filter((a) => a.status === 'active');
  switch (actionType) {
    case 'buyAsset': {
      for (const statType of ['force', 'cunning', 'wealth'].sort(() => rng() - 0.5)) {
        const options = (provider.assets[statType] || []).filter((a) => a.rating <= (f[statType] || 0) && a.cost <= (f.facCreds || 0));
        if (options.length) { const pick = options[Math.floor(rng() * options.length)]; return { statType, catalogId: pick.id, locationId: f.homeworldId }; }
      }
      return null;
    }
    case 'sellAsset': { const a = activeAssets[Math.floor(rng() * activeAssets.length)]; return a ? { factionAssetId: a.id } : null; }
    case 'repairAssetOrFaction': {
      const damaged = activeAssets.filter((a) => { const c = catalogFor(provider, a); return c && a.hp < c.hp; });
      if (damaged.length) return { factionAssetId: damaged[0].id, increments: 1 };
      return { factionAssetId: null };
    }
    case 'refitAsset': {
      const a = activeAssets[Math.floor(rng() * activeAssets.length)];
      if (!a) return null;
      const options = (provider.assets[a.statType] || []).filter((o) => o.id !== a.catalogId && o.rating <= (f[a.statType] || 0));
      if (!options.length) return null;
      return { factionAssetId: a.id, newCatalogId: options[Math.floor(rng() * options.length)].id };
    }
    case 'expandInfluence': {
      const known = Array.from(locationsOf(f));
      const candidate = known[Math.floor(rng() * known.length)];
      if (!candidate) return null;
      return { locationId: candidate, hp: Math.min(4, f.facCreds || 1) };
    }
    case 'changeHomeworld': {
      const options = (f.basesOfInfluence || []).filter((b) => b.locationId !== f.homeworldId);
      if (!options.length) return null;
      return { newLocationId: options[Math.floor(rng() * options.length)].locationId };
    }
    case 'attack': {
      for (const a of activeAssets) {
        const target = pickAttackTarget(campaign, f.id, a.locationId, rng);
        if (target) return { attackerFactionAssetId: a.id, defenderId: target.faction.id, defenderFactionAssetId: target.asset.id };
      }
      return null;
    }
    case 'seizePlanet': {
      for (const a of activeAssets) {
        if (attackableTargetsAt(campaign, f.id, a.locationId).length) return { locationId: a.locationId };
      }
      return null;
    }
    case 'useAssetAbility': {
      const withAbility = activeAssets.filter((a) => { const c = catalogFor(provider, a); return c && c.hasAction; });
      const a = withAbility[Math.floor(rng() * withAbility.length)];
      return a ? { factionAssetId: a.id } : null;
    }
    default: return null;
  }
}

/** Computes one faction's full turn — upkeep, goal-pick-if-none, action
 *  choice+targets+dice — against a SCRATCH clone of `campaign`, returning
 *  a draft `{factionId, factionName, turnNumber, action, event,
 *  resultCampaign}` for review. Nothing is applied to `campaign` itself.
 *  Returns null for a missing/non-faction id, or a faction still `busy`
 *  from a Change Homeworld transit (busyUntilTurn) or with an unresolved
 *  Seize Planet (which takes priority over picking a fresh action). */
function proposeFactionTurn(campaign, factionId, { rng = Math.random, turnNumber } = {}) {
  const faction = getFaction(campaign, factionId);
  if (!faction || faction.type !== 'faction') return null;
  const tn = turnNumber || (campaign.factionTurnNumber || 0) + 1;
  if (faction.busyUntilTurn && faction.busyUntilTurn > tn) {
    const event = makeEvent(campaign, { turnNumber: tn, factionId, factionName: faction.name, action: 'busy', locationId: faction.homeworldId, outcome: 'info', narrative: `${faction.name} is still in transit.` });
    event.impact = computeImpact(faction, faction);
    return { factionId, factionName: faction.name, turnNumber: tn, action: 'busy', event, resultCampaign: clone(campaign) };
  }
  let working = clone(campaign);
  working = payFactionUpkeep(working, factionId).campaign;
  working = pickGoalIfNone(working, factionId, { rng });
  const f = getFaction(working, factionId);
  const before = f;

  let result;
  if (f.seizeProgress) {
    const r = seizePlanet(working, { factionId, locationId: f.seizeProgress.locationId, rng, turnNumber: tn });
    result = { action: 'seizePlanet', event: r.event, resultCampaign: r.campaign };
  } else {
    const actionType = pickActionHeuristic(working, f, f.currentGoalId, rng);
    const args = autoArgs(working, f, actionType, rng);
    if (!args) {
      const reason = explainNoViableAction(working, f, actionType);
      const event = makeEvent(working, { turnNumber: tn, factionId, factionName: f.name, action: 'none', locationId: f.homeworldId, outcome: 'info', narrative: `${f.name} has no viable action this turn — ${reason}.` });
      result = { action: 'none', event, resultCampaign: working };
    } else {
      const fn = ACTIONS[actionType];
      const r = fn(working, { factionId, ...args, rng, turnNumber: tn });
      result = { action: actionType, event: r.event, resultCampaign: r.campaign };
    }
  }
  result.event.impact = computeImpact(before, getFaction(result.resultCampaign, factionId));
  return { factionId, factionName: f.name, turnNumber: tn, action: result.action, event: result.event, resultCampaign: result.resultCampaign };
}

/** A plain snapshot of the faction fields "impact" cares about — HP,
 *  FacCreds, and each asset's own hp/status — used only to diff
 *  before-vs-after (below), never stored on its own. */
function snapshotFactionForImpact(faction) {
  if (!faction) return { hp: 0, facCreds: 0, assets: [] };
  return {
    hp: faction.hp || 0,
    facCreds: faction.facCreds || 0,
    assets: (faction.factionAssets || []).map((a) => ({ id: a.id, catalogId: a.catalogId, hp: a.hp, status: a.status })),
  };
}

/** "The impact of this event on the faction" (direct request) — a plain
 *  before/after diff computed ONCE at propose time (when both states are
 *  naturally on hand) and stored permanently on the committed event:
 *  HP/FacCreds deltas plus which of the faction's OWN assets were
 *  added/removed/changed. Deliberately not a replayable command log or a
 *  cross-faction diff (an Attack's defender-side damage is scoped to the
 *  defending faction's own future `impact`, not duplicated here) — kept
 *  simple per direct instruction. */
function computeImpact(before, after) {
  const b = snapshotFactionForImpact(before);
  const a = snapshotFactionForImpact(after);
  const beforeIds = new Set(b.assets.map((x) => x.id));
  const afterIds = new Set(a.assets.map((x) => x.id));
  const assetsAdded = a.assets.filter((x) => !beforeIds.has(x.id)).map((x) => ({ id: x.id, catalogId: x.catalogId }));
  const assetsRemoved = b.assets.filter((x) => !afterIds.has(x.id)).map((x) => ({ id: x.id, catalogId: x.catalogId }));
  const assetsChanged = a.assets
    .filter((x) => { const prior = b.assets.find((y) => y.id === x.id); return prior && (prior.hp !== x.hp || prior.status !== x.status); })
    .map((x) => { const prior = b.assets.find((y) => y.id === x.id); return { id: x.id, catalogId: x.catalogId, hpBefore: prior.hp, hpAfter: x.hp, statusBefore: prior.status, statusAfter: x.status }; });
  return { hpDelta: a.hp - b.hp, facCredsDelta: a.facCreds - b.facCreds, assetsAdded, assetsRemoved, assetsChanged };
}

/** A committed draft's resultCampaign already has the event appended to
 *  factionEvents (see below) and every effect applied — committing is
 *  just handing that snapshot back. Kept as a named function (rather
 *  than inlining `draft.resultCampaign` at every call site) so the
 *  "propose computes, commit applies" boundary stays explicit in the UI
 *  code. */
function commitFactionTurn(draft) {
  return draft.resultCampaign;
}

// proposeFactionTurn above doesn't push to factionEvents itself (it
// doesn't know yet whether the GM will accept it) — this wraps it so the
// returned resultCampaign is commit-ready (factionEvents already
// appended), matching the "commit = hand back resultCampaign" contract
// above.
function proposeAndLog(campaign, factionId, opts) {
  const draft = proposeFactionTurn(campaign, factionId, opts);
  if (!draft) return null;
  pushEvent(draft.resultCampaign, draft.event);
  return draft;
}

/** Proposes a full round: bumps factionTurnNumber once, rolls initiative,
 *  and proposes every faction in order, CHAINING each proposal against
 *  the previous faction's resultCampaign so later factions' drafts
 *  already reflect earlier ones in the same batch. Returns the array of
 *  drafts for review — nothing is committed. Per the module doc comment,
 *  a round's drafts are an all-or-nothing batch: commit the LAST draft's
 *  resultCampaign (it already carries every prior draft's effects) via
 *  commitFactionTurn(drafts[drafts.length-1]), or discard the whole
 *  batch and call this again for a fresh one. `factionIds` optionally
 *  scopes the round to a specific subset (e.g. the UI passing
 *  `factionsPresentAt(doc, activeLocationId)` so Full Round only ever
 *  processes whoever's active at WHERE's own current location) — every
 *  faction in the campaign, same as before this option existed, when
 *  omitted. */
function advanceFactionTurnRound(campaign, { rng = Math.random, factionIds } = {}) {
  let working = startTurnRound(campaign);
  const turnNumber = working.factionTurnNumber;
  const ids = factionIds || listEntities(working, 'faction').map((f) => f.id);
  const order = initiativeOrder(ids, rng);
  const drafts = [];
  for (const factionId of order) {
    const draft = proposeAndLog(working, factionId, { rng, turnNumber });
    if (!draft) continue;
    drafts.push(draft);
    working = draft.resultCampaign;
  }
  return drafts;
}

/** Step mode: propose (and log) exactly one faction's turn, without
 *  touching the round-wide factionTurnNumber machinery — a lighter-weight
 *  "just resolve this one faction right now" action. Still bumps the
 *  counter by one on commit, so Faction Events entries stay
 *  chronologically ordered regardless of whether they came from a step or
 *  a full round. */
function proposeFactionStep(campaign, factionId, { rng = Math.random } = {}) {
  const turnNumber = (campaign.factionTurnNumber || 0) + 1;
  const draft = proposeAndLog(campaign, factionId, { rng, turnNumber });
  if (draft) draft.resultCampaign.factionTurnNumber = turnNumber;
  return draft;
}

exports.relationshipStanceBetween = relationshipStanceBetween;
exports.factionsAtLocation = factionsAtLocation;
exports.factionsInRegion = factionsInRegion;
exports.factionsPresentAt = factionsPresentAt;
exports.factionPresenceReasons = factionPresenceReasons;
exports.getCurrentWhereLocations = getCurrentWhereLocations;
exports.generateFactionResponses = generateFactionResponses;
exports.expandEventReadAloud = expandEventReadAloud;
exports.setEventReadAloud = setEventReadAloud;
exports.getFactionGoalTrack = getFactionGoalTrack;
exports.ensureFactionGoalTrack = ensureFactionGoalTrack;
exports.advanceGoalProgress = advanceGoalProgress;
exports.factionsWithGoalNearCompletion = factionsWithGoalNearCompletion;
exports.getFactionDossier = getFactionDossier;
exports.isFactionRoundDue = isFactionRoundDue;
exports.resetFactionPacing = resetFactionPacing;
exports.factionEventsByRound = factionEventsByRound;
exports.getConflictEscalationTrack = getConflictEscalationTrack;
exports.ensureConflictEscalationTrack = ensureConflictEscalationTrack;
exports.suggestedConflictEscalations = suggestedConflictEscalations;
exports.startTurnRound = startTurnRound;
exports.payFactionUpkeep = payFactionUpkeep;
exports.pickGoalIfNone = pickGoalIfNone;
exports.buyAsset = buyAsset;
exports.sellAsset = sellAsset;
exports.repairAssetOrFaction = repairAssetOrFaction;
exports.refitAsset = refitAsset;
exports.expandInfluence = expandInfluence;
exports.removeFactionBase = removeFactionBase;
exports.changeHomeworld = changeHomeworld;
exports.seizePlanet = seizePlanet;
exports.attack = attack;
exports.useAssetAbility = useAssetAbility;
exports.toggleAssetStealth = toggleAssetStealth;
exports.explainNoViableAction = explainNoViableAction;
exports.proposeFactionTurn = proposeFactionTurn;
exports.commitFactionTurn = commitFactionTurn;
exports.advanceFactionTurnRound = advanceFactionTurnRound;
exports.proposeFactionStep = proposeFactionStep;

});

register("src/domain/factionConflicts.js", function(exports, require){
// factionConflicts.js — Faction Conflict (Living Faction Engine,
// docs/design/faction-conflict-integration-plan.md): the one-click
// "quick-start" generator for a conflict's hero-path fields. Everything
// that mutates an actual conflict entity's fields lives in
// domain/entities.js (ensureConflictFields and its sibling mutators),
// matching where every other entity-field mutator already lives; this
// module is just the pure content generator, mirroring domain/
// missions.js's generateMission() shape — a plain object out, no draft/
// review step, since there's no dice outcome to resolve, only flavor
// text a GM edits or accepts as-is.

const {pick, tablesWithOverrides} = require("src/domain/oracles.js");

/** Rolls a conflict's hero-path starting content from the "Faction
 *  Conflict" oracle table group (data/tables.js) — a stated/root-cause
 *  gap, a third-party casualty idea, and one starter session hook.
 *  Pure/RNG-injectable like every other generator in this app. Returns
 *  plain strings ready to hand to entities.js's updateEntity/
 *  addConflictSessionHook — this function never touches the campaign
 *  itself. */
function generateConflictSeed(campaign, { rng = Math.random, genrePack } = {}) {
  const tables = tablesWithOverrides(campaign.oracles && campaign.oracles.overrides, genrePack || (campaign.settings && campaign.settings.genrePack));
  const group = (tables && tables['Faction Encounter']) || {};
  const rootCauseTable = group['Root Cause Category'] || [];
  const gapTable = group['Cause Gap Flavor'] || [];
  const casualtyTable = group['Third-Party Casualty'] || [];
  const hookTable = group['Starter Session Hook'] || [];
  const rootCause = rootCauseTable.length ? pick(rootCauseTable, rng) : '';
  const gap = gapTable.length ? pick(gapTable, rng) : '';
  return {
    statedCause: rootCause ? `On the surface, this is about ${rootCause}.` : '',
    rootCause: gap ? `But ${gap}.` : '',
    causeGapHook: 'If the party surfaces the gap between the two, both sides’ public stories stop holding up.',
    thirdPartyCasualty: casualtyTable.length ? pick(casualtyTable, rng) : '',
    sessionHook: hookTable.length ? pick(hookTable, rng) : '',
  };
}

exports.generateConflictSeed = generateConflictSeed;

});

register("src/domain/hostileLocations.js", function(exports, require){
// hostileLocations.js — the domain half of importing HOSTILE's own canon
// gazetteer (docs/adr/0026-hostile-canon-locations.md) into a live
// campaign as real, fully-editable Location entities. Pure and DOM-free,
// same "clone once, return new campaign" shape as every other domain
// mutator. Mirrors entities.js's createItemFromCatalog (a catalog entry
// in, one real entity out) but as a bulk loop, matching the shape of
// other bulk actions like factions.js's advanceFactionTurns.
//
// The catalog itself is no longer bundled JS — as of the JSON-pack
// conversion (docs/adr/0026 addendum) it lives in assets/data-packs/
// hostile-*.json, one file per zone, fetched and merged at import-click
// time by ui/hostileLocationsFetch.js (fetch() isn't pure/synchronous, so
// it can't live here per rule 3) and handed to importHostileLocations
// below as a plain `{bases, zones, stars, locations}` object — this module
// stays exactly as pure/DOM-free/synchronous as before, just no longer
// importing its own data, and has no idea the pack it's handed may itself
// be a merge of several zone files.
//
// Import order matters (2026-07-08 follow-ups): Bases, then Zones, then
// Stars, then the worlds themselves — each later pass references
// entities the earlier pass already created (a world's `bases`/
// `starSystem` values are real Location NAMES, matched against
// #base/#star-tagged entities the World Profile UI's dropdowns source
// from). A star's own `starSystem` field is set to its OWN name (the
// JSON pack's own `stars` entries already encode this) — that
// self-reference is what tells the UI "this Location IS the star, not a
// world orbiting one."
//
// After all four catalogs land, linkHierarchy() builds the real
// Zone > Star > World > Base containment chain as relationships (not
// tags — the star name used to be duplicated as a tag on the world;
// that's gone now that the relationship exists as the single source of
// truth): the "downward" edge on each pair is typed/labeled Contains,
// the reverse "upward" edge is typed/labeled Located At — Zone
// -Contains-> Star -Contains-> World -Contains-> Base, with Star/World/
// Base's own edge back reading Located At. This is deliberately the
// same two relationship types across every pair (no separate "orbits"
// type) — it reuses the existing Relationships chip list and Graph
// rendering with zero new mechanism, and reads naturally in both
// directions ("Near Earth Zone Contains Wolf 359" / "Wolf 359 Located
// At Near Earth Zone").

const {createEntity, updateEntity, findByName, addRelationship, updateRelationshipType, updateRelationshipLabel} = require("src/domain/entities.js");

function importCatalog(campaign, entries, makeFields) {
  let next = campaign;
  const createdIds = [];
  for (const entry of entries) {
    if (findByName(next, entry.name)) continue;
    const { campaign: withEntity, id } = createEntity(next, { type: 'location', name: entry.name });
    next = updateEntity(withEntity, id, makeFields(entry));
    createdIds.push(id);
  }
  return { campaign: next, createdIds };
}

/** Links `parentName` --Contains--> `childName` and, symmetrically,
 *  `childName` --Located At--> `parentName`. Both entities must already
 *  exist (by exact name). Unconditional and idempotent — addRelationship
 *  no-ops if the edge already exists, and re-running updateRelationship*
 *  on an existing edge just re-asserts the same values, so this is safe
 *  to call on every import regardless of whether either side is new. */
function linkContains(campaign, parentName, childName) {
  const parent = findByName(campaign, parentName);
  const child = findByName(campaign, childName);
  if (!parent || !child || parent.id === child.id) return campaign;
  let next = addRelationship(campaign, parent.id, child.id, 'Contains', 'contains');
  next = updateRelationshipType(next, child.id, parent.id, 'located_at');
  next = updateRelationshipLabel(next, child.id, parent.id, 'Located At');
  return next;
}

/** Creates one Location entity per entry in `pack` (the fetched JSON —
 *  see ui/hostileLocationsFetch.js — shaped `{bases, zones, stars,
 *  locations}`) not already present in the campaign, deduped by exact
 *  name match via findByName — safely re-runnable as later zones are
 *  appended to the pack; already-imported worlds/stars/zones/bases are
 *  skipped, not duplicated or overwritten, so a GM's own edits are never
 *  clobbered by a later import. Imports pack.bases, pack.zones,
 *  pack.stars, then pack.locations, in that order, then links the whole
 *  Zone > Star > World > Base containment chain as relationships.
 *  Returns {campaign, createdIds} (combined across all four catalogs —
 *  the relationship-linking pass creates no new entities, only edges).
 *  A missing/malformed section (not an array) is treated as empty rather
 *  than throwing, so a partial or hand-edited pack degrades gracefully. */
function importHostileLocations(campaign, pack) {
  let next = campaign;
  let createdIds = [];
  const p = pack && typeof pack === 'object' ? pack : {};
  const packBases = Array.isArray(p.bases) ? p.bases : [];
  const packZones = Array.isArray(p.zones) ? p.zones : [];
  const packStars = Array.isArray(p.stars) ? p.stars : [];
  const packLocations = Array.isArray(p.locations) ? p.locations : [];

  const bases = importCatalog(next, packBases, (entry) => ({
    tags: ['hostile-canon', 'base'],
    overview: entry.summary,
  }));
  next = bases.campaign;
  createdIds = createdIds.concat(bases.createdIds);

  const zones = importCatalog(next, packZones, (entry) => ({
    tags: ['hostile-canon', 'zone'],
    overview: entry.summary,
  }));
  next = zones.campaign;
  createdIds = createdIds.concat(zones.createdIds);

  const stars = importCatalog(next, packStars, (entry) => ({
    tags: ['hostile-canon', 'star'],
    overview: entry.summary,
    hex: entry.hex,
    zone: entry.zone,
    starSystem: entry.starSystem,
  }));
  next = stars.campaign;
  createdIds = createdIds.concat(stars.createdIds);

  const worlds = importCatalog(next, packLocations, (entry) => ({
    tags: ['hostile-canon', entry.zone, entry.locationKind],
    overview: entry.summary,
    hex: entry.hex,
    zone: entry.zone,
    starport: entry.starport,
    worldSize: entry.worldSize,
    atmosphere: entry.atmosphere,
    hydrographics: entry.hydrographics,
    population: entry.population,
    government: entry.government,
    lawLevel: entry.lawLevel,
    techLevel: entry.techLevel,
    bases: [...entry.bases],
    tradeCodes: [...entry.tradeCodes],
    gasGiant: entry.gasGiant,
    starSystem: entry.starSystem,
  }));
  next = worlds.campaign;
  createdIds = createdIds.concat(worlds.createdIds);

  for (const star of packStars) next = linkContains(next, star.zone, star.name);
  for (const world of packLocations) {
    next = linkContains(next, world.starSystem, world.name);
    for (const baseName of world.bases) next = linkContains(next, world.name, baseName);
  }

  return { campaign: next, createdIds };
}

exports.importHostileLocations = importHostileLocations;

});

register("src/ui/hostileLocationsFetch.js", function(exports, require){
// hostileLocationsFetch.js — the async, browser-only half of importing
// HOSTILE's own canon Locations gazetteer (docs/adr/0026, JSON-pack
// addendum): fetches assets/data-packs/hostile-near-earth-zone.json and
// hands the plain data to domain/hostileLocations.js's pure
// importHostileLocations(campaign, pack). Deliberately NOT in src/domain/
// — fetch() is neither pure nor synchronous, the same reason
// ui/mechanicsScan.js/ui/tocScan.js live here instead of domain/.
//
// file:// is a hard no for this feature, the same restriction
// ui/mechanicsScan.js already documented and worked around by just
// surfacing a clear error rather than attempting a workaround: Chromium
// treats a file:// page's fetch to another file:// resource as
// cross-origin and blocks it outright. Every other feature in this app
// still works over file://; only this one (and the PDF-scanning features)
// requires `npm run serve` (http://).
// Each zone is its own JSON file (one per pass of the ADR 0026 rollout
// checklist) rather than one ever-growing file — keeps each zone's data
// independently reviewable/citable and avoids merge conflicts in a single
// huge JSON as later zones are appended. Add a new zone's file path here
// when it lands; importHostileLocations()'s dedup-by-name and
// linkContains relationship logic need no changes since it just sees one
// bigger merged pack.
const PACK_URLS = [
  './assets/data-packs/hostile-near-earth-zone.json',
  './assets/data-packs/hostile-fomalhaut-settlement-zone.json',
];

// `urls` narrows the import to particular zone files — Settings ->
// Campaigns -> Source Data imports each zone on its own.
async function fetchHostileLocationsPack(urls = PACK_URLS) {
  if (typeof location !== 'undefined' && location.protocol === 'file:') {
    throw new Error('HOSTILE Canon Locations needs the app served over http(s) — run `npm run serve` and try again (file:// blocks reading a local JSON file for security reasons)');
  }
  const merged = { zones: [], bases: [], stars: [], locations: [] };
  for (const url of urls) {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`Could not load the HOSTILE Locations data pack at ${url} (HTTP ${res.status})`);
    const pack = await res.json();
    for (const key of Object.keys(merged)) {
      if (Array.isArray(pack[key])) merged[key] = merged[key].concat(pack[key]);
    }
  }
  return merged;
}

exports.fetchHostileLocationsPack = fetchHostileLocationsPack;

});

register("src/domain/contentPack.js", function(exports, require){
// contentPack.js — a GM's own ad-hoc content transfer between campaigns:
// export/import just Entities, Guide docs, or Journal entries as a portable
// JSON file, so a custom set (a homebrew Bestiary, a written Guide section,
// a batch of session logs) can be carried into another campaign. Distinct
// from core/store.js's export()/import() (whole-campaign, REPLACING) and
// from domain/hostileLocations.js's importHostileLocations() (a curated
// catalog with name-dedup, safe to re-run) — this one is always additive,
// no dedup, and generates a fresh id for every record on import: two
// independently-created campaigns' ids (Date.now()+random, no campaign
// namespace baked in) are not guaranteed unique against each other.

function clone(c) { try { return structuredClone(c); } catch { return JSON.parse(JSON.stringify(c)); } }
function freshId(prefix) { return prefix + Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }

const PACK_APP = 'GMAtlas';
const PACK_KIND = 'content-pack';

/** Serializes whole sections of a campaign into a portable, additive pack.
 *  A section key is entirely ABSENT (not an empty array) when its flag is
 *  false, so importContentPack can tell "nothing to import here" apart
 *  from "import this empty list" (the latter never happens from this
 *  export path, but importContentPack is defensive about it regardless).
 *  An entity's thumbnailId is stripped — a Gallery image reference that
 *  won't resolve in the destination campaign, since Gallery isn't part of
 *  this export. */
function exportContentPack(campaign, { entities = false, guide = false, journal = false } = {}) {
  const pack = { app: PACK_APP, kind: PACK_KIND, schemaVersion: campaign.schemaVersion };
  if (entities) {
    pack.entities = (campaign.entities?.items || []).map((e) => {
      const copy = clone(e);
      delete copy.thumbnailId;
      return copy;
    });
  }
  if (guide) pack.guide = clone(campaign.guide?.docs || []);
  if (journal) pack.journal = clone(campaign.journal || []);
  return pack;
}

/** Imports a pack additively into campaign. Entities dedup by exact name
 *  match (case-insensitive, trimmed — same convention
 *  domain/hostileLocations.js's own importer already uses for this same
 *  overlapping-catalog problem via entities.js's findByName), direct
 *  follow-up request: "allow all content packs to be uploaded into one
 *  campaign without overwrite... re-import will just skip those
 *  entities" — so importing the same pack twice, or two packs that happen
 *  to share a named entity, is safe to repeat. Guide docs/Journal entries
 *  are unaffected by this — still always-fresh-id, no dedup, matching
 *  store.import()'s "GM knows what they're doing" posture (a Journal
 *  entry has no natural dedup key that couldn't also wrongly discard a
 *  genuinely new entry that happens to read the same). Every entity/
 *  guide-doc gets a fresh id (or, for a deduped entity, resolves to the
 *  ALREADY-existing match's real id instead), remapped through an old->new
 *  map so the pack's own internal structure survives even across a
 *  skipped duplicate: an entity relationship whose target isn't also in
 *  the pack (and isn't a dedup match either) is dropped; a guide doc whose
 *  parent isn't also in the pack becomes a new root instead of pointing at
 *  nothing. Journal entries have no internal refs and are appended as-is
 *  aside from a fresh id. Silently no-ops on a missing/malformed pack (a
 *  null pack passed in) or a mismatched section shape (nothing happens for
 *  that section) rather than throwing — a bad file picked at the
 *  file-input level is the UI's job to reject with a toast before this
 *  ever runs. */
function importContentPack(campaign, pack) {
  const next = clone(campaign);
  if (!pack || typeof pack !== 'object') return next;

  if (Array.isArray(pack.entities)) {
    if (!next.entities || typeof next.entities !== 'object') next.entities = { items: [], activeId: null, history: [] };
    if (!Array.isArray(next.entities.items)) next.entities.items = [];
    const nameKey = (n) => String(n || '').trim().toLowerCase();
    const existingByName = new Map(next.entities.items.map((e) => [nameKey(e.name), e.id]));
    const idMap = new Map();
    const toCreate = [];
    for (const e of pack.entities) {
      const existingId = existingByName.get(nameKey(e.name));
      if (existingId) { idMap.set(e.id, existingId); continue; }
      idMap.set(e.id, freshId('ent_'));
      toCreate.push(e);
    }
    for (const e of toCreate) {
      const copy = clone(e);
      copy.id = idMap.get(e.id);
      copy.relationships = (Array.isArray(copy.relationships) ? copy.relationships : [])
        .filter((r) => idMap.has(r.to))
        .map((r) => ({ ...r, to: idMap.get(r.to) }));
      next.entities.items.push(copy);
    }
  }

  if (Array.isArray(pack.guide)) {
    const idMap = new Map(pack.guide.map((d) => [d.id, freshId('gd_')]));
    if (!next.guide || typeof next.guide !== 'object') next.guide = { docs: [], activeId: null };
    if (!Array.isArray(next.guide.docs)) next.guide.docs = [];
    for (const d of pack.guide) {
      const copy = clone(d);
      copy.id = idMap.get(d.id);
      copy.parentId = (d.parentId && idMap.has(d.parentId)) ? idMap.get(d.parentId) : null;
      next.guide.docs.push(copy);
    }
  }

  if (Array.isArray(pack.journal)) {
    if (!Array.isArray(next.journal)) next.journal = [];
    for (const j of pack.journal) {
      const copy = clone(j);
      copy.id = freshId('j');
      next.journal.push(copy);
    }
  }

  return next;
}

exports.exportContentPack = exportContentPack;
exports.importContentPack = importContentPack;

});

register("src/ui/contentPacksFetch.js", function(exports, require){
// contentPacksFetch.js — the async, browser-only half of importing a
// content pack from data/contentPacksManifest.js's own list (Settings'
// "Available Packs"). Deliberately NOT in src/domain/ — fetch() is
// neither pure nor synchronous, the same reason ui/hostileLocationsFetch.js
// (this file's own model) and ui/mechanicsScan.js/ui/tocScan.js live here
// instead. Unlike hostileLocationsFetch.js's own fetchHostileLocationsPack
// (several zone files merged into one bespoke `{bases,zones,...}` shape),
// a content pack is always exactly one file handed straight to
// domain/contentPack.js's importContentPack — no merge logic needed.
//
// Same file:// restriction as hostileLocationsFetch.js: Chromium treats a
// file:// page's fetch to another file:// resource as cross-origin and
// blocks it outright, so this needs `npm run serve` (http://) — every
// other feature in this app still works over plain file://.
async function fetchJsonPack(url) {
  if (typeof location !== 'undefined' && location.protocol === 'file:') {
    throw new Error('Content Packs need the app served over http(s) — run `npm run serve` and try again (file:// blocks reading a local JSON file for security reasons)');
  }
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Could not load the pack at ${url} (HTTP ${res.status})`);
  return res.json();
}

exports.fetchJsonPack = fetchJsonPack;

});

