register("src/data/fiveLeaguesSpells.js", function(exports, require){
// fiveLeaguesSpells.js — the real Spell Table (Five Leagues from the
// Borderlands 3rd Edition, pp.47-50, read directly from assets/docs/5LFB/
// five-leagues-from-the-borderlands-3e.pdf), backing the Character Sheet's
// "Known Spells" section (direct follow-up request — only shown for a
// character whose Character Type is Mystic, p.45: "A Mystic is a
// spell-casting character"). All 34 D100-table entries (01-03 through
// 99-100), each with its real Incantation score, Target, Effect text, and
// Duration — a GM ticking a spell known here sees the real rule at hand
// without flipping back to the book. `simple: true` marks the 4 spells the
// table itself flags with a trailing "*" (p.46: a Simple spell never costs
// a Strand on a success, only on a natural-2 failure). No spell in this
// table carries the separate "Taxing" marker the rules text also defines
// (once-per-battle casting) — none of the 34 entries show it.
const FIVE_LEAGUES_SPELLS = [
  { key: 'antidote', label: 'Antidote', incantation: '7+', target: '1 ally', effect: 'Target is unaffected by Poison or Venom traits.', duration: 'Battle', simple: false },
  { key: 'barrier', label: 'Barrier', incantation: '6+', target: 'Ground', effect: 'Place a line of fire 4" long and 0.5" wide without touching any characters. Prevents all movement across it except for figures with the Flying trait. It may be shot across, but provides Cover.', duration: 'Full round', simple: false },
  { key: 'bind', label: 'Bind', incantation: '8+', target: 'Up to 3 enemies within 1" of each other', effect: 'Each targeted figure rolls D6, adding any Monster Point total, breaking free on a 6+. If failing to break free, the figure cannot move, but may fight and shoot normally.', duration: 'Activation', simple: false },
  { key: 'bleed', label: 'Bleed', incantation: '8+', target: '1 enemy', effect: 'The target loses the Regeneration trait if they have it. If Wounded, roll D6 each Tracking Phase — on a 6, they die.', duration: 'Battle', simple: false },
  { key: 'compel', label: 'Compel', incantation: '7+', target: '1 enemy', effect: 'When the target next activates, they must move directly towards the Mystic as fast as possible, never risking damage from dangerous terrain.', duration: 'Activation', simple: true },
  { key: 'confuse', label: 'Confuse', incantation: '7+', target: '1 enemy', effect: 'Target loses the Parry and Counter Attack traits.', duration: 'Full round', simple: false },
  { key: 'darts', label: 'Darts', incantation: '6+', target: '1 ally', effect: 'Target a character out of ranged weapon ammunition — they immediately restock. Does not work on single-use weapons.', duration: 'Immediate', simple: false },
  { key: 'distract', label: 'Distract', incantation: '7+', target: '1 enemy Ranged Trooper', effect: 'The target will remain in place and will not shoot.', duration: 'Activation', simple: false },
  { key: 'escape', label: 'Escape', incantation: '6+', target: '1 ally', effect: 'Remove the target character from the battle. No "Flight in the Dark" roll is needed.', duration: 'Immediate', simple: false },
  { key: 'explore', label: 'Explore', incantation: '7+', target: '1 marker', effect: 'Select an Unknown Enemy Marker, Exploration Marker, Unusual Location Marker, or similar, and roll to resolve what it is. Does not require Line of Sight.', duration: 'Immediate', simple: false },
  { key: 'fog', label: 'Fog', incantation: '6+', target: 'Ground', effect: 'Place a fog cloud circle 3" across. Figures can move into, out of, and through it, but it blocks all Lines of Sight.', duration: 'Full round', simple: false },
  { key: 'foresee', label: 'Foresee', incantation: '7+', target: 'None', effect: 'If a time limit applies to Achieving the Objective, increase the limit by 1 battle round.', duration: 'Immediate', simple: false },
  { key: 'fortune', label: 'Fortune', incantation: '5+', target: 'Personal', effect: 'The Mystic may reroll a ranged roll to Hit, a melee roll to Hit, a proficiency test, or force an enemy to reroll a successful Overcome Armor roll against them.', duration: 'Full round', simple: true },
  { key: 'frighten', label: 'Frighten', incantation: '7+', target: 'None', effect: 'If the enemy took any casualties this turn, they must roll 1 additional Morale die. No Line of Sight is required.', duration: 'Next Tracking Phase', simple: false },
  { key: 'guidance', label: 'Guidance', incantation: '7+', target: '1 ally', effect: 'The Ally may reroll a single shooting roll to Hit, melee roll to Hit, proficiency test, or force an enemy to reroll a successful Overcome Armor roll — any ally may use the reroll, at any point, once cast. No Line of Sight required.', duration: 'Full round', simple: false },
  { key: 'heal', label: 'Heal', incantation: '6+', target: '1 ally', effect: 'Remove a Wound.', duration: 'Immediate', simple: false },
  { key: 'illuminate', label: 'Illuminate', incantation: '6+', target: 'Personal', effect: 'All characters, features, and items within 12" of the Mystic are visible from any distance.', duration: 'Battle', simple: true },
  { key: 'infuse', label: 'Infuse', incantation: '6+', target: '1 ally that is not Wounded', effect: 'As long as the target remains un-Wounded, they receive the Counter Attack ability.', duration: 'Until Wounded', simple: false },
  { key: 'manipulate', label: 'Manipulate', incantation: '6+', target: '1 item', effect: "An item on the ground, in the Mystic's possession, or in an ally's possession may be moved up to 8\" within Line of Sight. If moved into contact with a character, they may pick it up immediately, free.", duration: 'Immediate', simple: true },
  { key: 'mark', label: 'Mark', incantation: '7+', target: '1 enemy', effect: 'All ranged attacks on the selected target receive a +1 bonus to Hit.', duration: 'Full round', simple: false },
  { key: 'meekness', label: 'Meekness', incantation: '7+', target: '1 enemy', effect: 'Enemy melee attacks do +0/+0 damage.', duration: 'Full round', simple: false },
  { key: 'mobility', label: 'Mobility', incantation: '7+', target: '1 ally', effect: 'The character ignores all movement reductions due to Difficult terrain.', duration: 'Battle', simple: false },
  { key: 'premonition', label: 'Premonition', incantation: '7+', target: 'None', effect: 'When rolling for Initiative, 2 dice may be rerolled.', duration: 'Next Initiative Roll', simple: false },
  { key: 'repel', label: 'Repel', incantation: '7+', target: '1 enemy', effect: 'The enemy is pushed directly away D6+1" (Aberrations subtract their current Monster Points from the roll). Can be used to push a figure into danger.', duration: 'Immediate', simple: false },
  { key: 'shadows', label: 'Shadows', incantation: '6+', target: '1 ally', effect: 'Target may immediately move to any location within 4" of their current position — can move through Impassable obstacles or walls, but both positions must be visible to the Mystic.', duration: 'Immediate', simple: false },
  { key: 'shield', label: 'Shield', incantation: '6+', target: '1 ally', effect: "All ranged attacks aimed at the spell's target, or a character within 3\" of them, will Hit only on a natural 6.", duration: 'Full round', simple: false },
  { key: 'slow', label: 'Slow', incantation: '8+', target: 'Up to 3 enemies within 1" of each other', effect: 'Reduce enemy Speed by -2" and Dashing becomes impossible for them. Negates Flying and Slippery traits.', duration: 'Full round', simple: false },
  { key: 'spellbreak', label: 'Spellbreak', incantation: '7+', target: '1 enemy', effect: 'The enemy is unable to cast any spells.', duration: 'Full round', simple: false },
  { key: 'steelbreak', label: 'Steelbreak', incantation: '7+', target: '1 enemy', effect: 'Enemy counts as Armor 0.', duration: 'Full round', simple: false },
  { key: 'summon', label: 'Summon', incantation: '7+', target: 'Ground', effect: 'Summons a magical creature (Agility 2, Speed 6"/+0", Combat +0, Toughness 4, Armor 0, attacks +0/+0, no equipment) in base contact with the Mystic, able to act immediately. Only usable with fewer than 6 warband members and allies on the table.', duration: 'Battle', simple: false },
  { key: 'tinker', label: 'Tinker', incantation: '6+', target: '1 ally', effect: 'Add +2 to any proficiency test.', duration: 'Full round', simple: false },
  { key: 'torment', label: 'Torment', incantation: '8+', target: '1 enemy', effect: 'If the enemy is engaged in melee while Wounded, their opponent receives a Combat Bonus.', duration: 'Battle', simple: false },
  { key: 'waylay', label: 'Waylay', incantation: '8+', target: '1 enemy patrol (Site Battle scenario, p.142)', effect: 'The patrol does not move this round. When next activated, they will begin moving towards a random Exploration Marker.', duration: 'Full round', simple: false },
  { key: 'weaken', label: 'Weaken', incantation: '8+', target: '1 enemy', effect: 'Negates the Tough trait. Has no effect on Aware figures.', duration: 'Battle', simple: false },
];
function findFiveLeaguesSpell(key) {
  return FIVE_LEAGUES_SPELLS.find((s) => s.key === key) || null;
}

exports.FIVE_LEAGUES_SPELLS = FIVE_LEAGUES_SPELLS;
exports.findFiveLeaguesSpell = findFiveLeaguesSpell;

});

register("src/data/fiveLeaguesEnemyTraits.js", function(exports, require){
// fiveLeaguesEnemyTraits.js — Five Leagues from the Borderlands 3rd
// Edition (read directly from assets/docs/5LFB/five-leagues-from-the-
// borderlands-3e.pdf) Universal Enemy Traits (p.152-153) and Aberration
// Traits (p.184-185), backing the Bestiary 'fiveleagues-lifeform'
// template's own Traits field (direct follow-up request: "include the
// Traits or Aberrant [sic — the real term is Aberration] Traits as
// separate lines where the title is in bold just like in the rulebook...
// make it a tooltip link to show the definition of the trait"). A GM
// still just types comma-separated trait NAMES into the one free-text
// Traits field, exactly as the book's own stat blocks print them
// ("Traits: Undead, Counter Attack") — this catalog is only ever used to
// resolve each typed name back to its own real definition for the
// tooltip; an unrecognized name (a Compendium-only trait, a homebrew one,
// a typo) still renders as a plain bold line with no tooltip, never an
// error.
const FIVE_LEAGUES_ENEMY_TRAITS = [
  { key: 'awareness', label: 'Awareness', text: 'You cannot attempt to Seize the Initiative against this enemy, even if the scenario would allow the attempt.' },
  { key: 'brave', label: 'Brave', text: 'The enemy only fails Morale checks when rolling a 1, instead of the customary 1-2.' },
  { key: 'counterAttack', label: 'Counter Attack', text: 'If the enemy wins a melee exchange, they will inflict a Hit even if they were the defender.' },
  { key: 'crawling', label: 'Crawling', text: 'The enemy may Dash during Site Battles.' },
  { key: 'fearless', label: 'Fearless', text: 'The enemy does not take Morale checks.' },
  { key: 'fey', label: 'Fey', text: 'When targeted by a spell, the enemy may roll D6. The spell is canceled on a 4-6. If a spell would affect multiple figures, roll individually for each figure: the spell is canceled if any roll succeeds.' },
  { key: 'flying', label: 'Flying', text: 'The enemy ignores all terrain penalties and may move across obstacles, even if they would be otherwise Impassable. Flying figures are assumed to land or be hovering just over ground level at the end of their move, and can be engaged normally in melee. Foes do not receive a Combat Bonus from higher ground against Flying characters.' },
  { key: 'gruesome', label: 'Gruesome', text: 'A character who is removed as a casualty from battle must make a modification of -5 when rolling for post-game injuries. This does not affect rolls on the Flight in the Dark Table.' },
  { key: 'hangBack', label: 'Hang Back', text: 'An enemy with Hang Back should always be set up in or behind a terrain feature. They will not move from that feature, except to engage foes within one move. If targeted by ranged weapons, they will move to get out of sight, if possible.' },
  { key: 'monster', label: 'Monster', text: 'They cannot Dash and always move as directly as possible towards their foes.' },
  { key: 'outflank', label: 'Outflank', text: 'When deploying, the enemy may roll to Outflank, if the scenario permits it.' },
  { key: 'parry', label: 'Parry', text: 'The enemy may Parry in melee combat (p.42).' },
  { key: 'poison', label: 'Poison', text: 'A natural 6 on a ranged attack or a natural 6 as the attacker in a melee exchange will automatically remove the target as a casualty, unless the blow fails to penetrate Armor.' },
  { key: 'poorShot', label: 'Poor Shot', text: 'This enemy does not add their Combat Skill to ranged attacks.' },
  { key: 'regeneration', label: 'Regeneration', text: 'Each Tracking Phase, any enemy with a Wound will heal. Two Wounds during the same battle round will kill them, as normal.' },
  { key: 'relentless', label: 'Relentless', text: 'Warband members cannot use or gain the Parry and Counter Attack abilities in melee against this enemy.' },
  { key: 'skirmisher', label: 'Skirmisher', text: 'The enemy may make ranged attacks even if they moved a full move. Weapons that normally allow no movement (such as crossbows) will allow a half move instead.' },
  { key: 'slippery', label: 'Slippery', text: 'The enemy does not suffer movement reductions due to difficult terrain, may move through water features at normal speed, and may ignore obstacles up to 1" tall when moving.' },
  { key: 'terrifying', label: 'Terrifying', text: 'The enemy has Counter Attack when fighting Followers (but not Heroes).' },
  { key: 'tough', label: 'Tough', text: 'The enemy cannot be Stunned.' },
  { key: 'undead', label: 'Undead', text: 'The enemy cannot Dash. Undead are always Tough and Fearless as well.' },
  { key: 'unknownEnemies', label: 'Unknown Enemies', text: 'The enemy always uses the rules for Unknown Enemy markers unless the scenario would not permit it.' },
];

const FIVE_LEAGUES_ABERRATION_TRAITS = [
  { key: 'areaAttack', label: 'Area Attack', text: 'After the creature moves, if it did not enter melee, it will conduct a ranged attack against the closest warband member in range. The target is Hit on a D6 roll of 4+. Any character within 2" of the target point is struck on a D6 roll of 5+. Cover and protections against ranged attacks have no effect, and the attack can strike allies of the Aberration as well as foes.' },
  { key: 'charge', label: 'Charge', text: 'If the creature moves into melee, it receives a Combat Bonus in the first exchange.' },
  { key: 'cruelWounds', label: 'Cruel Wounds', text: 'A character knocked out by this creature must add 1 turn to any recovery time required by the Injury Table after the battle.' },
  { key: 'difficultToKill', label: 'Difficult to Kill', text: 'Each Tracking Phase, if the Aberration did not fight in melee combat, roll D6. On a 5-6, it regains 1 MP if any have been lost.' },
  { key: 'ethereal', label: 'Ethereal', text: 'The creature does not lose more than 1 MP to a strike, even if rolling above its Toughness.' },
  { key: 'fellTouch', label: 'Fell Touch', text: 'Blows from the creature always penetrate non-enchanted Armor.' },
  { key: 'knockBack', label: 'Knock Back', text: 'A character suffering a melee strike from the creature is flung D6" directly backwards. If they collide with another character, they stop in place. This ends the melee.' },
  { key: 'lash', label: 'Lash', text: 'Whenever the creature loses MP, it lashes out, pushing all melee opponents back 3", and ending the melee immediately.' },
  { key: 'magicResistant', label: 'Magic Resistant', text: 'The creature is unaffected by any spells, and enchanted weapons provide no advantage against it. Effects that specifically affect the character fighting the creature apply as normal.' },
  { key: 'rangedAttack', label: 'Ranged Attack', text: 'If the creature is not in melee by the end of a normal move, it will conduct a ranged attack just like an archer. These attacks have their own damage score and cannot run out of ammunition.' },
  { key: 'size', label: 'Size', text: 'All ranged attacks against the creature receive a +1 bonus to Hit.' },
  { key: 'terror', label: 'Terror', text: 'A Follower that loses a melee exchange to the creature will flee a full move directly away, if they survive, and can take no Actions the following battle round. If engaged in melee combat, they will fight normally.' },
  { key: 'venom', label: 'Venom', text: 'A natural 6 on a combat roll will knock the target out, bypassing Armor.' },
  { key: 'wings', label: 'Wings', text: 'The creature ignores all terrain penalties and may move across obstacles, even if they would be otherwise Impassable. When using Wings, figures are assumed to land or be hovering just over ground level at the end of their move, and can be engaged normally in melee.' },
  { key: 'undying', label: 'Undying', text: 'The creature counts as being Undead for the purpose of items and spells with special effects against Undead.' },
];

/** Resolves a GM-typed trait name (whatever casing/whitespace) back to
 *  its own real definition, searching the Universal Enemy Traits first
 *  and then the Aberration Traits — null if unrecognized (a Compendium-
 *  only trait, a homebrew one, or a typo), which the UI renders as a
 *  plain bold line with no tooltip rather than an error. */
function findFiveLeaguesEnemyTrait(name) {
  const needle = String(name || '').trim().toLowerCase();
  if (!needle) return null;
  const all = [...FIVE_LEAGUES_ENEMY_TRAITS, ...FIVE_LEAGUES_ABERRATION_TRAITS];
  return all.find((t) => t.label.toLowerCase() === needle) || null;
}

exports.FIVE_LEAGUES_ENEMY_TRAITS = FIVE_LEAGUES_ENEMY_TRAITS;
exports.FIVE_LEAGUES_ABERRATION_TRAITS = FIVE_LEAGUES_ABERRATION_TRAITS;
exports.findFiveLeaguesEnemyTrait = findFiveLeaguesEnemyTrait;

});

register("src/data/locationTypeIcons.js", function(exports, require){
// locationTypeIcons.js — Five Leagues from the Borderlands' own canonical
// Location categories (Core rulebook p.68 Step 2: Establish Settlements;
// p.92-94 Encounter Locations: Enemy Camps, Enemy Hideouts, Delves, Monster
// Lairs, Unexplored Locations), offered as a small symbolic icon a GM can
// pick as a Location entity's own "portrait" — direct follow-up request:
// "create simple drawing icons representing the types of locations that
// are in 5LFB that can be selected as the portrait of the location entity
// record and will be displayed in the hex." Same small/genre-neutral/
// single-glyph posture as every other icon catalog here (battlemapIcons.js,
// hexcrawlIcons.js's own Threat catalog) — a real hand-drawn pen-and-ink
// set isn't something this tool can hand-author convincingly (same
// constraint noted for Hexcrawl's Geography icons before a real source
// sprite sheet was supplied to crop from); these are plain emoji glyphs
// instead, matching the app-wide convention.
//
// Shown as a picker in the Entity Editor for a Location entity only while
// Five Leagues is the active ruleset (settings.statRuleset ===
// 'fiveleagues' — see entityLocationTypeIconPicker, drawers/index.js), and
// stored on the entity as `locationTypeIcon` (a plain field via
// updateEntity, same as any other simple entity field — no dedicated
// domain mutator needed). Resolved at render time in the Hexcrawl grid's
// own center-icon slot (hexcrawlGrid) as a fallback UNDER a real uploaded
// Gallery thumbnail (entity.thumbnailId) but ABOVE the plain initial-letter
// fallback.
const FIVELEAGUES_LOCATION_TYPE_ICONS = [
  { key: 'settlement', label: 'Settlement', glyph: '🏘️' },
  { key: 'enemy-camp', label: 'Enemy Camp', glyph: '⛺' },
  { key: 'enemy-hideout', label: 'Enemy Hideout', glyph: '🕳️' },
  { key: 'delve', label: 'Delve', glyph: '🏚️' },
  { key: 'monster-lair', label: 'Monster Lair', glyph: '🐾' },
  { key: 'unexplored', label: 'Unexplored Location', glyph: '❓' },
];

function findLocationTypeIcon(key) {
  return FIVELEAGUES_LOCATION_TYPE_ICONS.find((i) => i.key === key) || null;
}

exports.FIVELEAGUES_LOCATION_TYPE_ICONS = FIVELEAGUES_LOCATION_TYPE_ICONS;
exports.findLocationTypeIcon = findLocationTypeIcon;

});

